window.ETSDATA=window.ETSDATA||{};window.ETSDATA[11]={"lc":{"p1":[{"n":1,"opts":["She's eating in a picnic area.","She's waiting in line at a food truck.","She's wiping off a bench.","She's throwing away a plate."],"vi":["Cô ấy đang ăn ở khu dã ngoại.","Cô ấy đang xếp hàng chờ ở một xe bán đồ ăn.","Cô ấy đang lau một băng ghế.","Cô ấy đang vứt một cái đĩa."],"ans":"A","xp":"Ảnh chụp một người phụ nữ đang ngồi ăn ở bàn ngoài trời (khu picnic) → (A) đúng.\n(B) không có xe bán đồ ăn hay hàng người chờ; (C) cô ấy không lau ghế (wipe off); (D) cô ấy không vứt đĩa (throw away).","a":"E24-T01-01.mp3","img":"q1.jpg"},{"n":2,"opts":["The man is brushing snow off the roof of a car.","The man is standing in the snow beside a car.","The man is shoveling snow from a walkway.","The man is running through the snow."],"vi":["Người đàn ông đang phủi tuyết khỏi nóc xe hơi.","Người đàn ông đang đứng trong tuyết bên cạnh một chiếc xe hơi.","Người đàn ông đang xúc tuyết khỏi lối đi.","Người đàn ông đang chạy qua tuyết."],"ans":"B","xp":"Người đàn ông đang đứng trong tuyết, cạnh chiếc xe (standing ... beside a car) → (B) đúng.\n(A) anh ấy không phủi tuyết trên nóc xe (brush off); (C) không xúc tuyết bằng xẻng (shovel); (D) không chạy (running).","a":"E24-T01-02.mp3","img":"q2.jpg"},{"n":3,"opts":["Some workers are hanging art in a gallery.","Two of the people are having a conversation.","One of the men is rearranging cushions on a sofa.","One of the men is painting a picture."],"vi":["Một số công nhân đang treo tranh trong phòng trưng bày.","Hai người trong số đó đang trò chuyện.","Một trong những người đàn ông đang sắp xếp lại gối trên ghế sofa.","Một trong những người đàn ông đang vẽ tranh."],"ans":"B","xp":"Trong phòng trưng bày, hai người đứng bên trái đang nói chuyện với nhau (having a conversation) → (B) đúng.\n(A) không ai đang treo tranh (hanging art); (C) không thấy gối (cushions) trong ảnh; (D) không ai đang vẽ tranh (painting).","a":"E24-T01-03.mp3","img":"q3.jpg"},{"n":4,"opts":["Vehicles are entering a parking garage.","Clothes hangers are scattered on the ground.","Empty racks are lined up next to a building.","Clothing is being displayed under a tent."],"vi":["Xe cộ đang đi vào bãi đỗ xe.","Móc treo quần áo nằm vương vãi trên mặt đất.","Những giá treo trống được xếp hàng cạnh một tòa nhà.","Quần áo đang được trưng bày dưới một mái lều."],"ans":"D","xp":"Quần áo được treo trưng bày dưới mái lều/bạt (is being displayed under a tent) → (D) đúng. Lưu ý: 'is being displayed' ở đây diễn tả TRẠNG THÁI đang được trưng bày, không cần có người.\n(A) không có xe đi vào bãi đỗ; (B) móc áo không nằm rải rác trên đất (scattered); (C) không thấy giá treo trống (empty racks).","a":"E24-T01-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Potted plants have been suspended from a ceiling.","Chairs have been stacked in front of an entryway.","A computer station has been set up on a desk.","A rug has been rolled up against a wall."],"vi":["Những chậu cây được treo lơ lửng từ trần nhà.","Những chiếc ghế được xếp chồng lên nhau trước lối vào.","Một bộ máy tính đã được lắp đặt trên bàn làm việc.","Một tấm thảm đã được cuộn lại dựa vào tường."],"ans":"C","xp":"Trên bàn có máy tính, màn hình đã được bố trí sẵn (a computer station has been set up on a desk) → (C) đúng.\n(A) chậu cây không treo từ trần (suspended from a ceiling); (B) ghế không xếp chồng (stacked); (D) không có tấm thảm cuộn lại (rolled up).","a":"E24-T01-05.mp3","img":"q5.jpg"},{"n":6,"opts":["One of the men is sweeping a patio.","One of the men is replacing some flooring.","A door has been taken off its frame.","A light fixture has been left on the ground."],"vi":["Một trong những người đàn ông đang quét sân hiên.","Một trong những người đàn ông đang thay sàn nhà.","Một cánh cửa đã được tháo ra khỏi khung.","Một bộ đèn đã bị để trên mặt đất."],"ans":"C","xp":"Cánh cửa đã được tháo khỏi khung và dựng sang một bên (has been taken off its frame) → (C) đúng.\n(A) không có sân hiên (patio) và không ai quét; (B) không ai đang thay sàn (flooring); (D) đèn đang ở trên trần, không nằm dưới đất (left on the ground).","a":"E24-T01-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"How old is this building?","qvi":"Tòa nhà này bao nhiêu năm tuổi rồi?","opts":["To ship some materials.","About ten years old.","Company offices, I think."],"vi":["Để vận chuyển một số vật liệu.","Khoảng mười năm tuổi.","Tôi nghĩ là văn phòng công ty."],"ans":"B","xp":"Câu hỏi 'How old' hỏi tuổi của tòa nhà → (B) 'khoảng 10 năm' trả lời trực tiếp.\n(A) và (C) dùng từ liên tưởng đến 'building' (materials, offices) nhưng không trả lời tuổi.","a":"E24-T01-07.mp3"},{"n":8,"q":"Can you come to my jazz performance tonight?","qvi":"Tối nay bạn có thể đến buổi biểu diễn nhạc jazz của tôi không?","opts":["I'm sorry I was late for the meeting.","Mostly just local musicians.","Sure, I'll be there!"],"vi":["Xin lỗi vì tôi đã đến họp muộn.","Chủ yếu chỉ là các nhạc sĩ địa phương.","Chắc chắn rồi, tôi sẽ đến!"],"ans":"C","xp":"Lời mời/đề nghị 'Can you come...?' → (C) 'Sure' đồng ý và nói sẽ đến.\n(A) dùng 'late' liên tưởng đến 'tonight/come'; (B) dùng 'musicians' liên tưởng đến 'jazz performance'.","a":"E24-T01-08.mp3"},{"n":9,"q":"Which apartment submitted a work order?","qvi":"Căn hộ nào đã gửi yêu cầu sửa chữa?","opts":["It's what you did for a living.","Submit your assignment here.","It came from the tenants in B23."],"vi":["Đó là công việc bạn đã làm để kiếm sống.","Hãy nộp bài tập của bạn ở đây.","Nó đến từ những người thuê nhà ở căn B23."],"ans":"C","xp":"Hỏi 'Which apartment' (căn hộ nào) → (C) nêu cụ thể: người thuê ở căn B23.\n(A) 'living' liên tưởng đến 'apartment'; (B) lặp từ gần giống 'submit'. Từ vựng: work order = phiếu/yêu cầu sửa chữa, tenant = người thuê nhà.","a":"E24-T01-09.mp3"},{"n":10,"q":"Will you contact the vendor about changing our delivery date?","qvi":"Bạn sẽ liên hệ với nhà cung cấp về việc đổi ngày giao hàng của chúng ta chứ?","opts":["Of course. I'll take care of it.","An e-mail receipt.","Could I get change for a dollar?"],"vi":["Tất nhiên rồi. Tôi sẽ lo việc đó.","Một biên lai qua e-mail.","Tôi có thể đổi tiền lẻ cho một đô la không?"],"ans":"A","xp":"Hỏi 'Will you contact...?' (bạn sẽ liên hệ chứ?) → (A) đồng ý 'Of course' và nói sẽ lo việc đó.\n(B) 'e-mail' liên tưởng đến 'contact'; (C) 'change' (tiền lẻ) là bẫy lặp âm với 'changing' (thay đổi).","a":"E24-T01-10.mp3"},{"n":11,"q":"Why was the maintenance worker here?","qvi":"Tại sao nhân viên bảo trì lại ở đây?","opts":["No, he didn't.","From three o'clock until four.","Because a light needed to be fixed."],"vi":["Không, anh ấy đã không làm.","Từ 3 giờ đến 4 giờ.","Vì một cái đèn cần được sửa."],"ans":"C","xp":"Câu hỏi 'Why' hỏi lý do → (C) 'Because...' (vì cần sửa đèn).\n(A) câu hỏi Wh- không trả lời bằng Yes/No; (B) trả lời cho câu hỏi 'How long/When'.","a":"E24-T01-11.mp3"},{"n":12,"q":"Did management make a hiring decision yet?","qvi":"Ban quản lý đã đưa ra quyết định tuyển dụng chưa?","opts":["Put it on the highest shelf.","The personnel department.","Yes, they chose Jacob Borgman."],"vi":["Hãy đặt nó lên kệ cao nhất.","Phòng nhân sự.","Rồi, họ đã chọn Jacob Borgman."],"ans":"C","xp":"Câu hỏi Yes/No 'Did ... yet?' → (C) 'Yes' và nói rõ đã chọn ai.\n(A) 'highest' có âm gần giống 'hiring'; (B) 'personnel department' liên tưởng đến 'hiring decision'.","a":"E24-T01-12.mp3"},{"n":13,"q":"Do you want to eat here in our cafeteria or go out?","qvi":"Bạn muốn ăn ở căng tin của chúng ta hay ra ngoài ăn?","opts":["He went there yesterday.","Well, maybe a sandwich.","Let's eat here."],"vi":["Anh ấy đã đến đó hôm qua.","À, có lẽ là một cái bánh sandwich.","Mình ăn ở đây đi."],"ans":"C","xp":"Câu hỏi lựa chọn (ăn ở đây HAY ra ngoài) → (C) chọn một phương án: ăn ở đây.\n(A) 'there' liên tưởng đến 'here'; (B) 'sandwich' liên tưởng đến 'cafeteria' nhưng không trả lời chọn chỗ ăn.","a":"E24-T01-13.mp3"},{"n":14,"q":"Didn't you e-mail the employment contract to Mr. Patel yesterday?","qvi":"Hôm qua bạn chưa gửi e-mail hợp đồng lao động cho ông Patel à?","opts":["Yes, I would agree.","No, I'll send it now.","Check the employee manual."],"vi":["Vâng, tôi đồng ý.","Chưa, tôi sẽ gửi ngay bây giờ.","Hãy xem sổ tay nhân viên."],"ans":"B","xp":"Câu hỏi phủ định hỏi đã gửi hợp đồng chưa → (B) 'No' (chưa) và nói sẽ gửi ngay.\n(A) không liên quan; (C) 'employee' là bẫy từ cùng gốc với 'employment'.","a":"E24-T01-14.mp3"},{"n":15,"q":"Our division's picnic is this Saturday, right?","qvi":"Buổi dã ngoại của bộ phận chúng ta là vào thứ Bảy này, đúng không?","opts":["There's a lot of rain in the forecast.","Sure, I like salad.","At the end of this corridor."],"vi":["Dự báo thời tiết nói sẽ có nhiều mưa.","Chắc chắn rồi, tôi thích salad.","Ở cuối hành lang này."],"ans":"A","xp":"Câu hỏi đuôi xác nhận buổi picnic vào thứ Bảy → (A) trả lời gián tiếp: dự báo có nhiều mưa (ngầm ý: đúng là thứ Bảy nhưng lo thời tiết xấu).\n(B) 'salad' liên tưởng đến 'picnic'; (C) trả lời câu hỏi 'Where'.","a":"E24-T01-15.mp3"},{"n":16,"q":"Would you like coffee or tea?","qvi":"Bạn muốn uống cà phê hay trà?","opts":["Just water, please.","For a few dollars more.","A fifteen-minute break."],"vi":["Cho tôi nước lọc thôi.","Thêm vài đô la nữa.","Nghỉ giải lao 15 phút."],"ans":"A","xp":"Câu hỏi lựa chọn (cà phê hay trà) → (A) chọn phương án thứ ba: chỉ nước lọc. Đây là kiểu trả lời thường gặp.\n(B) không liên quan; (C) 'break' (giờ nghỉ uống cà phê) liên tưởng đến 'coffee or tea'.","a":"E24-T01-16.mp3"},{"n":17,"q":"We achieved our sales targets this month.","qvi":"Tháng này chúng ta đã đạt chỉ tiêu doanh số.","opts":["That's excellent news!","A few times a day.","To the end of April."],"vi":["Đó là tin tuyệt vời!","Vài lần một ngày.","Đến cuối tháng Tư."],"ans":"A","xp":"Câu trần thuật báo tin tốt → (A) phản ứng phù hợp: 'Tin tuyệt vời!'.\n(B) trả lời 'How often'; (C) trả lời 'Until when'.","a":"E24-T01-17.mp3"},{"n":18,"q":"How often do you travel for your job?","qvi":"Bạn đi công tác thường xuyên như thế nào?","opts":["It turned out well.","Yes, I did find one.","About once a month."],"vi":["Mọi việc hóa ra rất tốt.","Vâng, tôi đã tìm được một cái.","Khoảng mỗi tháng một lần."],"ans":"C","xp":"'How often' hỏi tần suất → (C) 'khoảng một tháng một lần'.\n(A) 'well' liên tưởng đến 'How'; (B) câu hỏi Wh- không trả lời Yes/No.","a":"E24-T01-18.mp3"},{"n":19,"q":"We should hike the Wildflower Trail today.","qvi":"Hôm nay chúng ta nên đi bộ đường dài trên đường mòn Wildflower.","opts":["This seat is available.","I didn't bring boots.","At the visitors' center."],"vi":["Ghế này còn trống.","Tôi không mang giày ống theo.","Ở trung tâm du khách."],"ans":"B","xp":"Lời đề nghị đi leo núi → (B) từ chối gián tiếp: 'Tôi không mang giày ống' (nên không đi được).\n(A) bẫy nghe nhầm 'trail' thành 'train' → liên tưởng 'seat'; (C) trả lời câu hỏi 'Where'.","a":"E24-T01-19.mp3"},{"n":20,"q":"You've booked a hotel in London, haven't you?","qvi":"Bạn đã đặt khách sạn ở London rồi, phải không?","opts":["Very enjoyable, thanks.","He usually takes the train.","Yes, I made a reservation last week."],"vi":["Rất thú vị, cảm ơn.","Anh ấy thường đi tàu hỏa.","Vâng, tôi đã đặt phòng tuần trước."],"ans":"C","xp":"Câu hỏi đuôi xác nhận đã đặt khách sạn chưa → (C) 'Yes' + 'made a reservation' (= booked).\n(A) 'enjoyable' liên tưởng đến 'hotel'; (B) 'He' không rõ chỉ ai.","a":"E24-T01-20.mp3"},{"n":21,"q":"Are there any tickets left for tonight's concert?","qvi":"Còn vé nào cho buổi hòa nhạc tối nay không?","opts":["It's sold out.","He's a concert violinist.","They already left."],"vi":["Đã bán hết rồi.","Anh ấy là nghệ sĩ violin hòa nhạc.","Họ đã rời đi rồi."],"ans":"A","xp":"Hỏi còn vé không → (A) 'đã bán hết' = không còn vé.\n(B) lặp từ 'concert'; (C) lặp từ 'left' nhưng khác nghĩa (left = rời đi).","a":"E24-T01-21.mp3"},{"n":22,"q":"Haven't you used this software before?","qvi":"Bạn chưa từng dùng phần mềm này trước đây à?","opts":["Can I take your order?","I haven't had the chance.","About 40 dollars."],"vi":["Tôi có thể nhận order của quý khách không?","Tôi chưa có dịp.","Khoảng 40 đô la."],"ans":"B","xp":"Hỏi đã từng dùng phần mềm chưa → (B) 'chưa có dịp' = chưa dùng.\n(A) không liên quan; (C) trả lời 'How much'.","a":"E24-T01-22.mp3"},{"n":23,"q":"When is the new blender going to be released?","qvi":"Khi nào máy xay sinh tố mới sẽ được tung ra thị trường?","opts":["Only with fruits and vegetables.","In the kitchen cabinet.","The prototype is still being tested."],"vi":["Chỉ với trái cây và rau củ.","Trong tủ bếp.","Mẫu thử vẫn đang được thử nghiệm."],"ans":"C","xp":"Hỏi 'When' thời điểm ra mắt → (C) trả lời gián tiếp: mẫu thử còn đang thử nghiệm (nên chưa biết khi nào).\n(A) 'fruits and vegetables' liên tưởng đến 'blender'; (B) trả lời 'Where'.","a":"E24-T01-23.mp3"},{"n":24,"q":"Who's picking up our clients at the airport?","qvi":"Ai sẽ đón khách hàng của chúng ta ở sân bay?","opts":["They decided to drive.","At terminal 2.","It's a marketing position."],"vi":["Họ đã quyết định tự lái xe đến.","Ở nhà ga số 2.","Đó là một vị trí marketing."],"ans":"A","xp":"Hỏi 'Who' sẽ đón khách → (A) trả lời gián tiếp: khách tự lái xe nên không cần ai đón.\n(B) 'terminal' liên tưởng đến 'airport' (trả lời Where); (C) 'position' liên tưởng đến 'Who'.","a":"E24-T01-24.mp3"},{"n":25,"q":"Where are the red roses that came in this morning?","qvi":"Những bông hồng đỏ được giao đến sáng nay đâu rồi?","opts":["About three liters of water.","No, I didn't check out the sale.","I needed some for a large bouquet."],"vi":["Khoảng ba lít nước.","Không, tôi chưa xem đợt giảm giá.","Tôi cần dùng một ít cho một bó hoa lớn."],"ans":"C","xp":"Hỏi 'Where' hoa hồng ở đâu → (C) trả lời gián tiếp: tôi đã dùng chúng để làm một bó hoa lớn.\n(A) 'water' liên tưởng đến 'roses'; (B) câu hỏi Wh- không trả lời bằng No.","a":"E24-T01-25.mp3"},{"n":26,"q":"This film has been nominated for several awards.","qvi":"Bộ phim này đã được đề cử cho một vài giải thưởng.","opts":["Why don't we go see it?","After the announcement.","He made a great speech."],"vi":["Sao chúng ta không đi xem nhỉ?","Sau khi công bố.","Anh ấy đã có một bài phát biểu tuyệt vời."],"ans":"A","xp":"Câu trần thuật về bộ phim được đề cử → (A) phản hồi tự nhiên: rủ đi xem phim đó.\n(B) 'announcement' liên tưởng đến 'awards'; (C) 'He' không rõ chỉ ai.","a":"E24-T01-26.mp3"},{"n":27,"q":"Who's interested in starting a car pool program?","qvi":"Ai quan tâm đến việc khởi động chương trình đi chung xe?","opts":["Thanks, but I can't swim.","Clara's already organizing one.","It's a very interesting article."],"vi":["Cảm ơn, nhưng tôi không biết bơi.","Clara đã đang tổ chức một chương trình rồi.","Đó là một bài báo rất thú vị."],"ans":"B","xp":"Hỏi 'Who' quan tâm → (B) cho biết Clara đã đang tổ chức một chương trình đi chung xe rồi.\n(A) bẫy hiểu nhầm 'pool' là hồ bơi → 'swim'; (C) 'interesting' cùng gốc với 'interested'.","a":"E24-T01-27.mp3"},{"n":28,"q":"Where will I teach my workshop this month?","qvi":"Tháng này tôi sẽ dạy buổi hội thảo ở đâu?","opts":["We just sent an e-mail to all instructors.","Five to seven months.","Yes, it's a beautiful building."],"vi":["Chúng tôi vừa gửi e-mail cho tất cả giảng viên.","Năm đến bảy tháng.","Vâng, đó là một tòa nhà đẹp."],"ans":"A","xp":"Hỏi 'Where' → (A) trả lời gián tiếp: vừa gửi e-mail cho các giảng viên (thông tin địa điểm có trong e-mail).\n(B) 'months' liên tưởng 'month'; (C) câu hỏi Wh- không trả lời Yes.","a":"E24-T01-28.mp3"},{"n":29,"q":"Why are we moving these sweaters to the back of the store?","qvi":"Tại sao chúng ta lại chuyển những chiếc áo len này ra phía sau cửa hàng?","opts":["In the new shopping mall.","Yes, they come in other colors.","Our spring merchandise is arriving soon."],"vi":["Ở trung tâm mua sắm mới.","Vâng, chúng có màu khác nữa.","Hàng mùa xuân của chúng ta sắp về."],"ans":"C","xp":"Hỏi 'Why' → (C) nêu lý do: hàng mùa xuân sắp về (nên dồn áo len mùa đông ra sau để lấy chỗ).\n(A) 'shopping mall' liên tưởng đến 'store'; (B) câu hỏi Wh- không trả lời Yes.","a":"E24-T01-29.mp3"},{"n":30,"q":"Would you be interested in working on some of these contracts?","qvi":"Bạn có muốn đảm nhận một vài hợp đồng trong số này không?","opts":["Thank you for meeting me.","A contact lens prescription.","I have very limited time."],"vi":["Cảm ơn vì đã gặp tôi.","Một đơn thuốc kính áp tròng.","Tôi có rất ít thời gian."],"ans":"C","xp":"Lời đề nghị → (C) từ chối khéo: tôi có rất ít thời gian.\n(A) không liên quan; (B) 'contact' phát âm gần giống 'contracts'.","a":"E24-T01-30.mp3"},{"n":31,"q":"What type of job are you looking for?","qvi":"Bạn đang tìm loại công việc gì?","opts":["No, at ten A.M.","I really like working with computers.","Just a résumé is needed."],"vi":["Không, lúc 10 giờ sáng.","Tôi rất thích làm việc với máy tính.","Chỉ cần một bản sơ yếu lý lịch."],"ans":"B","xp":"Hỏi loại công việc → (B) trả lời gián tiếp: thích làm việc với máy tính (muốn công việc liên quan đến máy tính).\n(A) câu hỏi Wh- không trả lời No; (C) 'résumé' liên tưởng đến 'job'.","a":"E24-T01-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Thank you so much for organizing the annual company picnic, Jingdao. Everybody seemed to enjoy it.","Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty, Jingdao. Mọi người có vẻ rất thích."],["M","Well, we deserved it after working so hard this year.","À, chúng ta xứng đáng được như vậy sau một năm làm việc chăm chỉ."],["W","I agree. The food was great, by the way. Especially the peach pie you made. Would you mind sharing the recipe? It was delicious.","Tôi đồng ý. Nhân tiện, đồ ăn rất tuyệt. Đặc biệt là món bánh nướng nhân đào anh làm. Anh có phiền chia sẻ công thức không? Nó ngon lắm."],["M","I found the recipe online. I'll send you a link to the Web page. There's a really helpful video that walks you through all the steps. I recommend you watch it first.","Tôi tìm công thức trên mạng. Tôi sẽ gửi cho chị đường link đến trang web đó. Có một video rất hữu ích hướng dẫn chị từng bước. Tôi khuyên chị nên xem nó trước."],["W","All right, thanks.","Được rồi, cảm ơn anh."]],"qs":[{"n":32,"q":"What event does the woman mention?","qvi":"Người phụ nữ nhắc đến sự kiện nào?","opts":["A job fair","A cooking class","A fund-raiser","A company picnic"],"vi":["Hội chợ việc làm","Lớp học nấu ăn","Buổi gây quỹ","Buổi dã ngoại của công ty"],"ans":"D","xp":"Câu đầu tiên của người phụ nữ: \"Thank you so much for organizing the annual company picnic\" → sự kiện là buổi dã ngoại của công ty → (D)."},{"n":33,"q":"What does the woman ask for?","qvi":"Người phụ nữ yêu cầu điều gì?","opts":["A guest list","A dessert recipe","A business card","A promotional code"],"vi":["Danh sách khách mời","Công thức món tráng miệng","Danh thiếp","Mã khuyến mãi"],"ans":"B","xp":"Người phụ nữ nói: \"Especially the peach pie you made. Would you mind sharing the recipe?\" → xin công thức bánh nướng nhân đào. Peach pie (bánh đào) được diễn đạt lại thành 'dessert' (món tráng miệng) → (B)."},{"n":34,"q":"What does the man recommend doing?","qvi":"Người đàn ông khuyên làm gì?","opts":["Returning some merchandise","Watching a video","Creating an account","Reading a review"],"vi":["Trả lại hàng hóa","Xem một video","Tạo tài khoản","Đọc một bài đánh giá"],"ans":"B","xp":"Người đàn ông nói: \"There's a really helpful video that walks you through all the steps. I recommend you watch it first.\" → khuyên xem video trước → (B)."}],"a":"E24-T01-32-34.mp3"},{"ns":[35,37],"script":[["M","I'd like to finish calculating the company's expense reports for the month. Have you finished reviewing the travel reimbursement forms from all the departments?","Tôi muốn hoàn tất việc tính toán báo cáo chi phí của công ty trong tháng này. Chị đã xem xong các mẫu đơn hoàn tiền công tác từ tất cả các phòng ban chưa?"],["W","I'm almost done, but I have a question about a hotel receipt from one of our employees.","Tôi gần xong rồi, nhưng tôi có một thắc mắc về hóa đơn khách sạn của một nhân viên."],["M","What's the problem?","Có vấn đề gì vậy?"],["W","Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations. This one isn't on the list.","À, chính sách của chúng ta là nhân viên phải ở khách sạn nằm trong danh sách chỗ ở đã được phê duyệt. Khách sạn này không có trong danh sách."],["M","Who submitted the receipt?","Ai đã nộp hóa đơn đó?"],["W","Moritz Ziegler, one of our sales representatives.","Moritz Ziegler, một nhân viên kinh doanh của chúng ta."],["M","Hmm. He's a new employee and may have forgotten the policy. As a supervisor, I can approve the expense this one time.","Hừm. Anh ấy là nhân viên mới nên có thể đã quên chính sách. Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi này một lần."]],"qs":[{"n":35,"q":"What department do the speakers most likely work in?","qvi":"Những người nói nhiều khả năng làm việc ở phòng ban nào?","opts":["Accounting","Research and development","Maintenance","Marketing"],"vi":["Kế toán","Nghiên cứu và phát triển","Bảo trì","Marketing"],"ans":"A","xp":"Người đàn ông nói: \"I'd like to finish calculating the company's expense reports... Have you finished reviewing the travel reimbursement forms...?\" → tính báo cáo chi phí, xem đơn hoàn tiền là công việc của phòng kế toán → (A)."},{"n":36,"q":"What problem does the woman mention?","qvi":"Người phụ nữ nhắc đến vấn đề gì?","opts":["A report has not been submitted.","An invoice is not accurate.","A policy has not been followed.","An order has not been delivered."],"vi":["Một báo cáo chưa được nộp.","Một hóa đơn không chính xác.","Một chính sách đã không được tuân thủ.","Một đơn hàng chưa được giao."],"ans":"C","xp":"Người phụ nữ nói: \"our policy is for employees to stay at a hotel that's on our list of approved accommodations. This one isn't on the list.\" → nhân viên ở khách sạn ngoài danh sách = không tuân thủ chính sách → (C)."},{"n":37,"q":"What does the man say he will do?","qvi":"Người đàn ông nói anh ấy sẽ làm gì?","opts":["Delete an electronic file","Authorize a reimbursement","Set up a sales meeting","Review a spreadsheet"],"vi":["Xóa một tệp điện tử","Phê duyệt một khoản hoàn tiền","Sắp xếp một cuộc họp kinh doanh","Xem lại một bảng tính"],"ans":"B","xp":"Người đàn ông nói: \"As a supervisor, I can approve the expense this one time.\" → approve (phê duyệt) = authorize; khoản chi được hoàn lại = reimbursement → (B)."}],"a":"E24-T01-35-37.mp3"},{"ns":[38,40],"script":[["M","Good morning, Damilola. How's everything up here on deck?","Chào buổi sáng, Damilola. Mọi thứ trên boong tàu thế nào rồi?"],["W","Hi, Pedro. It was an uneventful night, and our cargo ship still hasn't moved yet.","Chào Pedro. Đêm qua không có gì đặc biệt, và tàu chở hàng của chúng ta vẫn chưa di chuyển."],["M","Hmm, I hope the fog over the harbor lifts soon.","Hừm, tôi hy vọng sương mù trên cảng sớm tan."],["W","Yeah, me too. The ship won't be able to leave until the weather improves.","Ừ, tôi cũng vậy. Tàu sẽ không thể rời đi cho đến khi thời tiết tốt hơn."],["M","I hope we won't get too far behind schedule. I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.","Hy vọng chúng ta sẽ không bị trễ lịch quá nhiều. Tôi sẽ gọi cho cơ quan quản lý cảng sớm để cập nhật khi nào chúng ta được phép rời đi."],["W","Sounds good.","Nghe hay đấy."]],"qs":[{"n":38,"q":"What industry do the speakers most likely work in?","qvi":"Những người nói nhiều khả năng làm việc trong ngành nào?","opts":["Shipping","Manufacturing","Hospitality","Meteorology"],"vi":["Vận tải biển","Sản xuất","Dịch vụ khách sạn - nhà hàng","Khí tượng học"],"ans":"A","xp":"Người phụ nữ nói: \"our cargo ship still hasn't moved yet\" (tàu chở hàng của chúng ta), cùng các từ 'deck', 'harbor', 'port authority' → họ làm trong ngành vận tải biển → (A)."},{"n":39,"q":"What is the reason for a delay?","qvi":"Lý do của sự chậm trễ là gì?","opts":["A schedule was written incorrectly.","Some equipment is not properly set up.","Weather conditions are poor.","Several staff members are absent."],"vi":["Lịch trình bị ghi sai.","Một số thiết bị không được lắp đặt đúng cách.","Điều kiện thời tiết xấu.","Một vài nhân viên vắng mặt."],"ans":"C","xp":"Người phụ nữ nói: \"The ship won't be able to leave until the weather improves.\" (và trước đó có sương mù - fog) → thời tiết xấu → (C)."},{"n":40,"q":"What does the man say he will do?","qvi":"Người đàn ông nói anh ấy sẽ làm gì?","opts":["Update a shift schedule","Clear a work space","Complete a checklist","Place a call"],"vi":["Cập nhật lịch làm ca","Dọn dẹp chỗ làm việc","Hoàn thành danh sách kiểm tra","Gọi một cuộc điện thoại"],"ans":"D","xp":"Người đàn ông nói: \"I'll be sure to call the port authority soon\" → call = place a call (gọi điện) → (D)."}],"a":"E24-T01-38-40.mp3"},{"ns":[41,43],"script":[["W","Hi. I've made a reservation to meet with some clients for lunch today. It's under Cohen.","Xin chào. Tôi đã đặt bàn để gặp một số khách hàng ăn trưa hôm nay. Đặt dưới tên Cohen."],["M","Oh, yes. I see your reservation. Welcome, Ms. Cohen.","À vâng. Tôi thấy thông tin đặt bàn của chị rồi. Chào mừng chị Cohen."],["W","I know I asked to be seated on your beautiful terrace, but it's very hot today.","Tôi biết là tôi đã yêu cầu ngồi ở sân hiên xinh đẹp của nhà hàng, nhưng hôm nay trời nóng quá."],["M","Hmm. I can seat you at table four inside. Do you mind waiting a few minutes?","Hừm. Tôi có thể xếp chị ngồi bàn số bốn bên trong. Chị có phiền đợi vài phút không?"],["W","Not at all. By the way, your parking area's nearly full. Where can I tell my clients to park?","Không sao cả. Nhân tiện, bãi đỗ xe của nhà hàng gần kín rồi. Tôi nên bảo khách hàng của tôi đỗ xe ở đâu?"],["M","Our customers can park for free in the garage across the street. Our cashier will stamp their parking tickets.","Khách của chúng tôi có thể đỗ xe miễn phí ở nhà để xe bên kia đường. Thu ngân của chúng tôi sẽ đóng dấu vào vé gửi xe của họ."],["W","Oh, great. Thanks. I'll call them and let them know.","Ồ, tuyệt quá. Cảm ơn anh. Tôi sẽ gọi báo cho họ biết."]],"qs":[{"n":41,"q":"Why is the woman at the restaurant?","qvi":"Tại sao người phụ nữ đến nhà hàng?","opts":["To celebrate a retirement","To perform an inspection","To meet with some clients","To write an article"],"vi":["Để mừng một người nghỉ hưu","Để thực hiện một cuộc kiểm tra","Để gặp một số khách hàng","Để viết một bài báo"],"ans":"C","xp":"Người phụ nữ nói: \"I've made a reservation to meet with some clients for lunch today.\" → cô ấy đến để gặp khách hàng → (C)."},{"n":42,"q":"What does the woman mean when she says, \"it's very hot today\"?","qvi":"Người phụ nữ có ý gì khi nói \"hôm nay trời rất nóng\"?","opts":["She is unable to accept an invitation.","A cooling system is not working.","A meeting will end soon.","She wants to change a seating request."],"vi":["Cô ấy không thể nhận lời mời.","Hệ thống làm mát không hoạt động.","Cuộc họp sắp kết thúc.","Cô ấy muốn thay đổi yêu cầu chỗ ngồi."],"ans":"D","xp":"Câu hỏi hàm ý. Cô ấy nói: \"I know I asked to be seated on your beautiful terrace, but it's very hot today.\" → đã đặt chỗ ngoài sân hiên nhưng trời nóng, nên muốn đổi chỗ; người đàn ông hiểu ý và đáp \"I can seat you at table four inside\" → (D)."},{"n":43,"q":"What does the man say about a parking garage?","qvi":"Người đàn ông nói gì về nhà để xe?","opts":["It is free for customers.","It is under construction.","It closes soon.","It offers monthly contracts."],"vi":["Nó miễn phí cho khách hàng.","Nó đang được xây dựng.","Nó sắp đóng cửa.","Nó có hợp đồng gửi xe theo tháng."],"ans":"A","xp":"Người đàn ông nói: \"Our customers can park for free in the garage across the street.\" → khách được đỗ xe miễn phí → (A)."}],"a":"E24-T01-41-43.mp3"},{"ns":[44,46],"script":[["W","Thank you both for coming here today to demonstrate your company's new compact printer. I know the store will be busy because we're having a big sale on laptop computers and tablets.","Cảm ơn cả hai anh đã đến đây hôm nay để giới thiệu chiếc máy in nhỏ gọn mới của công ty các anh. Tôi biết cửa hàng sẽ đông khách vì chúng tôi đang có đợt giảm giá lớn cho máy tính xách tay và máy tính bảng."],["M1","We're happy to be here. Our printers are perfect for students or people with home offices who may have limited space. My partner, Murat, will be setting up the printer station.","Chúng tôi rất vui được đến đây. Máy in của chúng tôi rất phù hợp cho sinh viên hoặc những người làm việc tại nhà có không gian hạn chế. Đồng nghiệp của tôi, Murat, sẽ lắp đặt khu trưng bày máy in."],["M2","Yes—where can I put our demonstration table?","Vâng — tôi có thể đặt bàn trình diễn của chúng tôi ở đâu?"],["W","I'll show you the area. Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.","Tôi sẽ chỉ cho anh khu vực đó. Ngoài ra, nếu các anh có mang theo tờ rơi giới thiệu, sẽ rất hữu ích nếu bày chúng ra để mọi người lấy."]],"qs":[{"n":44,"q":"Where does the woman most likely work?","qvi":"Người phụ nữ nhiều khả năng làm việc ở đâu?","opts":["At a university","At a publishing company","At an electronics store","At a grocery store"],"vi":["Ở một trường đại học","Ở một công ty xuất bản","Ở một cửa hàng điện tử","Ở một cửa hàng tạp hóa"],"ans":"C","xp":"Người phụ nữ nói: \"I know the store will be busy because we're having a big sale on laptop computers and tablets.\" → cửa hàng bán laptop, máy tính bảng = cửa hàng điện tử (electronics store) → (C)."},{"n":45,"q":"What does Murat ask about?","qvi":"Murat hỏi về điều gì?","opts":["How much an item costs","When an event will begin","How many people will participate","Where to set up some equipment"],"vi":["Một món hàng giá bao nhiêu","Khi nào sự kiện bắt đầu","Bao nhiêu người sẽ tham gia","Lắp đặt thiết bị ở đâu"],"ans":"D","xp":"Người đàn ông thứ nhất giới thiệu \"My partner, Murat, will be setting up the printer station.\" Murat (người đàn ông thứ hai) hỏi: \"where can I put our demonstration table?\" → hỏi chỗ đặt bàn/máy in = nơi lắp đặt thiết bị → (D)."},{"n":46,"q":"What does the woman suggest doing?","qvi":"Người phụ nữ đề nghị làm gì?","opts":["Offering a discount","Displaying informational materials","Holding a contest","Visiting a registration table"],"vi":["Giảm giá","Trưng bày tài liệu thông tin","Tổ chức một cuộc thi","Ghé bàn đăng ký"],"ans":"B","xp":"Người phụ nữ nói: \"if you brought any brochures with you, it'll be helpful to put those out for people to take.\" → brochures (tờ rơi) = informational materials; put out = display (bày ra) → (B)."}],"a":"E24-T01-44-46.mp3"},{"ns":[47,49],"script":[["W1","Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season. Any thoughts on what we should be concentrating on going forward?","Gizem và Hector, tôi rất hài lòng với doanh số các nhãn hàng bánh ngọt, bánh nướng và bánh quy của chúng ta trong mùa lễ vừa qua. Hai bạn có ý kiến gì về việc chúng ta nên tập trung vào điều gì sắp tới không?"],["W2","The biggest trend right now is the reduction of sugar. The public wants healthier products, but the same great taste. That'll be our biggest challenge.","Xu hướng lớn nhất hiện nay là giảm đường. Công chúng muốn sản phẩm lành mạnh hơn nhưng vẫn ngon như cũ. Đó sẽ là thách thức lớn nhất của chúng ta."],["M","One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.","Một trong những nhà cung cấp nguyên liệu của chúng ta gần đây đã bắt đầu bán một loại chất tạo ngọt làm hoàn toàn từ nguyên liệu tự nhiên."],["W1","Are there similar ones on the market? And how do they compare?","Trên thị trường có loại nào tương tự không? Và so sánh với nhau thì thế nào?"],["M","I'd have to do some investigation to find out more about that. I have some time available tomorrow afternoon.","Tôi sẽ phải tìm hiểu thêm về việc đó. Chiều mai tôi có chút thời gian rảnh."]],"qs":[{"n":47,"q":"What type of industry do the speakers most likely work in?","qvi":"Những người nói nhiều khả năng làm việc trong ngành nào?","opts":["Textile manufacturing","Food production","Health care","Hospitality"],"vi":["Sản xuất dệt may","Sản xuất thực phẩm","Chăm sóc sức khỏe","Dịch vụ khách sạn - nhà hàng"],"ans":"B","xp":"Người phụ nữ thứ nhất nói: \"I'm very pleased with the sales of our brands of cakes, pies, and cookies\" → công ty sản xuất bánh = ngành sản xuất thực phẩm (food production) → (B)."},{"n":48,"q":"What business challenge are the speakers discussing?","qvi":"Những người nói đang thảo luận về thách thức kinh doanh nào?","opts":["Lack of qualified personnel","Rising production costs","Changes in consumer preferences","Increased competition"],"vi":["Thiếu nhân sự có trình độ","Chi phí sản xuất tăng","Sự thay đổi trong sở thích của người tiêu dùng","Cạnh tranh gia tăng"],"ans":"C","xp":"Người phụ nữ thứ hai nói: \"The public wants healthier products, but the same great taste. That'll be our biggest challenge.\" → công chúng muốn sản phẩm lành mạnh hơn = sở thích người tiêu dùng thay đổi → (C)."},{"n":49,"q":"What does the man say he will do?","qvi":"Người đàn ông nói anh ấy sẽ làm gì?","opts":["Research more information","Negotiate a discount","Upgrade some machinery","Train a new employee"],"vi":["Tìm hiểu thêm thông tin","Thương lượng giảm giá","Nâng cấp máy móc","Đào tạo nhân viên mới"],"ans":"A","xp":"Người đàn ông nói: \"I'd have to do some investigation to find out more about that.\" → do some investigation (điều tra, tìm hiểu) = research → (A)."}],"a":"E24-T01-47-49.mp3"},{"ns":[50,52],"script":[["M","Hi, Bianca. I'm calling to see if you'd have time to work on a project for my marketing firm. We've expanded a lot in the past year, and we need some help.","Chào Bianca. Tôi gọi để xem chị có thời gian làm một dự án cho công ty marketing của tôi không. Năm qua chúng tôi đã mở rộng rất nhiều và chúng tôi cần người giúp."],["W","Thanks for thinking of me. What type of work would I be doing?","Cảm ơn anh đã nghĩ đến tôi. Tôi sẽ làm loại công việc gì?"],["M","Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites. You'd be overseeing the campaign.","À, chúng tôi có một khách hàng mới ở Brazil muốn thực hiện một chiến dịch marketing trên các trang mạng xã hội. Chị sẽ giám sát chiến dịch đó."],["W","Oh, I have experience with that. Why don't you send me a detailed description of the work? That'll give me an idea of how much time this project will take.","Ồ, tôi có kinh nghiệm về việc đó. Sao anh không gửi cho tôi bản mô tả chi tiết công việc nhỉ? Như vậy tôi sẽ biết dự án này sẽ mất bao nhiêu thời gian."]],"qs":[{"n":50,"q":"Why is the man calling?","qvi":"Tại sao người đàn ông gọi điện?","opts":["To explain a business merger","To describe a new company policy","To offer the woman a work assignment","To invite the woman to speak at a conference"],"vi":["Để giải thích về việc sáp nhập doanh nghiệp","Để mô tả một chính sách mới của công ty","Để giao cho người phụ nữ một công việc","Để mời người phụ nữ phát biểu tại một hội nghị"],"ans":"C","xp":"Người đàn ông nói: \"I'm calling to see if you'd have time to work on a project for my marketing firm.\" → mời cô ấy làm một dự án = đề nghị một công việc (work assignment) → (C)."},{"n":51,"q":"What does the man say a client is interested in doing?","qvi":"Người đàn ông nói khách hàng quan tâm đến việc gì?","opts":["Purchasing another business","Finding a new office space","Revising a budget proposal","Creating a marketing campaign"],"vi":["Mua lại một doanh nghiệp khác","Tìm văn phòng mới","Sửa đổi đề xuất ngân sách","Thực hiện một chiến dịch marketing"],"ans":"D","xp":"Người đàn ông nói: \"we have a new client in Brazil who's interested in creating a marketing campaign for social media sites\" → (D)."},{"n":52,"q":"What does the woman ask the man to send?","qvi":"Người phụ nữ yêu cầu người đàn ông gửi gì?","opts":["A project description","An event invitation","Some social media links","Some contact information"],"vi":["Bản mô tả dự án","Thư mời sự kiện","Một số đường link mạng xã hội","Thông tin liên lạc"],"ans":"A","xp":"Người phụ nữ nói: \"Why don't you send me a detailed description of the work?\" → bản mô tả chi tiết công việc = bản mô tả dự án → (A)."}],"a":"E24-T01-50-52.mp3"},{"ns":[53,55],"script":[["W","Hey, Koji? We were about to pack van number five for the music festival when we noticed it's got a flat tire.","Này Koji? Chúng tôi đang định chất đồ lên xe van số năm để đi lễ hội âm nhạc thì phát hiện xe bị xẹp lốp."],["M","Oh. That's not good.","Ồ. Không ổn rồi."],["W","We're supposed to get there by eleven to set up lunch for the performers. Is there another van we can take?","Chúng tôi phải đến đó trước 11 giờ để chuẩn bị bữa trưa cho các nghệ sĩ biểu diễn. Có chiếc xe van nào khác chúng tôi có thể dùng không?"],["M","Let me see what's available. We've got a lot of catering jobs today. Ah, yes—we can use van number three. Do you need help loading?","Để tôi xem còn xe nào. Hôm nay chúng ta có rất nhiều việc phục vụ tiệc. À, có rồi — chúng ta có thể dùng xe van số ba. Chị có cần giúp chất đồ lên xe không?"],["W","Yes, thanks. The food's already in coolers, but everything's in the kitchen with the serving utensils and napkins. It all needs to be brought to the parking area.","Có, cảm ơn anh. Đồ ăn đã được cho vào thùng giữ lạnh, nhưng tất cả đều đang ở trong bếp cùng với dụng cụ phục vụ và khăn ăn. Tất cả cần được mang ra bãi đỗ xe."],["M","All right; I can help with that.","Được rồi, tôi có thể giúp việc đó."]],"qs":[{"n":53,"q":"What problem does the woman mention?","qvi":"Người phụ nữ nhắc đến vấn đề gì?","opts":["A vehicle is out of service.","An employee is late.","A shipment was damaged.","Traffic is heavy."],"vi":["Một chiếc xe không sử dụng được.","Một nhân viên đến muộn.","Một lô hàng bị hư hỏng.","Giao thông đông đúc."],"ans":"A","xp":"Người phụ nữ nói: \"We were about to pack van number five ... when we noticed it's got a flat tire.\" → xe van (vehicle) bị xẹp lốp = không dùng được (out of service) → (A)."},{"n":54,"q":"Where do the speakers most likely work?","qvi":"Những người nói nhiều khả năng làm việc ở đâu?","opts":["At a recording studio","At a catering company","At a radio station","At a car dealership"],"vi":["Ở phòng thu âm","Ở công ty dịch vụ ăn uống (catering)","Ở đài phát thanh","Ở đại lý bán xe hơi"],"ans":"B","xp":"Người đàn ông nói: \"We've got a lot of catering jobs today.\" và họ chuẩn bị bữa trưa cho nghệ sĩ → công ty cung cấp dịch vụ ăn uống → (B)."},{"n":55,"q":"What does the man say he will do next?","qvi":"Người đàn ông nói tiếp theo anh ấy sẽ làm gì?","opts":["Arrange for a car repair","Order some kitchen supplies","Carry some items","Offer a refund"],"vi":["Sắp xếp sửa xe","Đặt mua đồ dùng nhà bếp","Mang vác một số đồ","Hoàn tiền"],"ans":"C","xp":"Người phụ nữ nói mọi thứ trong bếp \"needs to be brought to the parking area\", người đàn ông đáp: \"All right; I can help with that.\" → anh ấy sẽ giúp mang đồ ra bãi xe → (C)."}],"a":"E24-T01-53-55.mp3"},{"ns":[56,58],"script":[["M","Thanks for taking my call. As I mentioned in my e-mail, I'm interested in working in your field. But I'm talking to some professionals first so I can find out more about it.","Cảm ơn chị đã nghe máy. Như tôi đã nói trong e-mail, tôi quan tâm đến việc làm trong lĩnh vực của chị. Nhưng trước tiên tôi đang nói chuyện với một số người trong nghề để tìm hiểu thêm."],["W","Happy to help.","Rất vui được giúp."],["M","So how did you get your start?","Vậy chị đã bắt đầu sự nghiệp như thế nào?"],["W","Oh, my family always subscribed to three newspapers. So I always thought the news was important. At my university, I joined the newspaper and eventually worked my way up to being an editor.","Ồ, gia đình tôi luôn đặt mua ba tờ báo. Vì vậy tôi luôn nghĩ tin tức rất quan trọng. Ở trường đại học, tôi tham gia tờ báo của trường và dần dần phấn đấu trở thành biên tập viên."],["M","Wow. Is it true that people in the news business work very long hours? So what's your schedule like?","Chà. Có đúng là người làm trong ngành tin tức phải làm việc rất nhiều giờ không? Vậy lịch làm việc của chị như thế nào?"]],"qs":[{"n":56,"q":"Why is the man calling the woman?","qvi":"Tại sao người đàn ông gọi cho người phụ nữ?","opts":["To plan a company event","To confirm a work deadline","To discuss a career path","To accept a job offer"],"vi":["Để lên kế hoạch cho sự kiện công ty","Để xác nhận hạn chót công việc","Để trao đổi về con đường sự nghiệp","Để nhận lời mời làm việc"],"ans":"C","xp":"Người đàn ông nói: \"I'm interested in working in your field. But I'm talking to some professionals first so I can find out more about it.\" → anh ấy muốn tìm hiểu về nghề = thảo luận con đường sự nghiệp → (C)."},{"n":57,"q":"Who most likely is the woman?","qvi":"Người phụ nữ nhiều khả năng là ai?","opts":["A newspaper editor","A university professor","A delivery person","A professional actor"],"vi":["Biên tập viên báo","Giáo sư đại học","Nhân viên giao hàng","Diễn viên chuyên nghiệp"],"ans":"A","xp":"Người phụ nữ nói: \"At my university, I joined the newspaper and eventually worked my way up to being an editor.\" → cô ấy là biên tập viên báo → (A). (B) là bẫy vì có từ 'university'."},{"n":58,"q":"What will the woman most likely do next?","qvi":"Người phụ nữ nhiều khả năng sẽ làm gì tiếp theo?","opts":["Negotiate a contract","Explain an office policy","Review a résumé","Describe a work schedule"],"vi":["Thương lượng hợp đồng","Giải thích chính sách văn phòng","Xem xét sơ yếu lý lịch","Mô tả lịch làm việc"],"ans":"D","xp":"Câu cuối người đàn ông hỏi: \"So what's your schedule like?\" → tiếp theo người phụ nữ sẽ mô tả lịch làm việc của mình → (D)."}],"a":"E24-T01-56-58.mp3"},{"ns":[59,61],"script":[["M","Hi, Karen! I just read the article on the company Web site about the proposed merger with QZ Corporation. It looks like we're going ahead with it.","Chào Karen! Tôi vừa đọc bài viết trên trang web công ty về đề xuất sáp nhập với Tập đoàn QZ. Có vẻ như chúng ta sẽ tiến hành việc đó."],["W","There would be a lot of advantages to merging operations, although they also talked about it last year.","Việc hợp nhất hoạt động sẽ có nhiều lợi ích, mặc dù năm ngoái họ cũng đã nói về chuyện đó rồi."],["M","I remember that. But there were a lot of details to work out—like whether our offices would stay in Chicago. Now it looks like we won't be relocating.","Tôi nhớ chứ. Nhưng có nhiều chi tiết cần giải quyết — như văn phòng của chúng ta có ở lại Chicago hay không. Giờ thì có vẻ chúng ta sẽ không phải chuyển đi."],["W","Well, I really don't want to move, so that's a relief.","Chà, tôi thực sự không muốn chuyển đi, nên thật nhẹ nhõm."]],"qs":[{"n":59,"q":"What are the speakers mainly discussing?","qvi":"Những người nói chủ yếu đang thảo luận về điều gì?","opts":["A new transportation route","A company merger","A public relations initiative","A medical facility design"],"vi":["Một tuyến vận chuyển mới","Việc sáp nhập công ty","Một kế hoạch quan hệ công chúng","Thiết kế một cơ sở y tế"],"ans":"B","xp":"Người đàn ông mở đầu: \"I just read the article ... about the proposed merger with QZ Corporation.\" và cả cuộc hội thoại nói về việc sáp nhập → (B)."},{"n":60,"q":"Why does the woman say, \"they also talked about it last year\"?","qvi":"Tại sao người phụ nữ nói \"năm ngoái họ cũng đã nói về chuyện đó\"?","opts":["To express doubt","To explain a process","To make a recommendation","To update some information"],"vi":["Để bày tỏ sự nghi ngờ","Để giải thích một quy trình","Để đưa ra lời khuyên","Để cập nhật thông tin"],"ans":"A","xp":"Câu hỏi hàm ý. Người đàn ông nói \"It looks like we're going ahead with it.\" Người phụ nữ đáp việc sáp nhập có nhiều lợi ích \"although they also talked about it last year\" → năm ngoái cũng nói vậy mà không thành, nên cô ấy nghi ngờ lần này có thật sự tiến hành không → (A)."},{"n":61,"q":"What does the woman want to avoid?","qvi":"Người phụ nữ muốn tránh điều gì?","opts":["Paying a certification fee","Training additional staff","Upgrading some technology","Relocating to another city"],"vi":["Trả phí cấp chứng chỉ","Đào tạo thêm nhân viên","Nâng cấp công nghệ","Chuyển đến thành phố khác"],"ans":"D","xp":"Người đàn ông nói: \"Now it looks like we won't be relocating.\" Người phụ nữ đáp: \"I really don't want to move, so that's a relief.\" → cô ấy không muốn chuyển đi (khỏi Chicago) = chuyển đến thành phố khác → (D)."}],"a":"E24-T01-59-61.mp3"},{"ns":[62,64],"script":[["M","Thanks for calling Customized Concepts. How can I help you?","Cảm ơn quý khách đã gọi đến Customized Concepts. Tôi có thể giúp gì cho quý khách?"],["W","My company wants to give every employee a gift, something useful but not too big. Since we're about to host our annual staff basketball tournament, I thought a water bottle might be good.","Công ty tôi muốn tặng quà cho mỗi nhân viên, thứ gì đó hữu ích nhưng không quá lớn. Vì chúng tôi sắp tổ chức giải bóng rổ thường niên cho nhân viên, tôi nghĩ một chiếc bình nước có thể sẽ hợp."],["M","We carry a few drink containers. If you're at our Web site, you'll see them under the Lifestyle tab.","Chúng tôi có bán một vài loại bình đựng đồ uống. Nếu chị đang ở trang web của chúng tôi, chị sẽ thấy chúng trong mục Lifestyle."],["W","Let me pull it up now... All right.","Để tôi mở trang đó ra... Được rồi."],["M","I recommend the metal bottle with the wide-mouthed lid. It's easier to clean than the one with the straw.","Tôi khuyên chị chọn bình kim loại có nắp miệng rộng. Nó dễ rửa hơn loại có ống hút."],["W","OK, thanks. And you could put our company logo on it, right?","Được, cảm ơn anh. Và anh có thể in logo công ty chúng tôi lên đó, đúng không?"],["M","Yes. You'll just need to send me the graphic file.","Vâng. Chị chỉ cần gửi cho tôi tệp hình ảnh."],["W","I can do that.","Tôi làm được."]],"qs":[{"n":62,"q":"Who is a gift for?","qvi":"Món quà dành cho ai?","opts":["Donors","Volunteers","Employees","Clients"],"vi":["Nhà tài trợ","Tình nguyện viên","Nhân viên","Khách hàng"],"ans":"C","xp":"Người phụ nữ nói: \"My company wants to give every employee a gift\" → quà dành cho nhân viên → (C)."},{"n":63,"q":"Look at the graphic. What is the price of the item the man recommends?","qvi":"Hãy nhìn hình. Món đồ người đàn ông giới thiệu có giá bao nhiêu?","opts":["$21","$18","$24","$15"],"vi":["21 đô la","18 đô la","24 đô la","15 đô la"],"ans":"C","xp":"Người đàn ông nói: \"I recommend the metal bottle with the wide-mouthed lid.\" Trên hình, bình kim loại nắp miệng rộng là 'Wide-Mouthed Steel Water Bottle' giá $24 → (C)."},{"n":64,"q":"What is the woman going to send to the man?","qvi":"Người phụ nữ sẽ gửi gì cho người đàn ông?","opts":["A graphic file","A list of names","A delivery address","An account number"],"vi":["Một tệp hình ảnh","Một danh sách tên","Một địa chỉ giao hàng","Một số tài khoản"],"ans":"A","xp":"Người đàn ông nói: \"You'll just need to send me the graphic file.\" Người phụ nữ đáp: \"I can do that.\" → cô ấy sẽ gửi tệp hình ảnh (logo) → (A)."}],"a":"E24-T01-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["W","Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week. The files'll be loaded onto the audio devices tomorrow.","Yun, tôi vừa thu âm xong phần hướng dẫn bằng âm thanh cho các bức tranh vẽ chì sẽ có mặt trong triển lãm nghệ thuật hiện đại tuần tới. Các tệp sẽ được tải vào thiết bị nghe vào ngày mai."],["M","That's great. But, unfortunately, we have to make one change. The drawing by Claudia Hoffman will no longer be in the exhibit. There was a scheduling mix-up, and it was promised to another museum starting next week.","Tuyệt quá. Nhưng tiếc là chúng ta phải thay đổi một chỗ. Bức tranh của Claudia Hoffman sẽ không còn trong triển lãm nữa. Đã có sự nhầm lẫn về lịch, và bức tranh đã được hứa cho một bảo tàng khác mượn bắt đầu từ tuần sau."],["W","Oh, that's too bad. That was one of my favorite pieces. Will you put anything in its place?","Ôi, tiếc quá. Đó là một trong những tác phẩm tôi thích nhất. Anh có đặt tác phẩm nào khác vào chỗ đó không?"],["M","No. We'll just remove it.","Không. Chúng ta sẽ chỉ bỏ nó ra thôi."],["W","OK, then I'll make that change to the audio-guide recording. I'll do that right away.","Được, vậy tôi sẽ sửa lại phần thu âm hướng dẫn. Tôi sẽ làm ngay."]],"qs":[{"n":65,"q":"What type of art will be displayed in an exhibit?","qvi":"Loại tác phẩm nghệ thuật nào sẽ được trưng bày trong triển lãm?","opts":["Clay sculptures","Oil paintings","Black-and-white photographs","Pencil drawings"],"vi":["Tượng đất sét","Tranh sơn dầu","Ảnh đen trắng","Tranh vẽ bút chì"],"ans":"D","xp":"Người phụ nữ nói: \"I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week.\" → (D)."},{"n":66,"q":"Look at the graphic. Which piece of artwork will no longer be included?","qvi":"Hãy nhìn bảng. Tác phẩm nào sẽ không còn được trưng bày nữa?","opts":["A Careful Glance","Promises","Stormy Sea","The Moment"],"vi":["A Careful Glance (Cái nhìn cẩn trọng)","Promises (Những lời hứa)","Stormy Sea (Biển bão)","The Moment (Khoảnh khắc)"],"ans":"C","xp":"Người đàn ông nói: \"The drawing by Claudia Hoffman will no longer be in the exhibit.\" Trong bảng, tác phẩm của Claudia Hoffman là 'Stormy Sea' → (C)."},{"n":67,"q":"What does the woman say she will do right away?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì ngay lập tức?","opts":["Speak with an artist","Edit a recording","Clean a gallery space","Greet some visitors"],"vi":["Nói chuyện với một họa sĩ","Chỉnh sửa bản thu âm","Dọn dẹp không gian phòng trưng bày","Chào đón khách tham quan"],"ans":"B","xp":"Người phụ nữ nói: \"then I'll make that change to the audio-guide recording. I'll do that right away.\" → make that change (sửa đổi) = edit; audio-guide recording = a recording → (B)."}],"a":"E24-T01-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","I'm glad we were assigned to cover the press conference earlier today. I counted seven other major media networks there, in addition to ours.","Tôi mừng là chúng ta được giao đưa tin về buổi họp báo sáng nay. Tôi đếm được bảy hãng truyền thông lớn khác ở đó, ngoài hãng của chúng ta."],["W","Well, the offshore wind industry is going to transform the way this region gets its power.","Chà, ngành điện gió ngoài khơi sẽ thay đổi hoàn toàn cách khu vực này có được nguồn điện."],["M","Agreed. Let's compare our facts before we start writing.","Đồng ý. Chúng ta hãy đối chiếu thông tin trước khi bắt đầu viết bài."],["W","So the largest cluster of wind turbines—off the coast of Winston—is already built. The other sites are at different stages of construction, though Lanchester is also close to being done.","Vậy cụm tua-bin gió lớn nhất — ngoài khơi Winston — đã được xây xong. Các địa điểm khác đang ở những giai đoạn xây dựng khác nhau, dù Lanchester cũng sắp hoàn thành."],["M","Right. And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.","Đúng vậy. Và tôi nghĩ điều quan trọng là chúng ta tập trung vào việc có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực nhờ dự án này."]],"qs":[{"n":68,"q":"Who most likely are the speakers?","qvi":"Những người nói nhiều khả năng là ai?","opts":["Urban planners","Journalists","Engineers","Environmental scientists"],"vi":["Nhà quy hoạch đô thị","Nhà báo","Kỹ sư","Nhà khoa học môi trường"],"ans":"B","xp":"Người đàn ông nói: \"I'm glad we were assigned to cover the press conference earlier today.\" và \"Let's compare our facts before we start writing.\" → được giao đưa tin họp báo, viết bài → họ là nhà báo → (B)."},{"n":69,"q":"Look at the graphic. Which site has already been completed?","qvi":"Hãy nhìn bản đồ. Địa điểm nào đã được hoàn thành?","opts":["Site A","Site B","Site C","Site D"],"vi":["Địa điểm A","Địa điểm B","Địa điểm C","Địa điểm D"],"ans":"D","xp":"Người phụ nữ nói: \"the largest cluster of wind turbines—off the coast of Winston—is already built.\" Trên bản đồ, địa điểm ngoài khơi Winston (cũng là cụm lớn nhất, 70 tua-bin) là Site D → (D)."},{"n":70,"q":"What does the man suggest focusing on?","qvi":"Người đàn ông đề nghị tập trung vào điều gì?","opts":["Work opportunities","Wind turbine costs","Supply chain issues","Power capacity"],"vi":["Cơ hội việc làm","Chi phí tua-bin gió","Vấn đề chuỗi cung ứng","Công suất điện"],"ans":"A","xp":"Người đàn ông nói: \"it's crucial for us to focus on how many new jobs ... are opening up in the area\" → new jobs (việc làm mới) = work opportunities → (A)."}],"a":"E24-T01-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","You have reached the information line for the Cranbury Apartments management office. On Monday, April twelfth, maintenance work will begin to repave the entire parking area adjacent to our building's main entrance. All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday. Any vehicle still in its spot after eight A.M. will be towed at the owner's expense. A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.","Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý Chung cư Cranbury. Vào thứ Hai, ngày 12 tháng 4, công việc bảo trì sẽ bắt đầu để trải lại mặt đường toàn bộ khu đỗ xe cạnh lối vào chính của tòa nhà. Tất cả cư dân Cranbury cần di chuyển xe khỏi chỗ đỗ được chỉ định trước 8 giờ sáng thứ Hai. Bất kỳ xe nào vẫn còn ở chỗ đỗ sau 8 giờ sáng sẽ bị kéo đi và chủ xe phải chịu chi phí. Bản đồ các địa điểm đỗ xe thay thế đã được gửi qua bưu điện cho cư dân vào tuần trước và cũng được dán ở sảnh tòa nhà."]],"qs":[{"n":71,"q":"Who has recorded the message?","qvi":"Ai đã ghi âm tin nhắn này?","opts":["A city mayor's office","A maintenance department","An automobile dealership","A building management office"],"vi":["Văn phòng thị trưởng thành phố","Bộ phận bảo trì","Đại lý ô tô","Văn phòng quản lý tòa nhà"],"ans":"D","xp":"Câu đầu: \"You have reached the information line for the Cranbury Apartments management office.\" → văn phòng quản lý chung cư = văn phòng quản lý tòa nhà → (D). (B) là bẫy vì có từ 'maintenance work'."},{"n":72,"q":"What are the listeners asked to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Move their vehicles","Pay their parking fines","Use an alternate entrance","Participate in a meeting"],"vi":["Di chuyển xe của họ","Nộp tiền phạt đỗ xe","Sử dụng lối vào khác","Tham gia một cuộc họp"],"ans":"A","xp":"Người nói: \"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday.\" → (A)."},{"n":73,"q":"What does the speaker say was mailed last week?","qvi":"Người nói cho biết thứ gì đã được gửi qua bưu điện vào tuần trước?","opts":["An election ballot","A maintenance plan","A map","A coupon"],"vi":["Phiếu bầu cử","Kế hoạch bảo trì","Bản đồ","Phiếu giảm giá"],"ans":"C","xp":"Người nói: \"A map of alternate parking sites was mailed to residents last week\" → bản đồ các chỗ đỗ xe thay thế → (C)."}],"a":"E24-T01-71-73.mp3"},{"ns":[74,76],"script":[["","Welcome to Your House Works. On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home. The first thing to do is to invest in a few special tools, like a trowel and crowbar. It's important to choose some that are high quality because you'll use them for many years. With your trowel and some roof cement, you can seal any cracks or chips. The crowbar will help you remove loose shingles that you can then replace. Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.","Chào mừng quý vị đến với chương trình Your House Works. Trong tập hôm nay, chúng ta sẽ tìm hiểu cách bảo dưỡng và sửa chữa nhỏ cho mái nhà của quý vị. Việc đầu tiên cần làm là đầu tư vào một vài dụng cụ chuyên dụng, như bay trát và xà beng. Điều quan trọng là chọn những dụng cụ chất lượng cao vì quý vị sẽ dùng chúng trong nhiều năm. Với chiếc bay và một ít xi măng lợp mái, quý vị có thể bịt kín mọi vết nứt hay vết sứt mẻ. Xà beng sẽ giúp quý vị gỡ những tấm ngói lợp bị lỏng để sau đó thay mới. Và tôi rất khuyến khích quý vị chụp ảnh mái nhà mỗi năm để có thể theo dõi tình trạng tổng thể của nó."]],"qs":[{"n":74,"q":"What is the topic of the episode?","qvi":"Chủ đề của tập chương trình là gì?","opts":["Garden landscaping","Window installation","Roof maintenance","Kitchen renovations"],"vi":["Thiết kế cảnh quan sân vườn","Lắp đặt cửa sổ","Bảo dưỡng mái nhà","Cải tạo nhà bếp"],"ans":"C","xp":"Người nói: \"On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.\" → bảo dưỡng và sửa mái nhà = roof maintenance → (C)."},{"n":75,"q":"What does the speaker emphasize about some tools?","qvi":"Người nói nhấn mạnh điều gì về một số dụng cụ?","opts":["They should be cleaned regularly.","They should be of high quality.","They were recently invented.","They can be easily stored."],"vi":["Chúng nên được lau chùi thường xuyên.","Chúng nên có chất lượng cao.","Chúng mới được phát minh gần đây.","Chúng có thể cất giữ dễ dàng."],"ans":"B","xp":"Người nói: \"It's important to choose some that are high quality because you'll use them for many years.\" → dụng cụ nên có chất lượng cao → (B)."},{"n":76,"q":"What does the speaker recommend doing every year?","qvi":"Người nói khuyên nên làm gì mỗi năm?","opts":["Treating some wood","Consulting an electrician","Taking some photos","Draining some water"],"vi":["Xử lý gỗ","Hỏi ý kiến thợ điện","Chụp một số bức ảnh","Tháo nước"],"ans":"C","xp":"Người nói: \"I highly recommend you take photos of your roof every year\" → chụp ảnh mái nhà mỗi năm → (C)."}],"a":"E24-T01-74-76.mp3"},{"ns":[77,79],"script":[["","Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory. I hope you enjoyed seeing and learning about the many species of plants and flowers we care for here. As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room. I recommend attending. Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop. I watched it recently and learned many new things about the orchid species we have right here at the conservatory.","Một lần nữa cảm ơn quý vị đã tham gia chuyến tham quan Nhà kính Wallingford xinh đẹp cùng tôi hôm nay. Hy vọng quý vị đã thích thú khi ngắm nhìn và tìm hiểu về nhiều loài cây và hoa mà chúng tôi chăm sóc ở đây. Như tôi đã nói khi bắt đầu chuyến tham quan, nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết giảng về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng. Tôi khuyên quý vị nên tham dự. Công trình của Samantha cũng đã xuất hiện trong bộ phim tài liệu tên là Orchid Caretakers, quý vị có thể mua phim qua cửa hàng quà tặng trực tuyến của nhà kính. Gần đây tôi đã xem phim và biết thêm nhiều điều mới về các loài lan mà chúng tôi có ngay tại nhà kính này."]],"qs":[{"n":77,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["A radio show host","A tour guide","A sales associate","A professor"],"vi":["Người dẫn chương trình radio","Hướng dẫn viên tham quan","Nhân viên bán hàng","Giáo sư"],"ans":"B","xp":"Câu đầu: \"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory.\" và \"As I mentioned at the beginning of the tour\" → người dẫn đoàn tham quan → (B)."},{"n":78,"q":"What will happen at two o'clock?","qvi":"Điều gì sẽ diễn ra lúc 2 giờ?","opts":["A lecture will begin.","A demonstration will be given.","An interview will be conducted.","A park will close."],"vi":["Một buổi thuyết giảng sẽ bắt đầu.","Một buổi trình diễn sẽ được thực hiện.","Một cuộc phỏng vấn sẽ được tiến hành.","Một công viên sẽ đóng cửa."],"ans":"A","xp":"Người nói: \"world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock\" → (A)."},{"n":79,"q":"What is Orchid Caretakers?","qvi":"Orchid Caretakers là gì?","opts":["A book","An album","A film","A magazine"],"vi":["Một cuốn sách","Một album nhạc","Một bộ phim","Một tạp chí"],"ans":"C","xp":"Người nói: \"Samantha's work has also been featured in a documentary film called Orchid Caretakers\" → đó là một bộ phim tài liệu → (C)."}],"a":"E24-T01-77-79.mp3"},{"ns":[80,82],"script":[["","Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center. As you know, our facilities have been in need of some repairs for quite a while. So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet. So during the concert, I want to encourage you to buy food and drinks from the concession stand. Eighty percent of the proceeds will go to construction at the Hillcaster Community Center. Enjoy the music!","Trước khi buổi hòa nhạc từ thiện bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ Trung tâm Cộng đồng Hillcaster. Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần sửa chữa từ khá lâu. Đến nay, chúng tôi đã quyên được 5.000 đô la từ tiền bán vé, nhưng vẫn chưa đạt được mục tiêu. Vì vậy, trong buổi hòa nhạc, tôi khuyến khích quý vị mua đồ ăn và thức uống tại quầy bán hàng. 80% số tiền thu được sẽ dành cho việc xây dựng tại Trung tâm Cộng đồng Hillcaster. Chúc quý vị thưởng thức âm nhạc vui vẻ!"]],"qs":[{"n":80,"q":"What event is taking place?","qvi":"Sự kiện nào đang diễn ra?","opts":["A fund-raising concert","A sports competition","A play rehearsal","An awards ceremony"],"vi":["Một buổi hòa nhạc gây quỹ","Một cuộc thi thể thao","Một buổi tập kịch","Một lễ trao giải"],"ans":"A","xp":"Câu đầu: \"Before the benefit concert begins\" → benefit concert (hòa nhạc từ thiện) = fund-raising concert (hòa nhạc gây quỹ) → (A)."},{"n":81,"q":"What does the organization plan to do?","qvi":"Tổ chức này dự định làm gì?","opts":["Change a policy","Repair a building","Select a winner","Sponsor a team"],"vi":["Thay đổi chính sách","Sửa chữa một tòa nhà","Chọn người chiến thắng","Tài trợ cho một đội"],"ans":"B","xp":"Người nói: \"our facilities have been in need of some repairs for quite a while\" và \"Eighty percent of the proceeds will go to construction at the Hillcaster Community Center\" → họ gây quỹ để sửa chữa cơ sở vật chất (facilities = a building) → (B)."},{"n":82,"q":"What does the speaker encourage the listeners to do?","qvi":"Người nói khuyến khích người nghe làm gì?","opts":["Order tickets early","Visit a community center","Purchase refreshments","Donate clothing"],"vi":["Đặt vé sớm","Ghé thăm trung tâm cộng đồng","Mua đồ ăn thức uống","Quyên góp quần áo"],"ans":"C","xp":"Người nói: \"I want to encourage you to buy food and drinks from the concession stand\" → buy food and drinks = purchase refreshments (mua đồ ăn nhẹ, thức uống) → (C)."}],"a":"E24-T01-80-82.mp3"},{"ns":[83,85],"script":[["","Thank you all for attending today's workshop. Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner. Planning and spending your time wisely is a key factor to business success. During the presentation, I'll be referring to documents from the packet you were handed as you arrived. If you don't have one yet, Erina's at the back of the room. OK then, to start off, we'll do an exercise to get to know one another better.","Cảm ơn tất cả quý vị đã tham dự hội thảo hôm nay. Erina Kimura và tôi sẽ điều hành buổi học, và chúng ta sẽ tập trung vào việc sử dụng thời gian hiệu quả với tư cách là chủ doanh nghiệp. Lên kế hoạch và sử dụng thời gian một cách khôn ngoan là yếu tố then chốt dẫn đến thành công trong kinh doanh. Trong bài thuyết trình, tôi sẽ tham khảo các tài liệu trong tập hồ sơ quý vị được phát khi đến. Nếu quý vị chưa có, Erina đang ở cuối phòng. Được rồi, để bắt đầu, chúng ta sẽ làm một bài tập để làm quen với nhau hơn."]],"qs":[{"n":83,"q":"What is the topic of the workshop?","qvi":"Chủ đề của buổi hội thảo là gì?","opts":["Time management","Public speaking","Leadership skills","Professional networking"],"vi":["Quản lý thời gian","Nói trước công chúng","Kỹ năng lãnh đạo","Xây dựng mạng lưới quan hệ nghề nghiệp"],"ans":"A","xp":"Người nói: \"we'll be focusing on using time efficiently as a business owner\" → sử dụng thời gian hiệu quả = quản lý thời gian → (A)."},{"n":84,"q":"What does the speaker imply when he says, \"Erina's at the back of the room\"?","qvi":"Người nói ngụ ý gì khi nói \"Erina đang ở cuối phòng\"?","opts":["A guest speaker has just arrived.","Assistance is available.","Attendees should speak clearly and loudly.","An extra chair should be provided."],"vi":["Một diễn giả khách mời vừa đến.","Có người sẵn sàng hỗ trợ.","Người tham dự nên nói rõ ràng và to.","Cần cung cấp thêm một chiếc ghế."],"ans":"B","xp":"Câu hỏi hàm ý. Người nói: \"I'll be referring to documents from the packet you were handed... If you don't have one yet, Erina's at the back of the room.\" → ai chưa có tài liệu thì đến gặp Erina để nhận = có người hỗ trợ → (B)."},{"n":85,"q":"What will the listeners do next?","qvi":"Người nghe sẽ làm gì tiếp theo?","opts":["Sign their names on a list","Take a break","Participate in an introductory activity","Fill out a questionnaire"],"vi":["Ký tên vào danh sách","Nghỉ giải lao","Tham gia một hoạt động làm quen","Điền bảng câu hỏi"],"ans":"C","xp":"Câu cuối: \"to start off, we'll do an exercise to get to know one another better\" → bài tập để làm quen với nhau = hoạt động giới thiệu/làm quen (introductory activity) → (C)."}],"a":"E24-T01-83-85.mp3"},{"ns":[86,88],"script":[["","At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls. You'll notice how vibrant the colors are, even after all these centuries. This is what the ruins are most famous for. You can still see intricate details in the artists' pictures of scenes from daily life. Now, to protect the mosaics, a roof has been constructed over the area, and the lights are dim. And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles. As we proceed, please hold on to the handrails on either side. They'll help you stay on the path and protect the ruins around us.","Tại địa điểm này, các nhà khảo cổ học đã phát hiện tàn tích của một khu chợ từ thế kỷ thứ năm với những viên gạch khảm màu sắc rực rỡ trên tường. Quý vị sẽ thấy màu sắc vẫn rực rỡ như thế nào dù đã trải qua bao nhiêu thế kỷ. Đây chính là điều khiến khu tàn tích này nổi tiếng nhất. Quý vị vẫn có thể thấy những chi tiết tinh xảo trong các bức tranh của nghệ nhân mô tả cảnh sinh hoạt hằng ngày. Để bảo vệ các bức tranh khảm, một mái che đã được xây phía trên khu vực này và đèn được để mờ. Và tôi rất tiếc, nhưng không được phép chụp ảnh vì đèn flash sẽ làm hỏng gạch. Khi chúng ta đi tiếp, xin hãy bám vào tay vịn ở hai bên. Chúng sẽ giúp quý vị đi đúng lối và bảo vệ khu tàn tích xung quanh."]],"qs":[{"n":86,"q":"What is a historical site famous for?","qvi":"Di tích lịch sử này nổi tiếng vì điều gì?","opts":["Its defensive walls","Its royal inhabitants","An event that happened there","Some artwork"],"vi":["Những bức tường phòng thủ","Những cư dân hoàng gia","Một sự kiện đã xảy ra ở đó","Một số tác phẩm nghệ thuật"],"ans":"D","xp":"Người nói: \"the remains of a fifth-century marketplace with colorful mosaic tiles on the walls... This is what the ruins are most famous for.\" → nổi tiếng nhờ tranh gạch khảm (mosaic tiles) = tác phẩm nghệ thuật → (D). (A) là bẫy vì có từ 'walls'."},{"n":87,"q":"Why does the speaker apologize?","qvi":"Tại sao người nói xin lỗi?","opts":["The listeners cannot take pictures.","An area is closed to the listeners.","There is no gift shop.","A tour started late."],"vi":["Người nghe không được chụp ảnh.","Một khu vực không mở cửa cho người nghe.","Không có cửa hàng quà tặng.","Chuyến tham quan bắt đầu muộn."],"ans":"A","xp":"Người nói: \"I'm sorry, but taking photos is not allowed\" → taking photos is not allowed = cannot take pictures → (A)."},{"n":88,"q":"What does the speaker ask the listeners to do?","qvi":"Người nói yêu cầu người nghe làm gì?","opts":["Show their tickets","Put on protective clothing","Use some handrails","Speak quietly"],"vi":["Xuất trình vé","Mặc đồ bảo hộ","Sử dụng tay vịn","Nói khẽ"],"ans":"C","xp":"Người nói: \"As we proceed, please hold on to the handrails on either side.\" → bám vào tay vịn = use some handrails → (C)."}],"a":"E24-T01-86-88.mp3"},{"ns":[89,91],"script":[["","As you all know, our agency's just won an important contract with Parker Auto Parts Company. We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month. Now, I know it's a tight schedule, but this is a priority. The client has actually started trying to work on this internally, so there's a rough ad we can start editing. Let's work on that now.","Như mọi người đều biết, công ty chúng ta vừa giành được một hợp đồng quan trọng với Công ty Phụ tùng Ô tô Parker. Chúng ta sẽ làm hai quảng cáo dài 30 giây cho các đài phát thanh địa phương, phát hành vào tháng tới, và thêm hai quảng cáo 20 giây cho tháng sau đó. Tôi biết lịch trình rất gấp, nhưng đây là việc ưu tiên. Thực ra khách hàng đã bắt đầu tự làm việc này trong nội bộ, nên đã có một bản quảng cáo nháp để chúng ta bắt đầu chỉnh sửa. Chúng ta hãy bắt tay vào làm ngay bây giờ."]],"qs":[{"n":89,"q":"What is the speaker mainly discussing?","qvi":"Người nói chủ yếu đang nói về điều gì?","opts":["An advertising campaign","A market expansion","Some contract negotiations","Some audit procedures"],"vi":["Một chiến dịch quảng cáo","Việc mở rộng thị trường","Các cuộc đàm phán hợp đồng","Các thủ tục kiểm toán"],"ans":"A","xp":"Người nói: \"We'll be developing two 30-second ads for local radio stations ... and two additional 20-second ads for the following month.\" → làm một loạt quảng cáo cho khách hàng = chiến dịch quảng cáo → (A). (C) là bẫy vì có từ 'contract' (hợp đồng đã ký xong, không còn đàm phán)."},{"n":90,"q":"What does the speaker imply when he says, \"this is a priority\"?","qvi":"Người nói ngụ ý gì khi nói \"đây là việc ưu tiên\"?","opts":["Overtime pay has been approved.","A deadline must be met.","A client expressed concern.","A supervisor will be observing closely."],"vi":["Tiền làm thêm giờ đã được phê duyệt.","Phải hoàn thành đúng hạn.","Một khách hàng đã bày tỏ lo ngại.","Một người giám sát sẽ theo dõi sát sao."],"ans":"B","xp":"Câu hỏi hàm ý. Sau khi nói các quảng cáo sẽ phát hành tháng tới, người nói: \"I know it's a tight schedule, but this is a priority.\" → lịch gấp nhưng là việc ưu tiên, nghĩa là phải kịp thời hạn → (B)."},{"n":91,"q":"What will the listeners do next?","qvi":"Người nghe sẽ làm gì tiếp theo?","opts":["View a presentation","Review a budget","Revise some work","Do some research"],"vi":["Xem một bài thuyết trình","Xem xét ngân sách","Chỉnh sửa một sản phẩm","Nghiên cứu"],"ans":"C","xp":"Người nói: \"there's a rough ad we can start editing. Let's work on that now.\" → chỉnh sửa (editing) bản quảng cáo nháp = revise some work → (C)."}],"a":"E24-T01-89-91.mp3"},{"ns":[92,94],"script":[["","Excuse me, nurses. Your attention please. I've been receiving complaints about the free snacks in the hospital break rooms. Some people have mentioned that they don't like the selection of snacks, and some have said that they don't get to eat them at all because they're gone by the time the evening shift starts. So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria. That will require management approval, but I'll keep you posted.","Xin lỗi các y tá. Xin mọi người chú ý. Tôi liên tục nhận được phàn nàn về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện. Một số người nói họ không thích các loại đồ ăn được chọn, và một số khác nói họ không được ăn chút nào vì đồ ăn đã hết trước khi ca tối bắt đầu. Vì vậy tôi đang nghĩ đến việc mỗi tháng nạp một khoản tiền vào tài khoản chi tiêu nhân viên của từng người để mọi người có thể mua đồ ăn mình thích ở căng tin bệnh viện. Việc đó sẽ cần ban lãnh đạo phê duyệt, nhưng tôi sẽ thông báo tình hình cho mọi người."]],"qs":[{"n":92,"q":"Where do the listeners most likely work?","qvi":"Người nghe nhiều khả năng làm việc ở đâu?","opts":["At a hospital","At a restaurant","At a grocery store","At an electronics store"],"vi":["Ở bệnh viện","Ở nhà hàng","Ở cửa hàng tạp hóa","Ở cửa hàng điện tử"],"ans":"A","xp":"Người nói mở đầu: \"Excuse me, nurses.\" và nhắc đến \"the hospital break rooms\" → người nghe là y tá làm ở bệnh viện → (A)."},{"n":93,"q":"What is the main purpose of the talk?","qvi":"Mục đích chính của bài nói là gì?","opts":["To make a request","To address staff complaints","To present a new schedule","To explain a technical process"],"vi":["Để đưa ra một yêu cầu","Để giải quyết phàn nàn của nhân viên","Để giới thiệu lịch mới","Để giải thích một quy trình kỹ thuật"],"ans":"B","xp":"Người nói: \"I've been receiving complaints about the free snacks in the hospital break rooms\" rồi đưa ra giải pháp → mục đích là giải quyết phàn nàn của nhân viên (address = giải quyết) → (B)."},{"n":94,"q":"What does the speaker imply when she says, \"That will require management approval\"?","qvi":"Người nói ngụ ý gì khi nói \"Việc đó sẽ cần ban lãnh đạo phê duyệt\"?","opts":["A process has not been followed.","The listeners may be asked to work extra shifts.","The listeners should contact a manager.","A change will not be immediate."],"vi":["Một quy trình đã không được tuân thủ.","Người nghe có thể được yêu cầu làm thêm ca.","Người nghe nên liên hệ với quản lý.","Thay đổi sẽ không diễn ra ngay lập tức."],"ans":"D","xp":"Câu hỏi hàm ý. Người nói đề xuất nạp tiền vào tài khoản nhân viên, rồi nói \"That will require management approval, but I'll keep you posted.\" → cần chờ duyệt nên thay đổi sẽ không có ngay → (D)."}],"a":"E24-T01-92-94.mp3"},{"ns":[95,97],"script":[["","As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park. There are a lot of new areas to explore, so we've planned a short hike. We'll be walking around the pond and along the renovated walking trail. We'll end our walk on the hill on the north side of the park. There we'll be having some free snacks and ice cream. For those of you taking photos, don't forget to post them on the city's Web site. We'd like to commemorate this special day.","Với tư cách là thị trưởng Lakeville, tôi rất vui được chào đón quý vị đến với lễ kỷ niệm Công viên Lakeville vừa được cải tạo của thị trấn chúng ta. Có rất nhiều khu vực mới để khám phá, vì vậy chúng tôi đã lên kế hoạch cho một chuyến đi bộ ngắn. Chúng ta sẽ đi quanh hồ và dọc theo con đường đi bộ đã được cải tạo. Chúng ta sẽ kết thúc chuyến đi trên ngọn đồi ở phía bắc công viên. Ở đó chúng ta sẽ có đồ ăn nhẹ và kem miễn phí. Ai chụp ảnh thì đừng quên đăng ảnh lên trang web của thành phố nhé. Chúng tôi muốn lưu giữ kỷ niệm về ngày đặc biệt này."]],"qs":[{"n":95,"q":"According to the speaker, what was recently completed?","qvi":"Theo người nói, điều gì vừa mới được hoàn thành?","opts":["A company reorganization","A park renovation","A volunteer training","A conservation project"],"vi":["Việc tái cơ cấu công ty","Việc cải tạo công viên","Khóa đào tạo tình nguyện viên","Một dự án bảo tồn"],"ans":"B","xp":"Người nói: \"welcome you to the celebration for our town's newly renovated Lakeville Park\" → công viên vừa được cải tạo xong → (B)."},{"n":96,"q":"Look at the graphic. Where does the speaker say refreshments will be served?","qvi":"Hãy nhìn bản đồ. Người nói cho biết đồ ăn nhẹ sẽ được phục vụ ở đâu?","opts":["Location 1","Location 2","Location 3","Location 4"],"vi":["Vị trí 1","Vị trí 2","Vị trí 3","Vị trí 4"],"ans":"A","xp":"Người nói: \"We'll end our walk on the hill on the north side of the park. There we'll be having some free snacks and ice cream.\" Trên bản đồ, ngọn đồi (Hill) là vị trí 1 → (A). Lưu ý: snacks and ice cream = refreshments; (C) Picnic Tables là bẫy."},{"n":97,"q":"What are the listeners reminded to do?","qvi":"Người nghe được nhắc nhở làm gì?","opts":["Complete a survey","Donate some money","Join an organization","Post some photographs"],"vi":["Hoàn thành khảo sát","Quyên góp tiền","Tham gia một tổ chức","Đăng một số bức ảnh"],"ans":"D","xp":"Người nói: \"For those of you taking photos, don't forget to post them on the city's Web site.\" → (D)."}],"a":"E24-T01-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Thanks, everyone, for attending today's free public lecture, sponsored by the Springfield Farmers' Association. So, we've received lots of requests for information on growing a vegetable garden. People want to know how to keep their garden healthy and get the vegetables they want. The first thing we recommend is regular soil testing. Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart. Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.","Cảm ơn mọi người đã tham dự buổi thuyết giảng công cộng miễn phí hôm nay, do Hiệp hội Nông dân Springfield tài trợ. Chúng tôi đã nhận được rất nhiều yêu cầu cung cấp thông tin về cách trồng vườn rau. Mọi người muốn biết cách giữ cho khu vườn khỏe mạnh và thu được loại rau mình muốn. Điều đầu tiên chúng tôi khuyên là kiểm tra đất thường xuyên. Vì bây giờ là tháng Chín, tất cả mẫu đất trong sáu tuần tới nên được lấy ở cùng một độ sâu, như trong biểu đồ này. À, và trước khi ra về hôm nay, xin hãy đăng ký vào danh sách nhận thư của chúng tôi để được cập nhật về các buổi thuyết giảng sắp tới."]],"qs":[{"n":98,"q":"What is the topic of today's lecture?","qvi":"Chủ đề của buổi thuyết giảng hôm nay là gì?","opts":["When to harvest crops","Where to plant trees","How to grow vegetables","Which flowers need more sun"],"vi":["Khi nào thu hoạch mùa màng","Trồng cây ở đâu","Cách trồng rau","Loài hoa nào cần nhiều nắng hơn"],"ans":"C","xp":"Người nói: \"we've received lots of requests for information on growing a vegetable garden\" và tiếp tục hướng dẫn cách chăm vườn rau → chủ đề là cách trồng rau → (C)."},{"n":99,"q":"Look at the graphic. At what depth should samples be collected this month?","qvi":"Hãy nhìn bảng. Tháng này nên lấy mẫu ở độ sâu nào?","opts":["12 inches","4 inches","6 inches","8 inches"],"vi":["12 inch","4 inch","6 inch","8 inch"],"ans":"A","xp":"Người nói: \"Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.\" Trong bảng, tháng 9-10 (September-October) áp dụng cho mọi loại cây với độ sâu 12 inches → (A). Bẫy: (C) 6 inches cho rau chỉ áp dụng từ tháng 11 đến tháng 8."},{"n":100,"q":"What does the speaker encourage the listeners to do?","qvi":"Người nói khuyến khích người nghe làm gì?","opts":["Turn off mobile phones","Have some refreshments","Purchase some seeds","Sign up for a mailing list"],"vi":["Tắt điện thoại di động","Dùng đồ ăn nhẹ","Mua hạt giống","Đăng ký danh sách nhận thư"],"ans":"D","xp":"Câu cuối: \"please sign up for our mailing list to stay informed of future lectures\" → (D)."}],"a":"E24-T01-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Former Sendai Company CEO Ken Nakata spoke about ------- career experiences.","opts":["he","his","him","himself"],"ans":"B","xp":"Đại từ. Sau chỗ trống là cụm danh từ 'career experiences' → cần tính từ sở hữu. (B) his 'của ông ấy' → chọn (B). (A) he là đại từ chủ ngữ, (C) him là đại từ tân ngữ, (D) himself là đại từ phản thân, không đứng trước danh từ.\nDịch: Cựu CEO của Công ty Sendai, Ken Nakata, đã nói về những trải nghiệm nghề nghiệp của ông."},{"n":102,"q":"Passengers who will be taking a ------- domestic flight should go to Terminal A.","opts":["connectivity","connects","connect","connecting"],"ans":"D","xp":"Từ loại. Chỗ trống nằm giữa mạo từ 'a' và cụm danh từ 'domestic flight' → cần tính từ. (D) connecting dùng như tính từ: 'connecting flight' = chuyến bay nối chuyến → chọn (D). (A) connectivity là danh từ 'khả năng kết nối', (B) connects và (C) connect là động từ.\nDịch: Hành khách sẽ đi chuyến bay nội địa nối chuyến nên đến Nhà ga A."},{"n":103,"q":"Fresh and ------- apple-cider donuts are available at Oakcrest Orchard's retail shop for £6 per dozen.","opts":["eaten","open","tasty","free"],"ans":"C","xp":"Từ vựng (tính từ). 'Fresh and -------' cùng bổ nghĩa cho bánh donut → cần tính từ khen món ăn. (C) tasty 'ngon' → chọn (C). (A) eaten 'đã bị ăn', (B) open 'mở', (D) free 'miễn phí' (mâu thuẫn với giá £6).\nDịch: Bánh donut rượu táo tươi và ngon có bán tại cửa hàng bán lẻ của Oakcrest Orchard với giá 6 bảng một tá."},{"n":104,"q":"Zahn Flooring has the widest selection of ------- in the United Kingdom.","opts":["paints","tiles","furniture","curtains"],"ans":"B","xp":"Từ vựng (danh từ). Công ty tên 'Zahn Flooring' (vật liệu lát sàn) → hợp lý nhất là (B) tiles 'gạch lát' → chọn (B). (A) paints 'sơn', (C) furniture 'đồ nội thất', (D) curtains 'rèm cửa'.\nDịch: Zahn Flooring có nhiều lựa chọn gạch lát nhất ở Vương quốc Anh."},{"n":105,"q":"One responsibility of the IT department is to ensure that the company is using ------- software.","opts":["update","updating","updates","updated"],"ans":"D","xp":"Từ loại. Trước danh từ 'software' cần tính từ. Phân từ quá khứ (D) updated 'đã được cập nhật' mang nghĩa bị động, phù hợp (phần mềm được cập nhật) → chọn (D). (A)/(C) là động từ/danh từ, (B) updating mang nghĩa chủ động 'đang cập nhật', không hợp.\nDịch: Một trách nhiệm của phòng IT là đảm bảo công ty đang sử dụng phần mềm đã được cập nhật."},{"n":106,"q":"It is wise to check a company's dress code ------- visiting its head office.","opts":["so","how","like","before"],"ans":"D","xp":"Giới từ/liên từ. Sau chỗ trống là V-ing 'visiting' → cần giới từ chỉ thời gian. (D) before 'trước khi' hợp nghĩa: kiểm tra quy định trang phục trước khi đến trụ sở → chọn (D). (A) so 'vì vậy', (B) how 'như thế nào', (C) like 'giống như' không hợp nghĩa.\nDịch: Nên kiểm tra quy định trang phục của công ty trước khi đến thăm trụ sở chính của công ty đó."},{"n":107,"q":"Wexler Store's management team expects that employees will ------- support any new hires.","opts":["enthusiastically","enthusiasm","enthusiastic","enthused"],"ans":"A","xp":"Từ loại. Chỗ trống nằm giữa trợ động từ 'will' và động từ chính 'support' → cần trạng từ bổ nghĩa cho động từ. (A) enthusiastically 'một cách nhiệt tình' → chọn (A). (B) là danh từ, (C) là tính từ, (D) là động từ quá khứ/phân từ.\nDịch: Ban quản lý cửa hàng Wexler mong rằng nhân viên sẽ nhiệt tình hỗ trợ những người mới được tuyển."},{"n":108,"q":"Wheel alignments and brake system ------- are part of our vehicle service plan.","opts":["inspects","inspector","inspected","inspections"],"ans":"D","xp":"Từ loại/danh từ ghép. 'brake system -------' là cụm danh từ làm chủ ngữ cùng với 'Wheel alignments', động từ là 'are' (số nhiều) → cần danh từ số nhiều chỉ việc. (D) inspections 'các lần kiểm tra' → chọn (D). (B) inspector 'người kiểm tra' là danh từ chỉ người, số ít, không hợp nghĩa; (A)/(C) là động từ.\nDịch: Cân chỉnh bánh xe và kiểm tra hệ thống phanh là một phần trong gói bảo dưỡng xe của chúng tôi."},{"n":109,"q":"Registration for the Marketing Coalition Conference is now open ------- September 30.","opts":["until","into","yet","while"],"ans":"A","xp":"Giới từ. Sau chỗ trống là mốc thời gian 'September 30', câu nói việc đăng ký mở kéo dài đến một thời điểm → (A) until 'cho đến' → chọn (A). (B) into 'vào trong', (C) yet 'chưa/tuy nhiên', (D) while 'trong khi' (liên từ, cần mệnh đề).\nDịch: Việc đăng ký tham dự Hội nghị Liên minh Tiếp thị hiện đang mở cho đến ngày 30 tháng 9."},{"n":110,"q":"Growth in the home entertainment industry has been ------- this quarter.","opts":["separate","limited","willing","assorted"],"ans":"B","xp":"Từ vựng (tính từ). Chủ ngữ là 'Growth' (sự tăng trưởng) → tính từ hợp lý là (B) limited 'hạn chế' → chọn (B). (A) separate 'riêng biệt', (C) willing 'sẵn lòng' (dùng cho người), (D) assorted 'đủ loại'.\nDịch: Sự tăng trưởng trong ngành giải trí tại gia đã bị hạn chế trong quý này."},{"n":111,"q":"Hawson Furniture will be making ------- on the east side of town on Thursday.","opts":["deliveries","delivered","deliver","deliverable"],"ans":"A","xp":"Từ loại. Sau động từ 'making' cần danh từ làm tân ngữ. (A) deliveries 'các chuyến giao hàng' ('make deliveries' = giao hàng) → chọn (A). (B)/(C) là động từ, (D) deliverable chủ yếu là tính từ 'có thể giao được'.\nDịch: Nội thất Hawson sẽ giao hàng ở phía đông thị trấn vào thứ Năm."},{"n":112,"q":"The Marlton City Council does not have the authority to ------- parking on city streets.","opts":["drive","prohibit","bother","travel"],"ans":"B","xp":"Từ vựng (động từ). Tân ngữ là 'parking', nói về 'authority' (thẩm quyền) của hội đồng thành phố → (B) prohibit 'cấm' → chọn (B). (A) drive 'lái xe', (C) bother 'làm phiền', (D) travel 'đi lại' không hợp.\nDịch: Hội đồng thành phố Marlton không có thẩm quyền cấm đỗ xe trên các đường phố của thành phố."},{"n":113,"q":"Project Earth Group is ------- for ways to reduce transport-related greenhouse gas emissions.","opts":["looking","seeing","driving","leaning"],"ans":"A","xp":"Từ vựng/cụm động từ. Có giới từ 'for' phía sau → 'look for' = tìm kiếm → (A) looking → chọn (A). (B) seeing 'nhìn thấy', (C) driving 'lái', (D) leaning 'dựa vào' (lean on/against) không đi với 'for' theo nghĩa này.\nDịch: Tập đoàn Project Earth đang tìm cách giảm lượng khí thải nhà kính liên quan đến giao thông vận tải."},{"n":114,"q":"Our skilled tailors are happy to design a custom-made suit that fits your style and budget -------.","opts":["perfect","perfects","perfectly","perfection"],"ans":"C","xp":"Từ loại. Mệnh đề 'that fits your style and budget' đã đầy đủ (động từ + tân ngữ) → chỗ trống cuối câu cần trạng từ bổ nghĩa cho động từ 'fits'. (C) perfectly 'một cách hoàn hảo' → chọn (C). (A) là tính từ/động từ, (B) là động từ, (D) là danh từ.\nDịch: Những thợ may lành nghề của chúng tôi sẵn lòng thiết kế bộ vest may đo phù hợp hoàn hảo với phong cách và ngân sách của bạn."},{"n":115,"q":"Project manager Hannah Chung has proved to be very ------- with completing company projects.","opts":["helpfulness","help","helpfully","helpful"],"ans":"D","xp":"Từ loại. Sau 'prove to be' + trạng từ 'very' → cần tính từ làm bổ ngữ. (D) helpful 'hữu ích, giúp được nhiều' → chọn (D). (A) helpfulness là danh từ, (B) help là động từ/danh từ, (C) helpfully là trạng từ.\nDịch: Quản lý dự án Hannah Chung đã chứng tỏ là người rất đắc lực trong việc hoàn thành các dự án của công ty."},{"n":116,"q":"Lehua Vacation Club members will receive double points ------- the month of August at participating hotels.","opts":["onto","above","during","between"],"ans":"C","xp":"Giới từ. Sau chỗ trống là khoảng thời gian 'the month of August' → (C) during 'trong suốt' → chọn (C). (A) onto 'lên trên', (B) above 'phía trên', (D) between 'giữa (hai thứ)' không hợp.\nDịch: Thành viên của Câu lạc bộ Kỳ nghỉ Lehua sẽ nhận gấp đôi điểm trong suốt tháng Tám tại các khách sạn tham gia chương trình."},{"n":117,"q":"The costumes were not received ------- enough to be used in the first dress rehearsal.","opts":["far","very","almost","soon"],"ans":"D","xp":"Từ vựng (trạng từ). Cấu trúc 'adj/adv + enough to V'. Nghĩa: trang phục không đến kịp (sớm đủ) để dùng trong buổi tổng duyệt → (D) soon 'sớm' → chọn (D). (A) far 'xa', (B) very 'rất' (không đứng trước enough), (C) almost 'gần như'.\nDịch: Trang phục đã không được nhận đủ sớm để sử dụng trong buổi tổng duyệt đầu tiên."},{"n":118,"q":"As a former publicist for several renowned orchestras, Mr. Wu would excel in the role of event -------.","opts":["organized","organizer","organizes","organizational"],"ans":"B","xp":"Từ loại. 'the role of event -------' → cần danh từ chỉ người (vai trò do người đảm nhận), tạo danh từ ghép 'event organizer' = người tổ chức sự kiện → chọn (B). (A)/(C) là động từ, (D) organizational là tính từ.\nDịch: Là cựu chuyên viên quan hệ công chúng của nhiều dàn nhạc nổi tiếng, ông Wu sẽ làm rất tốt vai trò người tổ chức sự kiện."},{"n":119,"q":"The northbound lane on Davis Street will be ------- closed because of the city's bridge reinforcement project.","opts":["temporarily","competitively","recently","collectively"],"ans":"A","xp":"Từ vựng (trạng từ). Làn đường bị đóng do dự án gia cố cầu → đóng 'tạm thời' → (A) temporarily → chọn (A). (B) competitively 'một cách cạnh tranh', (C) recently 'gần đây' (không dùng với thì tương lai 'will'), (D) collectively 'một cách tập thể'.\nDịch: Làn đường hướng bắc trên phố Davis sẽ tạm thời bị đóng do dự án gia cố cầu của thành phố."},{"n":120,"q":"Airline representatives must handle a wide range of passenger issues, ------- missed connections to lost luggage.","opts":["from","under","on","against"],"ans":"A","xp":"Giới từ. Cấu trúc 'from A to B' (từ A đến B) dùng để liệt kê phạm vi, có 'to lost luggage' phía sau → (A) from → chọn (A). (B) under 'dưới', (C) on 'trên/về', (D) against 'chống lại'.\nDịch: Nhân viên hãng hàng không phải xử lý nhiều vấn đề của hành khách, từ lỡ chuyến bay nối chuyến đến thất lạc hành lý."},{"n":121,"q":"The meeting notes were ------- deleted, but Mr. Hahm was able to recreate them from memory.","opts":["accident","accidental","accidents","accidentally"],"ans":"D","xp":"Từ loại. Chỗ trống nằm giữa 'were' và phân từ 'deleted' (câu bị động) → cần trạng từ. (D) accidentally 'vô tình' → chọn (D). (A)/(C) là danh từ, (B) là tính từ.\nDịch: Biên bản cuộc họp đã vô tình bị xóa, nhưng ông Hahm đã có thể viết lại từ trí nhớ."},{"n":122,"q":"The current issue of Farming Scene magazine predicts that the price of corn will rise 5 percent over the ------- year.","opts":["next","with","which","now"],"ans":"A","xp":"Từ vựng/tính từ. 'over the ------- year' cần một từ bổ nghĩa cho 'year'; dự đoán dùng thì tương lai → 'over the next year' = trong năm tới → chọn (A). (B) with là giới từ, (C) which là đại từ quan hệ, (D) now là trạng từ.\nDịch: Số hiện tại của tạp chí Farming Scene dự đoán giá ngô sẽ tăng 5% trong năm tới."},{"n":123,"q":"Anyone who still ------- to take the fire safety training should do so before the end of the month.","opts":["needing","needs","has needed","were needing"],"ans":"B","xp":"Chia động từ/hòa hợp chủ ngữ. Mệnh đề quan hệ 'who ------- ' có chủ ngữ 'Anyone' (số ít) → cần động từ chia ở hiện tại số ít. (B) needs → chọn (B). (A) needing không phải động từ chính; (C) has needed không hợp với 'still' chỉ tình trạng hiện tại; (D) were needing sai số và sai thì.\nDịch: Bất kỳ ai vẫn còn cần tham gia khóa huấn luyện an toàn phòng cháy nên làm việc đó trước cuối tháng."},{"n":124,"q":"Emerging technologies have ------- begun to transform the shipping industry in ways that were once unimaginable.","opts":["already","exactly","hardly","closely"],"ans":"A","xp":"Từ vựng (trạng từ). Đứng giữa 'have' và 'begun' (thì hiện tại hoàn thành) → (A) already 'đã ... rồi' rất thường dùng với thì này → chọn (A). (B) exactly 'chính xác', (C) hardly 'hầu như không' (nghĩa phủ định, trái ý câu), (D) closely 'chặt chẽ, sát sao'.\nDịch: Các công nghệ mới nổi đã bắt đầu thay đổi ngành vận tải theo những cách từng không thể tưởng tượng nổi."},{"n":125,"q":"The company handbook outlines the high ------- that employees are expected to meet every day.","opts":["experts","accounts","recommendations","standards"],"ans":"D","xp":"Từ vựng (danh từ). 'high ------- that employees are expected to meet' → 'meet high standards' = đáp ứng tiêu chuẩn cao → chọn (D). (A) experts 'chuyên gia', (B) accounts 'tài khoản', (C) recommendations 'lời khuyên' (không đi với 'high' và 'meet').\nDịch: Sổ tay công ty nêu ra những tiêu chuẩn cao mà nhân viên được kỳ vọng phải đáp ứng mỗi ngày."},{"n":126,"q":"Because ------- of the board members have scheduling conflicts, the board meeting will be moved to a date when all can attend.","opts":["any","everybody","those","some"],"ans":"D","xp":"Đại từ/lượng từ. Cấu trúc '------- of the board members' + động từ số nhiều 'have'; nghĩa: vì một số thành viên bị trùng lịch → (D) some 'một vài' → chọn (D). (A) any thường dùng trong câu phủ định/nghi vấn; (B) everybody không đi với 'of the'; (C) those of thường không dùng với 'the + danh từ' theo nghĩa này.\nDịch: Vì một số thành viên hội đồng quản trị bị trùng lịch, cuộc họp hội đồng sẽ được dời sang ngày mà tất cả có thể tham dự."},{"n":127,"q":"The project ------- the collaboration of several teams across the company.","opts":["passed","decided","required","performed"],"ans":"C","xp":"Từ vựng (động từ). Tân ngữ là 'the collaboration of several teams' → dự án 'cần đến' sự phối hợp → (C) required → chọn (C). (A) passed 'vượt qua/thông qua', (B) decided 'quyết định', (D) performed 'thực hiện/biểu diễn'.\nDịch: Dự án đòi hỏi sự phối hợp của nhiều nhóm trong toàn công ty."},{"n":128,"q":"We cannot send the store's coupon booklet to the printers until it ------- by Ms. Jeon.","opts":["is approving","approves","has been approved","will be approved"],"ans":"C","xp":"Thì + thể bị động. Có 'by Ms. Jeon' → chủ ngữ 'it' (cuốn coupon) được duyệt → cần bị động, loại (A), (B). Mệnh đề trạng ngữ thời gian bắt đầu bằng 'until' không dùng thì tương lai 'will' → loại (D). (C) has been approved (hiện tại hoàn thành bị động, nhấn mạnh việc duyệt đã xong) → chọn (C).\nDịch: Chúng tôi không thể gửi cuốn phiếu giảm giá của cửa hàng đến nhà in cho đến khi nó được cô Jeon phê duyệt."},{"n":129,"q":"------- the closure of Verdigold Transport Services, we are looking for a new shipping company.","opts":["In spite of","Just as","In light of","According to"],"ans":"C","xp":"Giới từ/cụm giới từ. Việc công ty vận chuyển đóng cửa là lý do phải tìm công ty mới → (C) In light of 'xét đến, do' → chọn (C). (A) In spite of 'mặc dù' (trái nghĩa), (B) Just as 'ngay khi/giống như' (liên từ), (D) According to 'theo như'.\nDịch: Do việc Dịch vụ Vận tải Verdigold đóng cửa, chúng tôi đang tìm một công ty vận chuyển mới."},{"n":130,"q":"The ------- information provided by Uniss Bank's brochure helps applicants understand the terms of their loans.","opts":["arbitrary","supplemental","superfluous","potential"],"ans":"B","xp":"Từ vựng (tính từ). Thông tin trong tờ rơi giúp người vay hiểu điều khoản → thông tin 'bổ sung' → (B) supplemental → chọn (B). (A) arbitrary 'tùy tiện', (C) superfluous 'thừa thãi' (nghĩa tiêu cực), (D) potential 'tiềm năng'.\nDịch: Thông tin bổ sung trong tờ rơi của Ngân hàng Uniss giúp người nộp đơn hiểu các điều khoản của khoản vay."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following announcement.","passage":"<p>Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. <span class=\"blank\" data-n=\"131\">-------</span>. We will teach you how to plant a rain garden, which is simply a shallow sunken garden <span class=\"blank\" data-n=\"132\">-------</span> a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops. These gardens can be landscaped with native plants and flowers. <span class=\"blank\" data-n=\"133\">-------</span>, rain gardens are always beneficial to the local environment. Among other things, <span class=\"blank\" data-n=\"134\">-------</span> improve drainage and protect rivers and streams.</p><p>To register, visit www.maxley-horticulture.org.</p>","vi":"Hãy đến Trung tâm Làm vườn Maxley Heights và học cách tạo một khu vườn đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. Vào 4 giờ chiều thứ Bảy tới, chúng tôi tổ chức một buổi hội thảo miễn phí dành cho công chúng. Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa, đơn giản là một khu vườn trũng nông sử dụng hỗn hợp đất đặc biệt để lọc các chất ô nhiễm khỏi nước mưa chảy từ các con đường và mái nhà gần đó. Những khu vườn này có thể được tạo cảnh bằng các loại cây và hoa bản địa. Tuyệt vời nhất là, vườn mưa luôn có lợi cho môi trường địa phương. Ngoài những lợi ích khác, chúng còn cải thiện khả năng thoát nước và bảo vệ sông suối.\n\nĐể đăng ký, hãy truy cập www.maxley-horticulture.org.","qs":[{"n":131,"opts":["Children of all ages will enjoy the new exhibits.","Learn about rainfall patterns across the region.","Build a set of simple patio furniture with easy-to-acquire materials.","Next Saturday at 4 P.M., we are hosting a free workshop for the public."],"ans":"D","xp":"Điền câu. Câu trước mời mọi người đến 'learn how to create a beautiful, eco-friendly garden'; câu sau 'We will teach you how to plant a rain garden' → ở giữa cần câu giới thiệu sự kiện dạy học cụ thể. (D) nêu thời gian buổi hội thảo miễn phí → nối mạch tự nhiên: hội thảo → 'chúng tôi sẽ dạy bạn...'. (A) nói về triển lãm cho trẻ em, (B) nói về mô hình lượng mưa, (C) nói về đóng bàn ghế, đều lạc chủ đề làm vườn.\n(A) Trẻ em mọi lứa tuổi sẽ thích các khu trưng bày mới.\n(B) Tìm hiểu về mô hình lượng mưa trong khu vực.\n(C) Đóng một bộ bàn ghế sân hiên đơn giản bằng vật liệu dễ kiếm.\n(D) Vào 4 giờ chiều thứ Bảy tới, chúng tôi tổ chức một buổi hội thảo miễn phí cho công chúng."},{"n":132,"opts":["to use","used to","by using","that uses"],"ans":"D","xp":"Mệnh đề quan hệ. 'a shallow sunken garden ------- a special soil mix' → cần từ nối danh từ 'garden' với phần mô tả có tân ngữ 'a special soil mix'. (D) that uses 'mà sử dụng' (đại từ quan hệ + động từ số ít hợp với 'garden') → chọn (D). (A) to use 'để sử dụng' sai nghĩa (khu vườn không có mục đích dùng đất); (B) used to 'từng' hoặc 'được dùng để' không hợp; (C) by using 'bằng cách sử dụng' cần chủ thể hành động.\nDịch: ...một khu vườn trũng nông sử dụng hỗn hợp đất đặc biệt để lọc các chất ô nhiễm."},{"n":133,"opts":["Best of all","For example","In any event","As a matter of fact"],"ans":"A","xp":"Trạng từ liên kết. Câu trước nêu một ưu điểm (có thể trang trí bằng cây hoa bản địa), câu sau nêu ưu điểm quan trọng nhất (luôn có lợi cho môi trường) → (A) Best of all 'tuyệt vời nhất là' → chọn (A). (B) For example 'ví dụ' (câu sau không phải ví dụ của câu trước), (C) In any event 'dù sao đi nữa' (dùng khi gạt bỏ điều vừa nói), (D) As a matter of fact 'thật ra' (dùng để đính chính/nhấn mạnh thêm).\nDịch: Tuyệt vời nhất là, vườn mưa luôn có lợi cho môi trường địa phương."},{"n":134,"opts":["we","they","both","yours"],"ans":"B","xp":"Đại từ. Chủ ngữ của động từ 'improve drainage and protect rivers' phải là những khu vườn mưa (rain gardens, số nhiều) ở câu trước → (B) they → chọn (B). (A) we 'chúng tôi' (trung tâm không cải thiện thoát nước), (C) both 'cả hai' (không có hai đối tượng cụ thể), (D) yours 'của bạn' là đại từ sở hữu, không hợp nghĩa.\nDịch: Ngoài những lợi ích khác, chúng còn cải thiện khả năng thoát nước và bảo vệ sông suối."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following letter.","passage":"<p>31 July</p><p>Akwasi Dombo<br>Fourth Avenue<br>GA 105<br>Accra, Ghana</p><p>Dear Mr. Dombo,</p><p>Thank you for your <span class=\"blank\" data-n=\"135\">-------</span> support in helping me to plan the opening gala for Tokyo's fashion week. The event was a huge success, and I was honored to work with you. I know that our attendees follow your work closely, and they loved the designs you contributed for this event. Your designs received a lot of <span class=\"blank\" data-n=\"136\">-------</span> on social media. Shows like this will keep Tokyo on the map as a premier fashion centre. <span class=\"blank\" data-n=\"137\">-------</span>. I realize that the multiple delays made the planning no easy task. The auction <span class=\"blank\" data-n=\"138\">-------</span> our Young Designers Award program is coming up soon and I look forward to working with you on that as well.</p><p>Sincerely,</p><p>Asahi Ishioka<br>Director, Japanese Guild of Fashion Designers</p>","vi":"Ngày 31 tháng 7\n\nAkwasi Dombo\nĐại lộ Fourth\nGA 105\nAccra, Ghana\n\nKính gửi ông Dombo,\n\nCảm ơn ông vì sự hỗ trợ tuyệt vời trong việc giúp tôi lên kế hoạch cho buổi dạ tiệc khai mạc tuần lễ thời trang Tokyo. Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông. Tôi biết khách tham dự của chúng tôi theo dõi sát sao công việc của ông, và họ rất thích những thiết kế ông đóng góp cho sự kiện này. Các thiết kế của ông đã nhận được rất nhiều sự chú ý trên mạng xã hội. Những buổi trình diễn như thế này sẽ giữ cho Tokyo có tên trên bản đồ như một trung tâm thời trang hàng đầu. Cảm ơn ông cũng vì sự linh hoạt trong quá trình lên kế hoạch cho sự kiện. Tôi hiểu rằng nhiều lần trì hoãn đã khiến việc lên kế hoạch không hề dễ dàng. Buổi đấu giá nhằm gây quỹ cho chương trình Giải thưởng Nhà thiết kế Trẻ của chúng tôi sắp diễn ra và tôi mong được tiếp tục làm việc cùng ông trong sự kiện đó.\n\nTrân trọng,\n\nAsahi Ishioka\nGiám đốc, Hiệp hội Nhà thiết kế Thời trang Nhật Bản","qs":[{"n":135,"opts":["amazed","amazement","amazing","amazingly"],"ans":"C","xp":"Từ loại. Chỗ trống nằm giữa tính từ sở hữu 'your' và danh từ 'support' → cần tính từ. Sự hỗ trợ gây ấn tượng cho người khác → dùng V-ing: (C) amazing 'tuyệt vời' → chọn (C). (A) amazed 'cảm thấy ngạc nhiên' dùng cho người cảm nhận; (B) amazement là danh từ; (D) amazingly là trạng từ.\nDịch: Cảm ơn ông vì sự hỗ trợ tuyệt vời..."},{"n":136,"opts":["attention","proposals","innovation","criticism"],"ans":"A","xp":"Từ vựng (danh từ). Câu trước nói khách tham dự rất thích các thiết kế; câu sau nói những buổi trình diễn như vậy giúp Tokyo nổi tiếng → thiết kế nhận được nhiều 'sự chú ý' trên mạng xã hội → (A) attention → chọn (A). (B) proposals 'đề xuất', (C) innovation 'sự đổi mới', (D) criticism 'lời chỉ trích' (tiêu cực, trái mạch văn).\nDịch: Các thiết kế của ông đã nhận được rất nhiều sự chú ý trên mạng xã hội."},{"n":137,"opts":["Several other events have gone surprisingly well.","Thank you also for your flexibility in planning the event.","Please stop by our office the next time you are in the city.","Tokyo is a top tourism destination for many reasons."],"ans":"B","xp":"Điền câu. Câu ngay sau là 'I realize that the multiple delays made the planning no easy task' (nhiều lần trì hoãn khiến việc lên kế hoạch không dễ dàng) → câu cần điền phải liên quan đến khó khăn khi lên kế hoạch. (B) cảm ơn sự linh hoạt trong việc lên kế hoạch → 'also' nối với lời cảm ơn ở đầu thư, và 'flexibility' được giải thích bằng 'multiple delays' → chọn (B). (A) nói về sự kiện khác, (C) lời mời ghé văn phòng, (D) nói về du lịch — không nối với câu sau.\n(A) Một số sự kiện khác đã diễn ra tốt đến bất ngờ.\n(B) Cảm ơn ông cũng vì sự linh hoạt trong việc lên kế hoạch cho sự kiện.\n(C) Vui lòng ghé văn phòng chúng tôi lần tới khi ông đến thành phố.\n(D) Tokyo là điểm du lịch hàng đầu vì nhiều lý do."},{"n":138,"opts":["will benefit","to benefit","has benefited","benefits"],"ans":"B","xp":"Dạng động từ (to V). Câu 'The auction ------- our Young Designers Award program is coming up soon' đã có động từ chính 'is coming' → chỗ trống không thể là động từ chia thì, loại (A), (C), (D). Cần to-infinitive bổ nghĩa cho danh từ 'auction' chỉ mục đích: (B) to benefit 'nhằm mang lại lợi ích/gây quỹ cho' → chọn (B).\nDịch: Buổi đấu giá nhằm gây quỹ cho chương trình Giải thưởng Nhà thiết kế Trẻ của chúng tôi sắp diễn ra."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>From:</b> Patron Services &lt;patronservices@menachinlibrary.org&gt;</p><p><b>To:</b> Edgar Hughes &lt;hughese98@villachesta.com&gt;</p><p><b>Subject:</b> Card expiration date approaching</p><p><b>Date:</b> December 3</p></div><p>Dear Mr. Hughes,</p><p>Please be advised that your Mena Chin Library card will expire one month from today. <span class=\"blank\" data-n=\"139\">-------</span> must be renewed if you intend to keep your membership for the coming year. <span class=\"blank\" data-n=\"140\">-------</span>. This can be done at the information desk at any branch location.</p><p><span class=\"blank\" data-n=\"141\">-------</span> you decide to close your account, no action is necessary. Failure to complete your renewal by the <span class=\"blank\" data-n=\"142\">-------</span> date will result in the expiration of your library privileges.</p><p>If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.</p><p>Sincerely,</p><p>Patron Services</p>","vi":"Từ: Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>\nĐến: Edgar Hughes <hughese98@villachesta.com>\nTiêu đề: Sắp đến ngày hết hạn thẻ\nNgày: 3 tháng 12\n\nKính gửi ông Hughes,\n\nXin thông báo rằng thẻ thư viện Mena Chin của ông sẽ hết hạn sau một tháng kể từ hôm nay. Thẻ phải được gia hạn nếu ông muốn giữ tư cách thành viên trong năm tới. Việc gia hạn phải được hoàn tất ít nhất một tuần trước khi thẻ hết hạn. Việc này có thể thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào.\n\nNếu ông quyết định đóng tài khoản, ông không cần làm gì cả. Việc không hoàn tất gia hạn trước ngày đã nêu sẽ khiến quyền sử dụng thư viện của ông hết hiệu lực.\n\nNếu ông có bất kỳ câu hỏi nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp email này.\n\nTrân trọng,\n\nDịch vụ Bạn đọc","qs":[{"n":139,"opts":["It","You","Our","Each"],"ans":"A","xp":"Đại từ. Câu '------- must be renewed' (phải được gia hạn) → chủ ngữ là vật được gia hạn, tức thẻ thư viện ở câu trước ('your Mena Chin Library card', số ít) → (A) It → chọn (A). (B) You: người không 'được gia hạn'; (C) Our là tính từ sở hữu, cần danh từ theo sau; (D) Each 'mỗi' không có danh từ để chỉ.\nDịch: Thẻ phải được gia hạn nếu ông muốn giữ tư cách thành viên trong năm tới."},{"n":140,"opts":["To sign up for a card, visit your local library branch.","For questions about library membership, please visit our Web site.","Renewal must be completed at least one week before your card expires.","You may opt out of this program at any time."],"ans":"C","xp":"Điền câu. Câu sau 'This can be done at the information desk at any branch location' → 'This' phải chỉ một hành động có thể làm tại quầy thông tin, tức là việc gia hạn. (C) nói việc gia hạn phải hoàn tất ít nhất một tuần trước khi thẻ hết hạn → 'This' = renewal → chọn (C). (A) nói về đăng ký thẻ mới (ông Hughes đã có thẻ); (B) hướng dẫn vào website, mâu thuẫn với 'at the information desk' và cuối thư bảo trả lời email; (D) nói về rút khỏi chương trình, không liên quan.\n(A) Để đăng ký thẻ, hãy đến chi nhánh thư viện gần bạn.\n(B) Nếu có câu hỏi về tư cách thành viên, vui lòng truy cập website của chúng tôi.\n(C) Việc gia hạn phải được hoàn tất ít nhất một tuần trước khi thẻ của ông hết hạn.\n(D) Ông có thể rút khỏi chương trình này bất cứ lúc nào."},{"n":141,"opts":["Also","Should","Because","Although"],"ans":"B","xp":"Đảo ngữ câu điều kiện. '------- you decide to close your account, no action is necessary' → nghĩa: nếu ông quyết định đóng tài khoản thì không cần làm gì. 'Should + S + V' = 'If + S + V' (đảo ngữ điều kiện loại 1) → (B) Should → chọn (B). (A) Also 'cũng' không nối hai mệnh đề; (C) Because 'vì' và (D) Although 'mặc dù' không hợp nghĩa.\nDịch: Nếu ông quyết định đóng tài khoản, ông không cần làm gì cả."},{"n":142,"opts":["specifically","specifics","specified","specificity"],"ans":"C","xp":"Từ loại. 'by the ------- date' → giữa 'the' và danh từ 'date' cần tính từ. (C) specified 'đã được chỉ định/đã nêu' (phân từ quá khứ dùng như tính từ) → 'the specified date' = ngày đã nêu → chọn (C). (A) là trạng từ, (B) specifics và (D) specificity là danh từ.\nDịch: Việc không hoàn tất gia hạn trước ngày đã nêu sẽ khiến quyền sử dụng thư viện của ông hết hiệu lực."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following letter.","passage":"<p>April 7</p><p>Naomi Burwell<br>43 Waymire Road<br>South Portland, ME 04109</p><p>Dear Ms. Burwell,</p><p>I am Omar Ridha, the manager of Droplight Studio. <span class=\"blank\" data-n=\"143\">-------</span>. We offer a full range of photography services for real estate professionals like you. We take pride in composing interior and exterior shots that make a property look its best. Droplight Studio spares no effort in <span class=\"blank\" data-n=\"144\">-------</span> superior digital images. <span class=\"blank\" data-n=\"145\">-------</span>, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property. And once the photo shoot is over, every image <span class=\"blank\" data-n=\"146\">-------</span> expert editing. All these services come standard in every package.</p><p>Please visit our Web site to view our work as well as our pricing and scheduling information. We are happy to work with you to customize orders.</p><p>Sincerely,</p><p>Omar Ridha, Droplight Studio</p>","vi":"Ngày 7 tháng 4\n\nNaomi Burwell\n43 đường Waymire\nSouth Portland, ME 04109\n\nKính gửi bà Burwell,\n\nTôi là Omar Ridha, quản lý của Droplight Studio. Tôi muốn giới thiệu với bà về doanh nghiệp của chúng tôi. Chúng tôi cung cấp đầy đủ các dịch vụ chụp ảnh cho các chuyên gia bất động sản như bà. Chúng tôi tự hào về việc bố cục những bức ảnh nội thất và ngoại thất giúp bất động sản trông đẹp nhất. Droplight Studio không tiếc công sức để tạo ra những hình ảnh kỹ thuật số chất lượng vượt trội. Thật vậy, thiết bị đạt chuẩn chuyên nghiệp, ánh sáng và kỹ thuật dàn dựng của chúng tôi cho phép làm nổi bật những đặc điểm tốt nhất của bất động sản. Và sau khi buổi chụp kết thúc, mọi bức ảnh đều được chỉnh sửa bởi chuyên gia. Tất cả các dịch vụ này đều là tiêu chuẩn trong mọi gói dịch vụ.\n\nVui lòng truy cập website của chúng tôi để xem các tác phẩm cũng như thông tin về giá và lịch đặt chụp. Chúng tôi sẵn lòng làm việc với bà để điều chỉnh đơn hàng theo yêu cầu.\n\nTrân trọng,\n\nOmar Ridha, Droplight Studio","qs":[{"n":143,"opts":["I would like to introduce you to our business.","Great photographs can make your property stand out.","We are looking forward to your visit.","It was the first studio of its kind to open in this area."],"ans":"A","xp":"Điền câu. Người viết vừa tự giới thiệu 'I am Omar Ridha, the manager of Droplight Studio', câu sau bắt đầu mô tả dịch vụ 'We offer a full range of photography services...' → câu ở giữa nên nêu mục đích thư: giới thiệu doanh nghiệp. (A) → chọn (A). (B) hợp chủ đề nhưng chen giữa phần tự giới thiệu và phần mô tả dịch vụ thì đột ngột; (C) chưa có lịch hẹn nào; (D) 'It' không rõ chỉ gì và thông tin không liên quan.\n(A) Tôi muốn giới thiệu với bà về doanh nghiệp của chúng tôi.\n(B) Những bức ảnh đẹp có thể làm bất động sản của bà nổi bật.\n(C) Chúng tôi mong được đón bà đến thăm.\n(D) Đó là studio đầu tiên thuộc loại này mở tại khu vực."},{"n":144,"opts":["researching","creating","purchasing","displaying"],"ans":"B","xp":"Từ vựng (V-ing). 'spare no effort in V-ing' = không tiếc công sức làm gì. Studio chụp ảnh thì 'tạo ra' hình ảnh kỹ thuật số chất lượng cao → (B) creating → chọn (B). (A) researching 'nghiên cứu', (C) purchasing 'mua', (D) displaying 'trưng bày' không phù hợp với công việc của studio.\nDịch: Droplight Studio không tiếc công sức để tạo ra những hình ảnh kỹ thuật số chất lượng vượt trội."},{"n":145,"opts":["If not","By comparison","Otherwise","Indeed"],"ans":"D","xp":"Trạng từ liên kết. Câu trước nói studio dốc sức tạo ảnh chất lượng cao; câu sau đưa ra bằng chứng củng cố (thiết bị chuyên nghiệp, ánh sáng, kỹ thuật dàn dựng) → (D) Indeed 'thật vậy' → chọn (D). (A) If not 'nếu không', (B) By comparison 'so với đó', (C) Otherwise 'nếu không thì/ngoài ra' không hợp mạch.\nDịch: Thật vậy, thiết bị đạt chuẩn chuyên nghiệp, ánh sáng và kỹ thuật dàn dựng của chúng tôi cho phép làm nổi bật những đặc điểm tốt nhất của bất động sản."},{"n":146,"opts":["receives","is receiving","had received","had to receive"],"ans":"A","xp":"Thì động từ. Đoạn văn mô tả quy trình dịch vụ luôn diễn ra (sự thật/thói quen) bằng thì hiện tại đơn ('We offer', 'come standard'); chủ ngữ 'every image' số ít → (A) receives → chọn (A). (B) is receiving chỉ việc đang diễn ra lúc nói; (C) had received và (D) had to receive là thì quá khứ, không hợp.\nDịch: Và sau khi buổi chụp kết thúc, mọi bức ảnh đều được chỉnh sửa bởi chuyên gia."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following information.","passages":["<h3>STOP! PLEASE READ FIRST.</h3><p>Thank you for purchasing this item.</p><p>As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage. Assemble the item on a soft surface or on the flattened empty box.</p><p>Follow the pictures and begin the assembly by placing the main part on its side. Never overtighten any screws or bolts, or you may damage the wood or cushioning. Please visit our Web site to obtain maintenance tips and register your product for warranty coverage: www.indoordelight.com.</p>"],"vi":"DỪNG LẠI! VUI LÒNG ĐỌC TRƯỚC.\n\nCảm ơn bạn đã mua sản phẩm này.\n\nKhi mở hộp, vui lòng kiểm tra xem đã có đủ tất cả các bộ phận chưa và đặt chúng ở một nơi an toàn để tránh thất lạc hoặc hư hỏng. Hãy lắp ráp sản phẩm trên một bề mặt mềm hoặc trên chính chiếc hộp rỗng đã được trải phẳng.\n\nLàm theo các hình minh họa và bắt đầu lắp ráp bằng cách đặt phần chính nằm nghiêng. Không bao giờ vặn quá chặt bất kỳ con vít hay bu lông nào, nếu không bạn có thể làm hỏng phần gỗ hoặc phần đệm. Vui lòng truy cập trang web của chúng tôi để nhận các mẹo bảo dưỡng và đăng ký sản phẩm để được bảo hành: www.indoordelight.com.","qs":[{"n":147,"q":"Where is the information most likely found?","qvi":"Thông tin này nhiều khả năng được tìm thấy ở đâu?","opts":["On a door","On a receipt","In a box","On a Web site"],"ans":"C","xp":"Câu hỏi suy luận (nơi xuất hiện thông tin). Tiêu đề \"STOP! PLEASE READ FIRST.\" và câu \"As you do the unpacking, please verify that all components are included...\" cho thấy đây là tờ hướng dẫn người mua đọc ngay khi mở hộp sản phẩm → tờ giấy này nằm trong hộp. Ngoài ra còn nhắc \"the flattened empty box\" (cái hộp rỗng). → Chọn (C).\n(B) sai vì hóa đơn không hướng dẫn lắp ráp; (D) sai vì văn bản bảo người đọc \"visit our Web site\" → bản thân nó không nằm trên web.\n(A) Trên một cánh cửa\n(B) Trên một hóa đơn\n(C) Trong một chiếc hộp\n(D) Trên một trang web"},{"n":148,"q":"What kind of item is most likely discussed?","qvi":"Loại sản phẩm nào nhiều khả năng đang được nói đến?","opts":["A desktop computer","A piece of furniture","A household appliance","A power tool"],"ans":"B","xp":"Câu hỏi suy luận. Bằng chứng: phải lắp ráp (\"Assemble the item\", \"screws or bolts\") và \"you may damage the wood or cushioning\" (có thể làm hỏng phần gỗ hoặc phần đệm). Sản phẩm bằng gỗ, có đệm, phải tự lắp bằng vít → đồ nội thất (ví dụ ghế sofa, ghế). Thương hiệu \"indoordelight\" cũng gợi ý đồ trang trí trong nhà. → Chọn (B).\n(A) Một máy tính để bàn\n(B) Một món đồ nội thất\n(C) Một thiết bị gia dụng (điện)\n(D) Một dụng cụ điện cầm tay"}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following meeting schedule.","passages":["<p>We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings. Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.</p><table><tr><th>Winnipeg</th><th></th><th>Toulouse</th></tr><tr><td><u>7:00 A.M.</u></td><td>—</td><td>2:00 P.M.</td></tr><tr><td><u>8:00 A.M.</u></td><td>—</td><td>3:00 P.M.</td></tr><tr><td><u>9:00 A.M.</u></td><td>—</td><td>4:00 P.M.</td></tr><tr><td><u>10:00 A.M.</u></td><td>—</td><td>5:00 P.M.</td></tr><tr><td>11:00 A.M.</td><td>—</td><td>6:00 P.M.</td></tr><tr><td>12:00 noon</td><td>—</td><td>7:00 P.M.</td></tr></table>"],"vi":"Chúng tôi đề nghị toàn bộ nhân viên ở Winnipeg giữ một bản lịch này tại bàn làm việc như một công cụ tra cứu nhanh khi sắp xếp các cuộc họp giữa hai văn phòng. Bất cứ khi nào có thể, vui lòng sắp xếp các cuộc họp này vào một trong các khung giờ được gạch chân, tức là từ sau 7 giờ sáng nhưng trước 11 giờ sáng.\n\nWinnipeg — Toulouse\n7:00 sáng — 2:00 chiều\n8:00 sáng — 3:00 chiều\n9:00 sáng — 4:00 chiều\n10:00 sáng — 5:00 chiều\n11:00 sáng — 6:00 chiều\n12:00 trưa — 7:00 tối","qs":[{"n":149,"q":"What is suggested by the schedule?","qvi":"Lịch này gợi ý điều gì?","opts":["A conference has been scheduled.","A firm has offices in two time zones.","Administrative assistants make travel plans.","Some meeting times have been changed."],"ans":"B","xp":"Câu hỏi suy luận. Lịch so sánh giờ ở Winnipeg (Canada) và Toulouse (Pháp): 7:00 A.M. ở Winnipeg tương ứng 2:00 P.M. ở Toulouse, chênh nhau 7 tiếng. Văn bản nói lịch dùng để \"scheduling interoffice meetings\" (họp giữa các văn phòng) → công ty có văn phòng ở hai múi giờ khác nhau. → Chọn (B).\n(A), (C), (D) không được nhắc đến.\n(A) Một hội nghị đã được lên lịch.\n(B) Một công ty có văn phòng ở hai múi giờ.\n(C) Các trợ lý hành chính lên kế hoạch đi lại.\n(D) Một số giờ họp đã bị thay đổi."},{"n":150,"q":"What is indicated about 11:00 A.M. Winnipeg time?","qvi":"Điều gì được nêu về 11 giờ sáng giờ Winnipeg?","opts":["It is when the Winnipeg office closes for lunch.","It is when staff in Toulouse begin their workday.","It is not a preferred time to schedule a meeting.","It has just been added to the schedule."],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.\" — 11:00 A.M. không được gạch chân (lúc đó ở Toulouse đã 6 giờ chiều) → đây không phải giờ nên đặt lịch họp. \"not a preferred time\" = không nằm trong khung giờ khuyến khích. → Chọn (C).\n(A) Đó là lúc văn phòng Winnipeg đóng cửa nghỉ trưa.\n(B) Đó là lúc nhân viên ở Toulouse bắt đầu ngày làm việc.\n(C) Đó không phải là thời điểm được ưu tiên để đặt lịch họp.\n(D) Nó vừa mới được thêm vào lịch."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following brochure.","passages":["<p>The Bryant Foyer is one of the premier event spaces in our area. Set on a hill, it has expansive windows that provide sweeping views of the adjacent botanical gardens and the river. Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago. Today, the space can accommodate up to 200 guests and is ideal for wedding receptions, office parties, and panel presentations. With its marble floors, cathedral ceiling, and stunning artwork, the Bryant Foyer is the ideal location for your next gathering.</p><p>The on-site restaurant, Andito's, caters our events and also operates as its own business. This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene. Area residents know to plan far in advance to get a seat.</p><p>To reserve the event space or to make a dinner reservation, give us a call at 216-555-0157.</p>"],"vi":"Bryant Foyer là một trong những không gian tổ chức sự kiện hàng đầu trong khu vực của chúng tôi. Nằm trên một ngọn đồi, nơi đây có những ô cửa sổ rộng mở ra khung cảnh bao quát khu vườn bách thảo liền kề và dòng sông. Được xây dựng vào năm 1897, đây từng là trụ sở của Quỹ từ thiện Francona cho đến khi được cải tạo cách đây hơn một năm. Ngày nay, không gian này có thể chứa tới 200 khách và rất lý tưởng cho tiệc cưới, tiệc công ty và các buổi thuyết trình chuyên đề. Với sàn đá cẩm thạch, trần nhà cao vút kiểu nhà thờ và những tác phẩm nghệ thuật tuyệt đẹp, Bryant Foyer là địa điểm lý tưởng cho buổi họp mặt tiếp theo của bạn.\n\nNhà hàng tại chỗ, Andito's, cung cấp đồ ăn cho các sự kiện của chúng tôi và cũng hoạt động như một doanh nghiệp riêng. Nhà hàng \"từ nông trại đến bàn ăn\" này, do đầu bếp Michaela Rymond đứng đầu, đáp ứng mọi nhu cầu ăn uống và đã tạo nên cuộc cách mạng trong ẩm thực địa phương. Cư dân trong vùng đều biết phải lên kế hoạch thật sớm mới có được chỗ ngồi.\n\nĐể đặt không gian tổ chức sự kiện hoặc đặt bàn ăn tối, hãy gọi cho chúng tôi theo số 216-555-0157.","qs":[{"n":151,"q":"What is indicated about the Bryant Foyer?","qvi":"Điều gì được nêu về Bryant Foyer?","opts":["It is located on the shores of a lake.","It has recently been renovated.","It will build a botanical garden for guests.","It is reserved solely for corporate events."],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"it was the home of the Francona Charitable Trust until its renovation just over a year ago\" (được cải tạo cách đây hơn một năm) → \"recently been renovated\". → Chọn (B).\n(A) sai: nó nằm trên đồi, nhìn ra sông (river), không phải hồ. (C) sai: vườn bách thảo đã có sẵn ở bên cạnh (adjacent). (D) sai: còn dùng cho tiệc cưới (wedding receptions), không chỉ sự kiện công ty.\n(A) Nó nằm bên bờ một hồ nước.\n(B) Nó mới được cải tạo gần đây.\n(C) Nó sẽ xây một vườn bách thảo cho khách.\n(D) Nó chỉ dành riêng cho các sự kiện của công ty."},{"n":152,"q":"What is suggested about Andito's?","qvi":"Điều gì được gợi ý về Andito's?","opts":["It was started by an international chef.","It offers limited menu options.","It is now funded by a charitable organization.","It is very popular with local residents."],"ans":"D","xp":"Câu hỏi suy luận. Bằng chứng: \"Area residents know to plan far in advance to get a seat.\" (Cư dân trong vùng biết phải lên kế hoạch từ rất sớm mới có chỗ) → nhà hàng rất đông khách, rất được người dân địa phương ưa chuộng. → Chọn (D).\n(B) sai vì nhà hàng \"meets all dietary needs\" (đáp ứng mọi nhu cầu ăn uống). (C) sai: quỹ từ thiện chỉ là chủ cũ của tòa nhà. (A) không được nhắc đến.\n(A) Nó được mở bởi một đầu bếp quốc tế.\n(B) Nó có ít lựa chọn món ăn.\n(C) Hiện nó được một tổ chức từ thiện tài trợ.\n(D) Nó rất được cư dân địa phương ưa chuộng."}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Joan Chi (12:39 P.M.)</b></p><p>Hello Mina. Are you almost finished with the field measurements? I'm getting hungry.</p></div><div class=\"msg\"><p><b>Mina Evers (12:40 P.M.)</b></p><p>Sorry, Joan. I'm afraid you and Ms. Lim will have to go to lunch without me today. There's a problem with the site coordinates. This is going to take some time.</p></div><div class=\"msg\"><p><b>Joan Chi (12:51 P.M.)</b></p><p>Oh no. Should we bring something back for you?</p></div><div class=\"msg\"><p><b>Mina Evers (12:59 P.M.)</b></p><p>Get me a chicken sandwich.</p></div><div class=\"msg\"><p><b>Joan Chi (1:00 P.M.)</b></p><p>Sure thing, Mina. See you in a while.</p></div>"],"vi":"Joan Chi (12:39 chiều): Chào Mina. Chị sắp đo đạc xong ngoài hiện trường chưa? Tôi bắt đầu đói rồi.\n\nMina Evers (12:40 chiều): Xin lỗi Joan. Tôi e là hôm nay chị và chị Lim sẽ phải đi ăn trưa mà không có tôi rồi. Tọa độ công trường đang có vấn đề. Việc này sẽ mất khá nhiều thời gian.\n\nJoan Chi (12:51 chiều): Ôi không. Chúng tôi có nên mang gì về cho chị không?\n\nMina Evers (12:59 chiều): Mua giúp tôi một cái bánh mì kẹp gà nhé.\n\nJoan Chi (1:00 chiều): Được thôi, Mina. Lát nữa gặp lại nhé.","qs":[{"n":153,"q":"At 1:00 P.M., what does Ms. Chi most likely mean when she writes, \"Sure thing, Mina\"?","qvi":"Lúc 1:00 chiều, khi chị Chi viết \"Sure thing, Mina\" (Được thôi, Mina), nhiều khả năng ý chị ấy là gì?","opts":["She will bring lunch for Ms. Evers.","She can provide a tool that Ms. Evers needs.","Some site coordinates are correct.","Some measurements must be double-checked."],"ans":"A","xp":"Câu hỏi hàm ý. Ngay trước đó, Joan hỏi \"Should we bring something back for you?\" và Mina trả lời \"Get me a chicken sandwich.\" (Mua giúp tôi bánh mì kẹp gà). \"Sure thing\" = đồng ý → Joan sẽ mang bữa trưa (bánh mì kẹp gà) về cho Mina Evers. → Chọn (A).\n(A) Chị ấy sẽ mang bữa trưa về cho chị Evers.\n(B) Chị ấy có thể cung cấp một dụng cụ mà chị Evers cần.\n(C) Một số tọa độ công trường là chính xác.\n(D) Một số số đo phải được kiểm tra lại."},{"n":154,"q":"What will happen next?","qvi":"Điều gì sẽ xảy ra tiếp theo?","opts":["Ms. Chi will get new site coordinates.","Ms. Chi and Ms. Lim will be out for a while.","Ms. Evers will share a recipe.","Ms. Lim will begin taking measurements."],"ans":"B","xp":"Câu hỏi suy luận. Mina viết \"you and Ms. Lim will have to go to lunch without me today\" và Joan kết thúc bằng \"See you in a while.\" (Lát nữa gặp lại) → chị Chi và chị Lim sẽ ra ngoài ăn trưa một lúc. → Chọn (B).\n(A), (D) sai: chính Mina là người xử lý tọa độ và đo đạc. (C) không liên quan.\n(A) Chị Chi sẽ lấy tọa độ công trường mới.\n(B) Chị Chi và chị Lim sẽ ra ngoài một lúc.\n(C) Chị Evers sẽ chia sẻ một công thức nấu ăn.\n(D) Chị Lim sẽ bắt đầu đo đạc."}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following notice.","passages":["<p>This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for. Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.</p><p>If you need us to come to you instead, please contact us. We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it. Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.</p>"],"vi":"Thời tiết tuyệt vời của mùa này đã mang lại một vụ thu hoạch trái cây và rau củ dồi dào, trong nhiều trường hợp còn nhiều hơn lượng mà người trồng có thể tìm được người mua. Những ai trong số các bạn muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể làm vậy bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách các điểm nhận hàng của chúng tôi.\n\nNếu bạn cần chúng tôi đến tận nơi, vui lòng liên hệ với chúng tôi. Chúng tôi sẽ liên lạc với một trong nhiều tài xế xe tải độc lập đã tình nguyện vận chuyển và nhanh chóng phân phát thực phẩm quyên góp của bạn đến các nhóm đã được thẩm định và đang cần. Hãy xem trang web của chúng tôi để biết thêm thông tin về dịch vụ này cũng như những hiểu biết về các chủ đề liên quan đến trồng trọt và làm vườn ở vùng Northern Great Plains.","qs":[{"n":155,"q":"For whom is the notice most likely intended?","qvi":"Thông báo này nhiều khả năng dành cho ai?","opts":["Farmers","Professional chefs","Truck drivers","Supermarket managers"],"ans":"A","xp":"Câu hỏi suy luận (đối tượng). Thông báo nói vụ mùa bội thu, \"more than growers may find buyers for\" và \"Those of you wishing to donate surplus produce...\" (những ai muốn quyên góp nông sản dư thừa) → người đọc là người trồng trọt có nông sản dư = nông dân. → Chọn (A).\n(C) sai: tài xế xe tải là người tình nguyện chở hàng, được nhắc đến chứ không phải người đọc.\n(A) Nông dân\n(B) Đầu bếp chuyên nghiệp\n(C) Tài xế xe tải\n(D) Quản lý siêu thị"},{"n":156,"q":"What does the notice indicate about the weather?","qvi":"Thông báo cho biết điều gì về thời tiết?","opts":["It caused transportation delays.","It included heavier rain than usual.","It was frequently a topic in the local news.","It was beneficial for crops."],"ans":"D","xp":"Câu hỏi chi tiết. Bằng chứng: \"This season's excellent weather has yielded a substantial harvest of fruits and vegetables\" (thời tiết tuyệt vời mang lại vụ thu hoạch dồi dào) → thời tiết có lợi cho cây trồng. \"beneficial for crops\" diễn đạt lại ý này. → Chọn (D).\n(A), (B), (C) không được nhắc đến.\n(A) Nó gây chậm trễ vận chuyển.\n(B) Có mưa nhiều hơn bình thường.\n(C) Nó thường xuyên là chủ đề trên tin tức địa phương.\n(D) Nó có lợi cho cây trồng."},{"n":157,"q":"What service does the notice mention?","qvi":"Thông báo đề cập đến dịch vụ nào?","opts":["Staffing for local businesses","Food collection and distribution","Farm machinery repair","Gardening workshops"],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"If you need us to come to you instead... truck drivers who have kindly volunteered to transport and quickly distribute your food donations\" và \"Check our Web site for more information about this service\" → dịch vụ đến lấy thực phẩm quyên góp và phân phát = \"Food collection and distribution\". → Chọn (B).\n(D) sai: web chỉ cung cấp thông tin (insights) về làm vườn, không nói đến hội thảo.\n(A) Cung cấp nhân sự cho doanh nghiệp địa phương\n(B) Thu gom và phân phát thực phẩm\n(C) Sửa chữa máy móc nông nghiệp\n(D) Hội thảo làm vườn"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following notice.","passages":["<p>We are delighted that you are joining us for today's event. — <span class=\"pos\">[1]</span> —. We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.</p><p>Upon entering the venue, please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — <span class=\"pos\">[2]</span> —. Moreover, audience members are not allowed to make an audio or visual recording of the performance.</p><p>Bags and other items in the aisles pose a safety concern. — <span class=\"pos\">[3]</span> —. If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. — <span class=\"pos\">[4]</span> —. One of our attendants will gladly assist you with that.</p><p>Thank you for your cooperation.</p>"],"vi":"Chúng tôi rất vui vì quý vị đã đến tham dự sự kiện hôm nay. — [1] —. Chúng tôi đề nghị quý vị tuân thủ các hướng dẫn sau để đảm bảo mọi khán giả đều có trải nghiệm thú vị.\n\nKhi vào khu vực biểu diễn, vui lòng chuyển tất cả các thiết bị điện tử sang chế độ im lặng. Tiếng chuông điện thoại và màn hình sáng gây mất tập trung rất nhiều cho cả người biểu diễn lẫn những khán giả khác. — [2] —. Hơn nữa, khán giả không được phép ghi âm hoặc ghi hình buổi biểu diễn.\n\nTúi xách và các đồ vật khác để ở lối đi gây mất an toàn. — [3] —. Nếu túi của quý vị quá lớn, không để vừa dưới ghế, hãy cân nhắc gửi nó vào tủ khóa với giá chỉ 2 đô la. — [4] —. Một nhân viên của chúng tôi sẽ sẵn lòng hỗ trợ quý vị việc đó.\n\nCảm ơn sự hợp tác của quý vị.","qs":[{"n":158,"q":"Where most likely is the notice posted?","qvi":"Thông báo này nhiều khả năng được dán ở đâu?","opts":["In an airplane","In a concert hall","At a restaurant","At a post office"],"ans":"B","xp":"Câu hỏi suy luận (địa điểm). Các từ khóa: \"the performers\" (người biểu diễn), \"fellow audience members\" (các khán giả khác), \"recording of the performance\" (ghi hình buổi biểu diễn), \"under a seat\", \"aisles\" (lối đi giữa các hàng ghế) → đây là nơi diễn ra buổi biểu diễn, tức một phòng hòa nhạc. → Chọn (B).\n(A) Trên máy bay\n(B) Trong một phòng hòa nhạc\n(C) Tại một nhà hàng\n(D) Tại bưu điện"},{"n":159,"q":"What is stated about large bags?","qvi":"Điều gì được nêu về túi xách lớn?","opts":["They can be put in a locked box for a fee.","They must be left outside the building.","They will be inspected by an attendant.","They must be stored under a seat."],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2.\" → \"locker\" (tủ khóa) = \"a locked box\", \"for just $2\" = \"for a fee\" (có tính phí). → Chọn (A).\n(D) sai: túi lớn chính là túi không để vừa dưới ghế. (B), (C) không được nhắc đến (nhân viên chỉ hỗ trợ gửi tủ, không kiểm tra túi).\n(A) Có thể cất chúng vào tủ có khóa với một khoản phí.\n(B) Phải để chúng bên ngoài tòa nhà.\n(C) Chúng sẽ được nhân viên kiểm tra.\n(D) Phải cất chúng dưới ghế."},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\n\"Please refrain from making phone calls or texting at all times.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\n\"Vui lòng không gọi điện hoặc nhắn tin vào bất cứ lúc nào.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Câu hỏi điền câu. Câu cần điền nói về việc không dùng điện thoại (gọi điện, nhắn tin). Vị trí [2] nằm ngay sau câu \"please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting...\" (để thiết bị ở chế độ im lặng, chuông và màn hình sáng gây mất tập trung) → nói tiếp về điện thoại là hợp lý; sau [2] là \"Moreover, ... not allowed to make an audio or visual recording\" — \"Moreover\" (hơn nữa) bổ sung thêm một quy định về thiết bị. → Chọn (B).\n[3], [4] thuộc đoạn nói về túi xách nên không phù hợp; [1] đứng trước khi bắt đầu các quy định."}]},{"ns":[161,164],"head":"Questions 161-164 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Camille Ayala &lt;ayala@esplinelectronics.com&gt;</p><p><b>From:</b> Masae Adachi &lt;madachi@sweeterspecialties.com&gt;</p><p><b>Date:</b> February 12</p><p><b>Subject:</b> Event order</p><p><b>Attachment:</b> Sweeter Specialties Request Form</p></div><p>Dear Ms. Ayala,</p><p>Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March. We are honored that you chose us for a fourth year in a row! On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day. You will be billed on March 28. Please review the attached order form and return it to me within seven days.</p><p>Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications. In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling. We have judged it to be a delectable treat, and we are sure that you will be pleased.</p><p>If you have any concerns, just send me an e-mail. As always, we value your business.</p><p>Masae Adachi, Owner<br>Sweeter Specialties</p>"],"vi":"Người nhận: Camille Ayala <ayala@esplinelectronics.com>\nNgười gửi: Masae Adachi <madachi@sweeterspecialties.com>\nNgày: 12 tháng 2\nTiêu đề: Đơn hàng cho sự kiện\nTệp đính kèm: Phiếu yêu cầu của Sweeter Specialties\n\nKính gửi chị Ayala,\n\nCảm ơn chị đã chọn chúng tôi cung cấp bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng Ba. Chúng tôi rất vinh dự khi được chị chọn năm thứ tư liên tiếp! Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani lớn cho mỗi địa điểm trong số mười địa điểm chị đã chỉ định, và chúng tôi sẽ giao một chiếc bánh nhiều tầng làm theo yêu cầu riêng vào ngày hôm sau. Chị sẽ nhận hóa đơn vào ngày 28 tháng 3. Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày.\n\nVề chiếc bánh chị đặt cho ngày 30 tháng 3, bếp trưởng làm bánh của chúng tôi sẽ làm theo đúng các yêu cầu của chị. Thực tế, anh ấy đã làm thử một chiếc bánh mẫu theo công thức hoàn chỉnh vào sáng nay — bánh kem hạnh nhân với nhân mâm xôi tươi. Chúng tôi đánh giá đây là một món bánh rất ngon, và chúng tôi tin chắc chị sẽ hài lòng.\n\nNếu chị có bất kỳ thắc mắc nào, chỉ cần gửi email cho tôi. Như mọi khi, chúng tôi rất trân trọng sự ủng hộ của chị.\n\nMasae Adachi, Chủ cửa hàng\nSweeter Specialties","qs":[{"n":161,"q":"What is the main purpose of the e-mail?","qvi":"Mục đích chính của email là gì?","opts":["To request confirmation of an order","To adjust some delivery dates","To announce the expansion of a business","To promote new dessert products"],"ans":"A","xp":"Câu hỏi mục đích. Email tóm tắt lại đơn hàng (bánh vani cho 10 địa điểm ngày 29/3, bánh nhiều tầng ngày 30/3, thanh toán ngày 28/3) và yêu cầu \"Please review the attached order form and return it to me within seven days.\" (xem lại phiếu đặt hàng và gửi lại) → mục đích là đề nghị khách xác nhận đơn hàng. → Chọn (A).\n(B) sai: ngày giao không bị thay đổi. (D) sai: bánh mẫu được làm theo yêu cầu của khách, không phải quảng cáo sản phẩm mới.\n(A) Đề nghị xác nhận một đơn hàng\n(B) Điều chỉnh một số ngày giao hàng\n(C) Thông báo việc mở rộng kinh doanh\n(D) Quảng bá sản phẩm tráng miệng mới"},{"n":162,"q":"What is suggested about Ms. Ayala?","qvi":"Điều gì được gợi ý về chị Ayala?","opts":["She is receiving a professional award.","She has worked as a pastry chef.","She has been a Sweeter Specialties client in the past.","She received a positive recommendation about a chef."],"ans":"C","xp":"Câu hỏi suy luận. Bằng chứng: \"We are honored that you chose us for a fourth year in a row!\" (năm thứ tư liên tiếp) và \"As always, we value your business.\" → chị Ayala đã từng là khách hàng của Sweeter Specialties trước đây. → Chọn (C).\n(B) sai: người làm bánh là bếp trưởng của cửa hàng. (A), (D) không được nhắc đến.\n(A) Chị ấy sắp nhận một giải thưởng nghề nghiệp.\n(B) Chị ấy từng làm thợ làm bánh.\n(C) Chị ấy từng là khách hàng của Sweeter Specialties.\n(D) Chị ấy nhận được lời giới thiệu tốt về một đầu bếp."},{"n":163,"q":"What is indicated about the multilayer cake?","qvi":"Điều gì được nêu về chiếc bánh nhiều tầng?","opts":["It has been a best-selling product with clients.","It is the most expensive cake at Sweeter Specialties.","It is baked for Esplin Electronics annually.","It is a new flavor combination for Sweeter Specialties."],"ans":"D","xp":"Câu hỏi chi tiết. Bánh nhiều tầng là bánh \"custom-baked\" (làm theo yêu cầu riêng), giao vào 30/3. Đoạn 2: \"our head pastry chef will produce it according to your specifications. In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling.\" → bếp trưởng phải làm thử bánh mẫu theo công thức mới của khách → đây là sự kết hợp hương vị mới đối với cửa hàng. → Chọn (D).\n(C) sai: được chọn 4 năm liên tiếp nhưng không nói năm nào cũng làm loại bánh này. (A), (B) không được nhắc đến.\n(A) Nó là sản phẩm bán chạy nhất với khách hàng.\n(B) Nó là chiếc bánh đắt nhất ở Sweeter Specialties.\n(C) Nó được làm cho Esplin Electronics hằng năm.\n(D) Nó là một sự kết hợp hương vị mới của Sweeter Specialties."},{"n":164,"q":"The word \"judged\" in paragraph 2, line 3, is closest in meaning to","qvi":"Từ \"judged\" ở đoạn 2, dòng 3 gần nghĩa nhất với","opts":["criticized","settled","determined","described"],"ans":"C","xp":"Câu hỏi đồng nghĩa. \"We have judged it to be a delectable treat\" = Chúng tôi đã đánh giá / nhận định rằng nó là món bánh rất ngon. \"judge ... to be ...\" ở đây nghĩa là đưa ra kết luận, nhận định → gần nghĩa nhất với \"determined\" (xác định, kết luận). → Chọn (C).\n(A) criticized: chỉ trích (sai vì câu mang nghĩa khen). (B) settled: giải quyết, dàn xếp. (D) described: mô tả.\n(A) chỉ trích\n(B) giải quyết, dàn xếp\n(C) xác định, kết luận\n(D) mô tả"}]},{"ns":[165,167],"head":"Questions 165-167 refer to the following product review.","passages":["<h3>Great Dishwasher!</h3><p>I never had a dishwasher before. After remodeling my kitchen, I finally had room for a compact dishwasher. I did a lot of research, and the Dish Magic 300 seemed to be the best choice. It was pricier than other models, but all of the reviews were excellent. So, I decided to spend the extra money. I have had the dishwasher for one month now, and I could not be happier with my decision. Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in. Also, the machine is so quiet, you do not even know it is running. Lastly, it is designed to use water efficiently, which is very important to me. Overall, I am very pleased with this dishwasher.</p><p>– Anna Yakovleva</p>"],"vi":"Máy rửa bát tuyệt vời!\n\nTrước đây tôi chưa từng có máy rửa bát. Sau khi sửa sang lại căn bếp, cuối cùng tôi cũng có chỗ cho một chiếc máy rửa bát nhỏ gọn. Tôi đã tìm hiểu rất kỹ, và Dish Magic 300 có vẻ là lựa chọn tốt nhất. Nó đắt hơn các mẫu khác, nhưng tất cả các đánh giá đều rất tốt. Vì vậy, tôi quyết định chi thêm tiền. Tôi đã dùng chiếc máy này được một tháng, và tôi không thể hài lòng hơn với quyết định của mình. Quan trọng nhất là bát đĩa ra sạch bóng, dù lúc cho vào bẩn đến đâu. Ngoài ra, máy chạy êm đến mức bạn thậm chí không biết là nó đang hoạt động. Cuối cùng, nó được thiết kế để sử dụng nước hiệu quả, điều rất quan trọng đối với tôi. Nhìn chung, tôi rất hài lòng với chiếc máy rửa bát này.\n\n– Anna Yakovleva","qs":[{"n":165,"q":"Why did Ms. Yakovleva choose the Dish Magic 300 dishwasher?","qvi":"Tại sao chị Yakovleva chọn máy rửa bát Dish Magic 300?","opts":["It was less expensive than most models.","It was the largest model available.","It was rated very highly.","It was the same brand as her other appliances."],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"It was pricier than other models, but all of the reviews were excellent. So, I decided to spend the extra money.\" → chị chọn vì các đánh giá đều xuất sắc = \"rated very highly\". → Chọn (C).\n(A) sai: máy đắt hơn (pricier). (B) sai: chị mua máy nhỏ gọn (compact). (D) không được nhắc đến.\n(A) Nó rẻ hơn hầu hết các mẫu khác.\n(B) Nó là mẫu lớn nhất hiện có.\n(C) Nó được đánh giá rất cao.\n(D) Nó cùng thương hiệu với các thiết bị khác của chị."},{"n":166,"q":"The word \"running\" in paragraph 1, line 7, is closest in meaning to","qvi":"Từ \"running\" ở đoạn 1, dòng 7 gần nghĩa nhất với","opts":["adjusting","controlling","moving","operating"],"ans":"D","xp":"Câu hỏi đồng nghĩa. \"the machine is so quiet, you do not even know it is running\" = máy êm đến mức bạn không biết là nó đang chạy / đang hoạt động. Với máy móc, \"run\" = hoạt động → \"operating\". → Chọn (D).\n(C) moving (di chuyển) là nghĩa \"chạy\" của người/vật, không hợp với máy rửa bát.\n(A) điều chỉnh\n(B) điều khiển\n(C) di chuyển\n(D) hoạt động, vận hành"},{"n":167,"q":"What is indicated about Ms. Yakovleva?","qvi":"Điều gì được nêu về chị Yakovleva?","opts":["She cares about saving water.","She recently moved to a new home.","She bought the dishwasher a year ago.","She remodels kitchens professionally."],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"it is designed to use water efficiently, which is very important to me\" (dùng nước hiệu quả, điều rất quan trọng với tôi) → chị quan tâm đến việc tiết kiệm nước. → Chọn (A).\n(B) sai: chị sửa lại bếp (remodeling my kitchen), không phải chuyển nhà. (C) sai: mới dùng được một tháng (one month). (D) sai: không nói chị làm nghề sửa bếp.\n(A) Chị ấy quan tâm đến việc tiết kiệm nước.\n(B) Chị ấy mới chuyển đến nhà mới.\n(C) Chị ấy mua máy rửa bát cách đây một năm.\n(D) Chị ấy làm nghề cải tạo nhà bếp."}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following information.","passages":["<p>Skyler Airlines employs more than 20,000 people from all over the world. We're growing fast and have many positions available. — <span class=\"pos\">[1]</span> —. So regardless of your background, there's probably a place for you on our team. Skyler employees enjoy many perks. — <span class=\"pos\">[2]</span> —. For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — <span class=\"pos\">[3]</span> —. We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — <span class=\"pos\">[4]</span> —. Annual paid vacations enable a comfortable work-life balance. It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by <i>Travel Vista Journal</i> three years in a row.</p>"],"vi":"Skyler Airlines tuyển dụng hơn 20.000 người đến từ khắp nơi trên thế giới. Chúng tôi đang phát triển nhanh chóng và có nhiều vị trí đang tuyển. — [1] —. Vì vậy, bất kể xuất thân của bạn là gì, có lẽ luôn có một chỗ cho bạn trong đội ngũ của chúng tôi. Nhân viên Skyler được hưởng nhiều phúc lợi. — [2] —. Ví dụ, chương trình giảm giá của chúng tôi cho phép họ bay đến bất kỳ điểm đến nào của chúng tôi với giá chỉ bằng một phần nhỏ giá vé trung bình. — [3] —. Chúng tôi mang lại cơ hội thăng tiến và luân chuyển toàn cầu, hoàn trả học phí, chương trình cố vấn và chế độ đãi ngộ hậu hĩnh. — [4] —. Các kỳ nghỉ phép có lương hằng năm giúp cân bằng công việc và cuộc sống một cách thoải mái. Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp.","qs":[{"n":168,"q":"For whom is the information intended?","qvi":"Thông tin này dành cho ai?","opts":["Skyler Airlines employees","Skyler Airlines customers","Potential journal subscribers","Current job seekers"],"ans":"D","xp":"Câu hỏi suy luận (đối tượng). Bằng chứng: \"We're growing fast and have many positions available.\" và \"there's probably a place for you on our team\" → văn bản giới thiệu việc làm và phúc lợi để thu hút người đang tìm việc. → Chọn (D).\n(A) sai: nhân viên được nhắc đến ở ngôi thứ ba (\"them\"), không phải người đọc. (C) sai: tạp chí chỉ là nơi trao danh hiệu.\n(A) Nhân viên của Skyler Airlines\n(B) Khách hàng của Skyler Airlines\n(C) Những người có thể đăng ký mua tạp chí\n(D) Những người đang tìm việc"},{"n":169,"q":"In the information, what is NOT mentioned as being offered to employees?","qvi":"Trong thông tin, điều gì KHÔNG được nhắc đến là quyền lợi dành cho nhân viên?","opts":["Payment for educational expenses","Free airline tickets","Opportunities for mentoring","Paid days off"],"ans":"B","xp":"Câu hỏi NOT. Đối chiếu từng phương án:\n(A) có: \"tuition reimbursement\" (hoàn trả học phí) = trả chi phí học tập.\n(C) có: \"a mentorship program\" (chương trình cố vấn).\n(D) có: \"Annual paid vacations\" (nghỉ phép có lương hằng năm).\n(B) KHÔNG có: văn bản chỉ nói nhân viên được bay \"for a fraction of the average ticket price\" (với giá bằng một phần nhỏ giá vé) → vé giảm giá, không phải vé miễn phí. → Chọn (B).\n(A) Chi trả chi phí học tập\n(B) Vé máy bay miễn phí\n(C) Cơ hội được cố vấn, kèm cặp\n(D) Ngày nghỉ có lương"},{"n":170,"q":"What is mentioned about Skyler Airlines?","qvi":"Điều gì được đề cập về Skyler Airlines?","opts":["It flies to the most destinations around the world.","It is planning to merge with another airline.","It has been praised by a trade publication.","It has replaced its seats with more comfortable ones."],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"Skyler Airlines was named 'Best Airline to Work For' by Travel Vista Journal three years in a row.\" → được một tạp chí ngành (Travel Vista Journal — tạp chí du lịch) bình chọn = \"praised by a trade publication\". → Chọn (C).\n(A), (B), (D) không được nhắc đến.\n(A) Hãng bay đến nhiều điểm đến nhất thế giới.\n(B) Hãng đang dự định sáp nhập với một hãng hàng không khác.\n(C) Hãng đã được một ấn phẩm chuyên ngành khen ngợi.\n(D) Hãng đã thay ghế bằng loại thoải mái hơn."},{"n":171,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\n\"Our openings cover a broad range of skill sets.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\n\"Các vị trí đang tuyển của chúng tôi bao gồm nhiều nhóm kỹ năng khác nhau.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"A","xp":"Câu hỏi điền câu. Câu cần điền nói về \"openings\" (vị trí còn trống) với nhiều loại kỹ năng. Vị trí [1] đứng ngay sau \"have many positions available\" (openings = positions available) và ngay trước \"So regardless of your background, there's probably a place for you\" — \"So\" (vì vậy) là kết quả hợp lý: vì việc làm đa dạng kỹ năng nên dù bạn xuất thân thế nào cũng có chỗ phù hợp. → Chọn (A).\nCác vị trí [2], [3], [4] nằm trong phần nói về phúc lợi (perks) nên không hợp."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Susan Gowan (9:16 A.M.)</b></p><p>Good morning. The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores. We are on track to send them out next Monday.</p></div><div class=\"msg\"><p><b>Maggie Lorenz (9:17 A.M.)</b></p><p>How do they look?</p></div><div class=\"msg\"><p><b>Susan Gowan (9:20 A.M.)</b></p><p>There are still some missing elements.</p></div><div class=\"msg\"><p><b>Alan Woodson (9:21 A.M.)</b></p><p>We mainly need the information from the user studies that reviewed the headphones for sport use. We should have that report from the research and development office by Wednesday.</p></div><div class=\"msg\"><p><b>Maggie Lorenz (9:22 A.M.)</b></p><p>Yes, let's not overlook that. And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.</p></div><div class=\"msg\"><p><b>Susan Gowan (9:23 A.M.)</b></p><p>Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?</p></div><div class=\"msg\"><p><b>Maggie Lorenz (9:24 A.M.)</b></p><p>Let's try for Thursday afternoon. Then we will still have Friday to make any necessary changes.</p></div><div class=\"msg\"><p><b>Alan Woodson (9:25 A.M.)</b></p><p>Fine by me. I'm free after 2 P.M.</p></div>"],"vi":"Susan Gowan (9:16 sáng): Chào buổi sáng. Bộ slide thuyết trình về dòng tai nghe mới sắp sẵn sàng để gửi đến nhiều cửa hàng đối tác của chúng ta. Chúng ta đang đúng tiến độ để gửi đi vào thứ Hai tới.\n\nMaggie Lorenz (9:17 sáng): Trông chúng thế nào rồi?\n\nSusan Gowan (9:20 sáng): Vẫn còn thiếu một số nội dung.\n\nAlan Woodson (9:21 sáng): Chủ yếu chúng ta cần thông tin từ các nghiên cứu người dùng đánh giá tai nghe khi dùng để chơi thể thao. Chúng ta sẽ nhận được báo cáo đó từ phòng nghiên cứu và phát triển trước thứ Tư.\n\nMaggie Lorenz (9:22 sáng): Đúng vậy, đừng bỏ sót điều đó. Và nếu các bạn lo báo cáo không đến kịp trước thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy gửi gấp cho chúng ta một bản tóm tắt.\n\nSusan Gowan (9:23 sáng): Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả vào slide, ba chúng ta có nên lên lịch chạy thử bài thuyết trình vào thứ Năm hoặc thứ Sáu không?\n\nMaggie Lorenz (9:24 sáng): Hãy cố gắng vào chiều thứ Năm. Như vậy chúng ta vẫn còn thứ Sáu để thực hiện những thay đổi cần thiết.\n\nAlan Woodson (9:25 sáng): Tôi thấy ổn. Tôi rảnh sau 2 giờ chiều.","qs":[{"n":172,"q":"What is indicated about a presentation?","qvi":"Điều gì được nêu về một bài thuyết trình?","opts":["It will be expensive to produce.","It will highlight some best-selling products.","It will be Ms. Gowan's first project.","It will be sent to multiple locations."],"ans":"D","xp":"Câu hỏi chi tiết. Bằng chứng: \"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.\" → slide sẽ được gửi đến nhiều cửa hàng đối tác = \"sent to multiple locations\". → Chọn (D).\n(B) sai: đây là dòng tai nghe MỚI, chưa phải sản phẩm bán chạy. (A), (C) không được nhắc đến.\n(A) Sẽ tốn kém để làm.\n(B) Sẽ giới thiệu nổi bật một số sản phẩm bán chạy.\n(C) Sẽ là dự án đầu tiên của chị Gowan.\n(D) Sẽ được gửi đến nhiều địa điểm."},{"n":173,"q":"At 9:22 A.M., what does Ms. Lorenz imply when she writes, \"let's not overlook that\"?","qvi":"Lúc 9:22 sáng, khi chị Lorenz viết \"let's not overlook that\" (đừng bỏ sót điều đó), chị ấy ngụ ý gì?","opts":["More staff should attend a meeting.","Information from the user studies is important.","The presentation must run smoothly.","Partner stores must be notified about an upcoming report."],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó Alan viết \"We mainly need the information from the user studies that reviewed the headphones for sport use.\" Maggie trả lời \"Yes, let's not overlook that\" (đúng, đừng bỏ qua điều đó) và còn dặn nhắc Matt Harven gửi gấp bản tóm tắt → chị ấy cho rằng thông tin từ nghiên cứu người dùng rất quan trọng. → Chọn (B).\n(A) Nên có thêm nhân viên tham dự một cuộc họp.\n(B) Thông tin từ các nghiên cứu người dùng là quan trọng.\n(C) Bài thuyết trình phải diễn ra suôn sẻ.\n(D) Phải thông báo cho các cửa hàng đối tác về một báo cáo sắp tới."},{"n":174,"q":"Who most likely is Mr. Harven?","qvi":"Anh Harven nhiều khả năng là ai?","opts":["A store manager","An amateur athlete","A product researcher","An advertising executive"],"ans":"C","xp":"Câu hỏi suy luận. Alan nói báo cáo nghiên cứu người dùng sẽ đến \"from the research and development office\" (từ phòng nghiên cứu và phát triển). Maggie nói nếu báo cáo không đến kịp thì \"contact Matt Harven and remind him to expedite a summary to us\" → anh Harven là người phụ trách báo cáo này, tức là người làm nghiên cứu sản phẩm ở phòng R&D. → Chọn (C).\n(B) sai: \"sport use\" chỉ là nội dung nghiên cứu.\n(A) Một quản lý cửa hàng\n(B) Một vận động viên nghiệp dư\n(C) Một nhà nghiên cứu sản phẩm\n(D) Một giám đốc quảng cáo"},{"n":175,"q":"When do the writers plan to meet to review a slide presentation?","qvi":"Những người viết dự định gặp nhau để xem lại bài thuyết trình bằng slide vào khi nào?","opts":["On Monday","On Wednesday","On Thursday","On Friday"],"ans":"C","xp":"Câu hỏi chi tiết. Susan hỏi có nên \"schedule a trial run through the presentation on Thursday or Friday?\" (chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu); Maggie trả lời \"Let's try for Thursday afternoon.\" và Alan đồng ý \"Fine by me.\" → họ sẽ gặp vào thứ Năm. → Chọn (C).\n(A) thứ Hai là ngày gửi slide; (B) thứ Tư là hạn nhận báo cáo; (D) thứ Sáu dành để chỉnh sửa.\n(A) Vào thứ Hai\n(B) Vào thứ Tư\n(C) Vào thứ Năm\n(D) Vào thứ Sáu"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following press release and review.","passages":["<p>Aparna Kothari, Media Contact<br>Kitchen Swifts<br>akothari@kitchenswifts.com.au</p><p><b>FOR IMMEDIATE RELEASE</b></p><p>SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience. The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's. He says his cooking reflects his Filipino heritage, which is a blend of many cultures.</p><p>\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said. \"While preparing and eating these meals, you can feel like you are travelling the world with me.\"</p><p>Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers. Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options, and then a box is delivered weekly. Current customers will see no price increase with the partnership. To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.</p>","<p>https://www.sydneyrestaurants.com.au</p><p>A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney. It is usually fully booked for dinner; you may need to call months in advance for a table. We had a wonderful lunch there instead. Everything was delicious, and the bread and desserts are baked on-site! It was a worthwhile treat before I flew back to Hong Kong.</p><p>—Meili Guan</p>"],"vi":"Aparna Kothari, Phụ trách truyền thông\nKitchen Swifts\nakothari@kitchenswifts.com.au\n\nPHÁT HÀNH NGAY\n\nSYDNEY (4 tháng 6) — Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác với nhau để mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới. Vị đầu bếp từng đoạt giải thưởng này là chủ của các nhà hàng ở cả Philippines và Úc, trong đó có nhà hàng Enriqua's mới khai trương gần đây. Ông cho biết cách nấu ăn của mình thể hiện di sản Philippines của ông, vốn là sự pha trộn của nhiều nền văn hóa.\n\n\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và thú vị,\" ông nói. \"Trong khi chuẩn bị và thưởng thức những bữa ăn này, bạn có thể cảm thấy như đang cùng tôi du lịch khắp thế giới.\"\n\nZahra Chambers, phó chủ tịch của Kitchen Swifts, cho biết bà rất vui được làm việc với Đầu bếp Cordero và mang đến những công thức mới ngon miệng cho khách hàng của họ. Kitchen Swifts cung cấp thực đơn, công thức và nguyên liệu cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay. Khách hàng chọn các món ăn phù hợp nhất, sau đó một hộp hàng sẽ được giao hằng tuần. Khách hàng hiện tại sẽ không bị tăng giá khi có sự hợp tác này. Để tìm hiểu thêm, hãy truy cập trang web của Kitchen Swifts tại www.kitchenswifts.com.au.\n\n---\n\nhttps://www.sydneyrestaurants.com.au\n\nMột đồng nghiệp đã sắp xếp cho chúng tôi ăn tại Enriqua's khi tôi đang dự một hội nghị ở Sydney. Nhà hàng thường kín chỗ vào bữa tối; bạn có thể phải gọi đặt bàn trước nhiều tháng. Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời ở đó. Mọi thứ đều ngon, và bánh mì cùng món tráng miệng được nướng ngay tại chỗ! Đó là một bữa ăn đáng giá trước khi tôi bay về Hồng Kông.\n\n— Meili Guan","qs":[{"n":176,"q":"What is the purpose of the press release?","qvi":"Mục đích của thông cáo báo chí là gì?","opts":["To promote the opening of a restaurant","To announce a business partnership","To introduce a travel program","To congratulate an award recipient"],"ans":"B","xp":"Dạng câu hỏi mục đích. Câu đầu thông cáo: \"Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.\" và đoạn cuối nhắc \"with the partnership\". 'joining together' (hợp tác) = 'business partnership' → chọn (B). (A) sai: Enriqua's chỉ được nhắc thoáng qua là nhà hàng mới mở, không phải mục đích. (C) 'travelling the world' chỉ là cách nói ví von. (D) đầu bếp 'award-winning' nhưng thông cáo không chúc mừng ai.\n(A) Để quảng bá việc khai trương một nhà hàng\n(B) Để thông báo một sự hợp tác kinh doanh\n(C) Để giới thiệu một chương trình du lịch\n(D) Để chúc mừng một người đoạt giải"},{"n":177,"q":"In the press release, the word \"reflects\" in paragraph 1, line 4, is closest in meaning to","qvi":"Trong thông cáo báo chí, từ \"reflects\" ở đoạn 1, dòng 4 gần nghĩa nhất với","opts":["results in","changes","shows","thinks about"],"ans":"C","xp":"Dạng đồng nghĩa. Câu gốc: \"He says his cooking reflects his Filipino heritage\" — cách nấu ăn của ông 'phản ánh / thể hiện' di sản Philippines. 'reflect' ở đây = thể hiện, cho thấy → 'shows' → chọn (C). Lưu ý 'reflect on' mới có nghĩa 'suy ngẫm' (thinks about), nên (D) là bẫy.\n(A) dẫn đến\n(B) thay đổi\n(C) cho thấy, thể hiện\n(D) suy nghĩ về"},{"n":178,"q":"What is indicated about Kitchen Swifts?","qvi":"Điều gì được nêu về Kitchen Swifts?","opts":["It raised its prices for all customers.","It revised its delivery schedule.","It offers several meal options.","It has a new vice president."],"ans":"C","xp":"Dạng chi tiết. Đoạn 3: \"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options\" → công ty có nhiều lựa chọn bữa ăn → chọn (C). (A) sai: \"Current customers will see no price increase\". (B) sai: chỉ nói hộp được giao hằng tuần, không nói thay đổi lịch. (D) sai: Zahra Chambers là phó chủ tịch nhưng không nói là người mới.\n(A) Công ty đã tăng giá cho tất cả khách hàng.\n(B) Công ty đã điều chỉnh lịch giao hàng.\n(C) Công ty cung cấp nhiều lựa chọn bữa ăn.\n(D) Công ty có một phó chủ tịch mới."},{"n":179,"q":"What is most likely true about Ms. Guan?","qvi":"Điều gì nhiều khả năng đúng về cô Guan?","opts":["She went to Mr. Cordero's restaurant.","She recently went to Sydney for a vacation.","She is a colleague of Ms. Chambers.","She regularly orders from Kitchen Swifts."],"ans":"A","xp":"Dạng suy luận, kết hợp 2 bài. Bài đánh giá: \"A colleague arranged for us to eat at Enriqua's\". Thông cáo: Chef Cordero là chủ nhà hàng, \"including the recently opened Enriqua's\" → cô Guan đã ăn ở nhà hàng của ông Cordero → chọn (A). (B) sai: cô đến Sydney dự hội nghị (\"at a conference\"), không phải đi nghỉ. (C), (D) không có thông tin.\n(A) Cô ấy đã đến nhà hàng của ông Cordero.\n(B) Cô ấy gần đây đến Sydney để đi nghỉ.\n(C) Cô ấy là đồng nghiệp của bà Chambers.\n(D) Cô ấy thường xuyên đặt hàng từ Kitchen Swifts."},{"n":180,"q":"What did Ms. Guan suggest about Enriqua's in the review?","qvi":"Cô Guan ngụ ý điều gì về Enriqua's trong bài đánh giá?","opts":["It has a limited lunch menu.","It takes dinner reservations.","It serves bread from a local bakery.","It has a location in Hong Kong."],"ans":"B","xp":"Dạng suy luận. \"It is usually fully booked for dinner; you may need to call months in advance for a table.\" → có thể gọi đặt bàn trước cho bữa tối → nhà hàng nhận đặt chỗ bữa tối → chọn (B). (A) không có thông tin, cô còn khen bữa trưa tuyệt vời. (C) sai: \"the bread and desserts are baked on-site\" (nướng tại chỗ, không mua ở tiệm khác). (D) sai: Hong Kong là nơi cô bay về.\n(A) Nhà hàng có thực đơn bữa trưa hạn chế.\n(B) Nhà hàng nhận đặt chỗ cho bữa tối.\n(C) Nhà hàng phục vụ bánh mì từ một tiệm bánh địa phương.\n(D) Nhà hàng có một chi nhánh ở Hồng Kông."}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following e-mail and ticket.","passages":["<div class=\"hdr\"><p><b>To:</b> laura.savard@orbitmail.scot</p><p><b>From:</b> cboyle@ceoleire.co.uk</p><p><b>Date:</b> 25 May</p><p><b>Subject:</b> RE: Some suggestions</p></div><p>Dear Ms. Savard,</p><p>Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport. Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself. It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.</p><p>As you know, my merchandise is 100 percent handcrafted. If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal. Over the years, I've seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.</p><p>I look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.</p><p>Sincerely,</p><p>Conor Boyle<br>Ceoleire Classics</p>","<h3>Northern Ireland Ferry Service</h3><table><tr><td>Date of Issuance:</td><td>26 May</td></tr><tr><td>Passenger Name:</td><td>Conor Boyle</td></tr></table><table><tr><td>Departing Belfast:</td><td>Friday, 5 June, 1:05 PM</td></tr><tr><td>Docking at Cairnryan:</td><td>Friday, 5 June, 3:20 PM</td></tr></table><table><tr><td>Baggage:</td><td>1 suitcase (small), 2 instrument cases<br>(1 mandolin, 1 guitar)</td></tr><tr><td>Vehicle transport:</td><td>No</td></tr></table><table><tr><td>Adult Standard Class:</td><td>£55.00</td></tr></table><p>Please arrive 30 minutes prior to departure.</p>"],"vi":"Đến: laura.savard@orbitmail.scot\nTừ: cboyle@ceoleire.co.uk\nNgày: 25 tháng 5\nTiêu đề: RE: Một vài đề xuất\n\nKính gửi cô Savard,\n\nCảm ơn cô đã có lời đề nghị chu đáo là hoặc đến lấy đơn hàng trực tuyến tại cửa hàng của tôi, hoặc trả thêm tiền để vận chuyển bằng đường hàng không hay tàu hỏa. Cả hai cách đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng cho cô ở Stranraer. Tình cờ là chị/em gái tôi và các con của cô ấy sống gần đó, ở Kirkcolm. Trước khi đến thăm họ, tôi sẽ lái xe thuê đến nhà cô và trao tận tay hàng cho cô.\n\nNhư cô biết, hàng hóa của tôi được làm thủ công 100%. Nếu có hư hỏng nào xảy ra trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một chuyện tốn kém và mất thời gian. Nhiều năm qua, tôi đã thấy quá nhiều hư hỏng do những nhân viên bốc xếp hành lý cẩu thả gây ra. Chính sách của tôi là tự mình giao hàng bất cứ khi nào có thể, hoặc thuê một dịch vụ chuyển phát đường bộ hoặc đường biển mà tôi tin tưởng.\n\nTôi mong được gặp cô vào ngày 5 tháng 6. Tôi dự kiến đến nhà cô muộn nhất là 5 giờ chiều.\n\nTrân trọng,\n\nConor Boyle\nCeoleire Classics\n\n---\n\nDịch vụ Phà Bắc Ireland\n\nNgày phát hành: 26 tháng 5\nTên hành khách: Conor Boyle\n\nKhởi hành từ Belfast: Thứ Sáu, 5 tháng 6, 1:05 chiều\nCập bến Cairnryan: Thứ Sáu, 5 tháng 6, 3:20 chiều\n\nHành lý: 1 vali (nhỏ), 2 hộp nhạc cụ (1 đàn mandolin, 1 đàn guitar)\nVận chuyển xe: Không\n\nHạng phổ thông người lớn: 55,00 bảng Anh\n\nVui lòng có mặt 30 phút trước giờ khởi hành.","qs":[{"n":181,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To finalize a plan","To accept an invitation","To promote a new service","To request feedback on a policy"],"ans":"A","xp":"Dạng mục đích. Ông Boyle trả lời đề nghị của cô Savard: \"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself\", rồi chốt: \"I look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.\" → e-mail chốt kế hoạch giao hàng → chọn (A). (B) không có lời mời nào; (C) không quảng bá dịch vụ mới; (D) ông nói về chính sách của mình nhưng không xin ý kiến.\n(A) Để chốt một kế hoạch\n(B) Để nhận lời một lời mời\n(C) Để quảng bá một dịch vụ mới\n(D) Để xin ý kiến phản hồi về một chính sách"},{"n":182,"q":"Why will Mr. Boyle travel from Stranraer to Kirkcolm?","qvi":"Tại sao ông Boyle sẽ đi từ Stranraer đến Kirkcolm?","opts":["To make a delivery","To attend a meeting","To drop off a rental car","To visit with family members"],"ans":"D","xp":"Dạng chi tiết. \"It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house\" → giao hàng ở Stranraer trước, rồi đến Kirkcolm thăm chị/em gái và các cháu → 'sister and her children' = 'family members' → chọn (D). (A) là việc ông làm ở Stranraer, không phải ở Kirkcolm.\n(A) Để giao hàng\n(B) Để dự một cuộc họp\n(C) Để trả xe thuê\n(D) Để thăm người thân trong gia đình"},{"n":183,"q":"What is indicated in the e-mail?","qvi":"Điều gì được nêu trong e-mail?","opts":["Mr. Boyle's sister is a cofounder of Ceoleire Classics.","Mr. Boyle has been disappointed by air- and train-freight companies.","Ms. Savard has purchased items from Mr. Boyle in the past.","Ms. Savard prefers a specific brand of luggage."],"ans":"B","xp":"Dạng chi tiết. Cô Savard đề nghị trả thêm \"for air or train transport\" nhưng ông từ chối: \"Over the years, I've seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.\" → ông không hài lòng với vận chuyển đường hàng không/tàu hỏa (chỉ tin dịch vụ đường bộ hoặc đường biển) → chọn (B). (A), (C), (D) không được nhắc đến.\n(A) Chị/em gái ông Boyle là đồng sáng lập Ceoleire Classics.\n(B) Ông Boyle từng thất vọng với các công ty vận chuyển hàng bằng đường hàng không và tàu hỏa.\n(C) Cô Savard từng mua hàng của ông Boyle trước đây.\n(D) Cô Savard thích một thương hiệu hành lý cụ thể."},{"n":184,"q":"What is most likely true about Ms. Savard?","qvi":"Điều gì nhiều khả năng đúng về cô Savard?","opts":["She often travels for her job.","She paid extra to have items hand delivered.","She recently purchased musical instruments.","She will meet Mr. Boyle at the rental car office."],"ans":"C","xp":"Dạng suy luận, kết hợp 2 bài. E-mail: ông Boyle sẽ giao \"your online order\" — hàng thủ công (\"100 percent handcrafted\") — cho cô Savard. Vé phà: hành lý của ông gồm \"2 instrument cases (1 mandolin, 1 guitar)\" → hàng cô đặt là nhạc cụ → chọn (C). (B) sai: ông nói việc trả thêm là không cần thiết và ông tự giao. (D) sai: ông lái xe đến tận nhà cô. (A) không có thông tin.\n(A) Cô ấy thường đi công tác.\n(B) Cô ấy đã trả thêm tiền để được giao hàng tận tay.\n(C) Cô ấy gần đây đã mua nhạc cụ.\n(D) Cô ấy sẽ gặp ông Boyle tại văn phòng cho thuê xe."},{"n":185,"q":"How is Mr. Boyle traveling to Cairnryan on June 5 ?","qvi":"Ông Boyle đi đến Cairnryan vào ngày 5 tháng 6 bằng phương tiện gì?","opts":["By car","By train","By boat","By plane"],"ans":"C","xp":"Dạng chi tiết (bài 2). Vé là của \"Northern Ireland Ferry Service\": \"Departing Belfast: Friday, 5 June, 1:05 PM / Docking at Cairnryan: Friday, 5 June, 3:20 PM\" → ông đi phà (ferry) = tàu thuyền → chọn (C). (A) sai: \"Vehicle transport: No\" — ông không mang xe theo phà (xe thuê chỉ dùng sau khi đến nơi).\n(A) Bằng ô tô\n(B) Bằng tàu hỏa\n(C) Bằng tàu thủy (phà)\n(D) Bằng máy bay"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following advertisement, online forum posting, and outline.","passages":["<h3>Train to Achieve (TTA)—Our classes prepare you to succeed!</h3><p>Profiled in the latest <i>Business Directions Nigeria</i> newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa. By offering our classes entirely in online format, we bring the classroom to your home. All classes include individualized instruction and are taught by recognized professionals in their respective fields. Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé. For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng. The following are some of our most popular classes.</p><p><b>Introduction to Social Media Marketing (TTA1504):</b> Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.</p><p><b>Become a Successful Freelance Writer (TTA3283):</b> Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.</p><p><b>Starting an Internet Radio Station (TTA7629):</b> Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.</p><p><b>Basics of Graphic Design (TTA7633):</b> Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.</p>","<h3>Discussion forum for students enrolled in Train to Achieve Class TTA1504</h3><p><b>Posted on:</b> 21 May, 9:41 A.M. &nbsp;&nbsp; <b>Posted by:</b> Joseph Egbe &nbsp;&nbsp; <b>Subject:</b> Presentations</p><p>Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class. Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice.</p>","<h4>Egbe's Bakery—Unique baked-in flavours in every bite!</h4><ul><li><b>Section 1:</b> Explore our menu and price list</li><li><b>Section 2:</b> Browse photos of our delicious treats</li><li><b>Section 3:</b> Learn about our catering services</li><li><b>Section 4:</b> View lists of ingredients</li></ul>"],"vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi chuẩn bị cho bạn thành công!\n\nĐược giới thiệu trong bản tin Business Directions Nigeria mới nhất, Train to Achieve (TTA) là một trong những đơn vị đào tạo sáng tạo nhất ở Tây Phi. Bằng cách tổ chức các lớp học hoàn toàn dưới hình thức trực tuyến, chúng tôi mang lớp học đến tận nhà bạn. Tất cả các lớp đều có hướng dẫn riêng cho từng cá nhân và được giảng dạy bởi các chuyên gia được công nhận trong lĩnh vực của họ. Khi hoàn thành một lớp học, bạn sẽ nhận được Giấy chứng nhận Đào tạo chính thức, một điểm cộng giá trị cho bất kỳ bản lý lịch nào. Để xem đầy đủ danh sách học phí và lịch học, hãy truy cập trang web của chúng tôi tại www.traintoachieve.org.ng. Sau đây là một số lớp học được yêu thích nhất của chúng tôi.\n\nNhập môn Tiếp thị trên Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp của mình trên mạng.\n\nTrở thành Người viết Tự do Thành công (TTA3283): Cây bút kinh doanh Brenda Akande hướng dẫn chuyên sâu cho bạn cách mài giũa kỹ năng viết và bán dịch vụ viết của mình.\n\nKhởi nghiệp Đài phát thanh Internet (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru chỉ cho bạn cách thu hút thị trường mục tiêu và đưa ra những mẹo thực tế để thiết lập dịch vụ phát sóng.\n\nCơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn có được những kỹ năng cơ bản cần thiết để bắt đầu kinh doanh thiết kế đồ họa.\n\n---\n\nDiễn đàn thảo luận dành cho học viên đăng ký Lớp TTA1504 của Train to Achieve\n\nĐăng lúc: 21 tháng 5, 9:41 sáng   Người đăng: Joseph Egbe   Chủ đề: Bài thuyết trình\n\nKhi xem danh sách học viên đăng ký lớp này, tôi nhớ lại đã trò chuyện với một số bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng Một. Tôi mong được chia sẻ kinh nghiệm học tập với các bạn một lần nữa trong lớp này. Hôm qua tôi là học viên thứ hai gặp ông Akpan trong một buổi họp video riêng về công việc kinh doanh của tôi. Tôi sở hữu một xe tải bán đồ ăn chuyên bán các loại bánh nướng, và khi tôi cho ông Akpan xem dàn ý trang web của mình, ông đề nghị tôi thêm một mục có hình ảnh sinh động về tất cả các loại bánh của tôi. Đó là một lời khuyên hữu ích.\n\n---\n\nTiệm bánh Egbe's — Hương vị nướng độc đáo trong từng miếng bánh!\n• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi\n• Mục 2: Xem ảnh các món bánh ngon của chúng tôi\n• Mục 3: Tìm hiểu về dịch vụ cung cấp tiệc của chúng tôi\n• Mục 4: Xem danh sách nguyên liệu","qs":[{"n":186,"q":"What is indicated about TTA?","qvi":"Điều gì được nêu về TTA?","opts":["It was founded by a graphic designer.","It publishes its own online newsletter.","It offers classes led by industry professionals.","It has classroom facilities in cities across West Africa."],"ans":"C","xp":"Dạng chi tiết. Quảng cáo: \"All classes include individualized instruction and are taught by recognized professionals in their respective fields.\" → 'taught by recognized professionals' = 'led by industry professionals' → chọn (C). (A) Doug Umaru là giảng viên, không phải người sáng lập. (B) TTA được giới thiệu trên bản tin Business Directions Nigeria, không tự phát hành bản tin. (D) sai: lớp học \"entirely in online format\".\n(A) TTA được thành lập bởi một nhà thiết kế đồ họa.\n(B) TTA phát hành bản tin trực tuyến của riêng mình.\n(C) TTA có các lớp học do chuyên gia trong ngành giảng dạy.\n(D) TTA có cơ sở lớp học ở nhiều thành phố khắp Tây Phi."},{"n":187,"q":"According to the advertisement, what does TTA provide to students who finish a class?","qvi":"Theo quảng cáo, TTA cung cấp gì cho học viên hoàn thành một lớp học?","opts":["A résumé-writing workshop","A discount on a follow-up class","A list of current job postings","A certification document"],"ans":"D","xp":"Dạng chi tiết. \"Upon successful completion of a class, you will receive an official Certificate of Training\" → 'Certificate of Training' = 'a certification document' → chọn (D). (A) là bẫy: quảng cáo có nhắc 'résumé' nhưng chỉ nói chứng chỉ là điểm cộng cho lý lịch, không có hội thảo viết lý lịch.\n(A) Một buổi hội thảo viết lý lịch\n(B) Giảm giá cho lớp học tiếp theo\n(C) Danh sách các tin tuyển dụng hiện có\n(D) Một giấy chứng nhận"},{"n":188,"q":"What is most likely true about Mr. Egbe?","qvi":"Điều gì nhiều khả năng đúng về ông Egbe?","opts":["He helped design a discussion forum.","He has previously taken a TTA class.","He develops videoconferencing software.","He recently sold a bakery food truck."],"ans":"B","xp":"Dạng suy luận. Bài đăng: \"I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again\" → ông đã từng học một lớp của TTA (lớp thiết kế áp phích tháng Một) → chọn (B). (D) sai: \"I own a food truck\" — ông vẫn đang sở hữu xe, không bán đi. (A), (C) không có thông tin.\n(A) Ông ấy đã giúp thiết kế một diễn đàn thảo luận.\n(B) Ông ấy từng học một lớp của TTA trước đây.\n(C) Ông ấy phát triển phần mềm họp trực tuyến.\n(D) Ông ấy gần đây đã bán một xe tải bán bánh."},{"n":189,"q":"What TTA class is Mr. Egbe enrolled in?","qvi":"Ông Egbe đang theo học lớp nào của TTA?","opts":["Introduction to Social Media Marketing","Become a Successful Freelance Writer","Starting an Internet Radio Station","Basics of Graphic Design"],"ans":"A","xp":"Dạng chi tiết, kết hợp 2 bài. Tiêu đề diễn đàn: \"Discussion forum for students enrolled in Train to Achieve Class TTA1504\", và ông gặp \"Mr. Akpan\". Quảng cáo: \"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan\" → chọn (A).\n(A) Nhập môn Tiếp thị trên Mạng xã hội\n(B) Trở thành Người viết Tự do Thành công\n(C) Khởi nghiệp Đài phát thanh Internet\n(D) Cơ bản về Thiết kế Đồ họa"},{"n":190,"q":"What section did Mr. Egbe most likely add to the outline after speaking with Mr. Akpan?","qvi":"Ông Egbe nhiều khả năng đã thêm mục nào vào dàn ý sau khi nói chuyện với ông Akpan?","opts":["Section 1","Section 2","Section 3","Section 4"],"ans":"B","xp":"Dạng suy luận, kết hợp 2 bài. Bài đăng: ông Akpan \"suggested that I add a section with vivid images of all my baked goods\". Dàn ý: \"Section 2: Browse photos of our delicious treats\" → 'vivid images of baked goods' = 'photos of our delicious treats' → chọn (B). Mục 1 là thực đơn/bảng giá, mục 3 là dịch vụ tiệc, mục 4 là danh sách nguyên liệu.\n(A) Mục 1\n(B) Mục 2\n(C) Mục 3\n(D) Mục 4"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following article, review, and e-mail.","passages":["<h3>Caribbean Flavours Abound</h3><p><i>By Rebecca Roats</i></p><p>NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now. Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square. The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper. The restaurant is most famous for its jerk chicken. Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.</p><p>If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.</p>","<p>https://www.dinerreviews.co.uk/orangebaykitchen</p><p>Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk</p><p>Orange Bay Kitchen: 2/5 Stars</p><p>After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try. My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band's performance that night had been cancelled. Undeterred, we stayed and both ordered the jerk chicken. While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour. Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry. The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.</p>","<div class=\"hdr\"><p><b>To:</b> tpeterkin@sunmail.co.uk</p><p><b>From:</b> vsmith@orangebaykitchen.co.uk</p><p><b>Date:</b> 24 August</p><p><b>Subject:</b> Your review</p><p><b>Attachment:</b> 0258</p></div><p>Dear Ms. Peterkin,</p><p>Thank you for visiting Orange Bay Kitchen and leaving a review. Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.</p><p>During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation. However, the band will be back performing weekly beginning in September. Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage. I am sure you will find them delightful.</p><p>Sincerely,</p><p>Vea Smith, Owner<br>Orange Bay Kitchen</p>"],"vi":"Hương vị Caribe tràn ngập\nTác giả: Rebecca Roats\n\nNOTTINGHAM (1 tháng 8) — Orange Bay Kitchen đã phục vụ sự hòa quyện của hương vị Jamaica trong bầu không khí Caribe thư thái được sáu tháng nay. Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này là một viên ngọc thơm ngát giữa những cửa hàng và quán ăn nhộn nhịp ở Quảng trường Wester. Nhân viên phục vụ luôn sẵn lòng giúp thực khách lựa chọn trong vô số món ngon của thực đơn phong phú, bao gồm cà ri dê, súp đuôi bò và cá hồng. Nhà hàng nổi tiếng nhất với món gà jerk. Được ướp 24 giờ trước khi nướng và ăn kèm bắp cải hầm và cơm dừa, món ăn này có giá rất hời là 12 bảng.\n\nNếu bạn ghé vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae trực tiếp.\n\n---\n\nhttps://www.dinerreviews.co.uk/orangebaykitchen\n\nĐăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk\n\nOrange Bay Kitchen: 2/5 sao\n\nSau khi đọc một bài báo hết lời khen ngợi Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn thử nơi này. Hôm qua, chồng tôi và tôi đến đó lúc 7 giờ tối, mong được thưởng thức nhạc sống trong bữa tối. Thật không may, buổi biểu diễn của ban nhạc tối hôm đó đã bị hủy. Không nản lòng, chúng tôi ở lại và cả hai đều gọi món gà jerk. Dù vị khói của món gà rất tuyệt, món bắp cải hầm lại nhạt nhẽo. Ngoài ra, khẩu phần nhỏ hơn chúng tôi mong đợi, nên chúng tôi gọi thêm một món khai vị để khỏi phải về nhà mà vẫn đói. Bếp trưởng đã ra xin lỗi và vô cùng dễ mến, nhưng có lẽ chúng tôi sẽ không quay lại sớm.\n\n---\n\nĐến: tpeterkin@sunmail.co.uk\nTừ: vsmith@orangebaykitchen.co.uk\nNgày: 24 tháng 8\nTiêu đề: Bài đánh giá của cô\nTệp đính kèm: 0258\n\nKính gửi cô Peterkin,\n\nCảm ơn cô đã ghé Orange Bay Kitchen và để lại đánh giá. Quản lý của chúng tôi, Keron Deslandes, đã kể thêm cho tôi về chuyến ghé thăm của cô và việc chúng tôi đã không đáp ứng được kỳ vọng của cô tối hôm đó. Xin cô nhận phiếu quà tặng trị giá 20 bảng đính kèm; tôi rất mong cô sẽ cho chúng tôi thêm một cơ hội.\n\nTrong lần cô ghé thăm, ban nhạc của chúng tôi gặp sự cố thiết bị, đó là lý do dẫn đến việc hủy diễn vào phút chót. Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng Chín. Ngoài ra, tôi muốn cô biết rằng Bếp trưởng Adio Brown đã thay đổi gia vị ông dùng cho món bắp cải hầm. Tôi chắc rằng cô sẽ thấy chúng rất tuyệt.\n\nTrân trọng,\n\nVea Smith, Chủ nhà hàng\nOrange Bay Kitchen","qs":[{"n":191,"q":"What does the article mention about Orange Bay Kitchen?","qvi":"Bài báo đề cập điều gì về Orange Bay Kitchen?","opts":["It is currently hiring servers.","It is located on a quiet street.","It has another location in Jamaica.","It opened six months ago."],"ans":"D","xp":"Dạng chi tiết. \"Orange Bay Kitchen has been serving up an infusion of Jamaican flavours ... for six months now.\" (bài báo ngày 1/8) → nhà hàng mở cửa cách đây sáu tháng → chọn (D). (B) sai: nhà hàng nằm \"amid the bustling shops and eateries\" (giữa khu nhộn nhịp). (A) bài nhắc nhân viên phục vụ nhưng không nói tuyển dụng. (C) chỉ nói hương vị Jamaica, không có chi nhánh ở Jamaica.\n(A) Nhà hàng đang tuyển nhân viên phục vụ.\n(B) Nhà hàng nằm trên một con phố yên tĩnh.\n(C) Nhà hàng có một chi nhánh khác ở Jamaica.\n(D) Nhà hàng khai trương sáu tháng trước."},{"n":192,"q":"According to the article, what is the most popular menu item at Orange Bay Kitchen?","qvi":"Theo bài báo, món ăn được ưa chuộng nhất ở Orange Bay Kitchen là gì?","opts":["Red snapper","Oxtail soup","Jerk chicken","Curried goat"],"ans":"C","xp":"Dạng chi tiết. \"The restaurant is most famous for its jerk chicken.\" → 'most famous' ≈ 'most popular' → chọn (C). Các món còn lại (curried goat, oxtail soup, red snapper) chỉ được liệt kê là có trong thực đơn.\n(A) Cá hồng\n(B) Súp đuôi bò\n(C) Gà jerk\n(D) Cà ri dê"},{"n":193,"q":"What is suggested about Ms. Peterkin's visit to Orange Bay Kitchen?","qvi":"Điều gì được ngụ ý về chuyến ghé thăm Orange Bay Kitchen của cô Peterkin?","opts":["She was there on a Friday.","She dined alone.","She requested extra rice.","She ordered dessert."],"ans":"A","xp":"Dạng suy luận, kết hợp 2 bài. Bài báo: \"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.\" Bài đánh giá: \"My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.\" → nhạc sống chỉ có vào tối thứ Sáu, cô đến vì mong nghe nhạc sống → cô đến vào thứ Sáu → chọn (A). (B) sai: cô đi cùng chồng. (C) không nhắc; (D) sai: cô gọi thêm món khai vị (appetiser), không phải tráng miệng.\n(A) Cô ấy đến đó vào một ngày thứ Sáu.\n(B) Cô ấy ăn tối một mình.\n(C) Cô ấy yêu cầu thêm cơm.\n(D) Cô ấy gọi món tráng miệng."},{"n":194,"q":"What is a purpose of the e-mail?","qvi":"Một mục đích của e-mail là gì?","opts":["To answer a question","To offer an apology","To ask for feedback","To confirm a reservation"],"ans":"B","xp":"Dạng mục đích. Bà Smith viết: \"our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.\" và giải thích lý do hủy diễn → thừa nhận lỗi, tặng phiếu quà để bù đắp → mục đích là xin lỗi → chọn (B). Cô Peterkin không đặt câu hỏi nào (A), không xin phản hồi (C), không có đặt chỗ (D).\n(A) Để trả lời một câu hỏi\n(B) Để gửi lời xin lỗi\n(C) Để xin ý kiến phản hồi\n(D) Để xác nhận một đặt chỗ"},{"n":195,"q":"Whom did Ms. Peterkin meet at Orange Bay Kitchen?","qvi":"Cô Peterkin đã gặp ai tại Orange Bay Kitchen?","opts":["Ms. Roats","Mr. Deslandes","Mr. Brown","Ms. Smith"],"ans":"C","xp":"Dạng suy luận, kết hợp 2 bài. Bài đánh giá: \"The head chef came out to apologise and was extremely nice\". E-mail: \"Head Chef Adio Brown has changed the spices...\" → bếp trưởng là ông Brown → chọn (C). (A) Roats là tác giả bài báo; (B) Deslandes là quản lý, chỉ kể lại với bà Smith; (D) Smith là chủ nhà hàng, viết e-mail sau đó.\n(A) Bà Roats\n(B) Ông Deslandes\n(C) Ông Brown\n(D) Bà Smith"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following invoice, notice, and e-mail.","passages":["<h3>Orbys Distributors</h3><p><b>Client:</b> Green Canyon &nbsp;&nbsp;<b>Date:</b> June 10<br><b>Account:</b> 4352-0</p><table><tr><th>Item</th><th>Price</th></tr><tr><td>Garden soil, 33 cubic meters</td><td>$1,170.00</td></tr><tr><td>Crushed gravel, 30 metric tons</td><td>1,710.00</td></tr><tr><td>Decorative stone, 20 metric tons</td><td>1,140.00</td></tr><tr><td>70 paving stones, .6 x .6 meters</td><td>630.00</td></tr><tr><td>Subtotal</td><td>4,650.00</td></tr><tr><td>Discount (10%)</td><td>465.00</td></tr><tr><td>Delivery charge</td><td>350.00</td></tr><tr><td>Grand Total</td><td>4,535.00</td></tr></table><p>Please see the enclosed notice outlining important changes to your billing.</p>","<h3>Orbys Distributors</h3><p>To our valued customers:<br>Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing. Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.</p><p>Rest assured that our long-standing incentives remain in place:</p><ul><li>A 10% discount for orders of more than $4,000</li><li>A 20% discount for charitable organizations</li><li>Free deliveries to locations within 5 miles of one of our supply centers</li><li>Free samples for members of our Frequent Buyer Club</li></ul><p>More information about our transition to electronic invoicing is available on our Web site. Thank you for your support. Orbys Distributors appreciates your business.</p>","<div class=\"hdr\"><p><b>To:</b> Mary Peterson, Billing Department</p><p><b>From:</b> Tanvir Singh, Account Manager</p><p><b>Date:</b> September 12</p><p><b>Subject:</b> Account 1012-4</p></div><p>Hello Mary,</p><p>I received a query today from William Tesoriero at Tesoriero Remodeling. His monthly invoice for August never arrived.</p><p>As you know, Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis. He is also a member of the Frequent Buyer Club. This is a customer we absolutely do not want to lose. I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.</p><p>I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.</p><p>Tanvir</p>"],"vi":"Orbys Distributors\n\nKhách hàng: Green Canyon   Ngày: 10 tháng 6\nTài khoản: 4352-0\n\nMặt hàng — Giá\nĐất trồng vườn, 33 mét khối — 1.170,00 đô la\nĐá dăm, 30 tấn — 1.710,00\nĐá trang trí, 20 tấn — 1.140,00\n70 viên đá lát, 0,6 x 0,6 mét — 630,00\nTạm tính — 4.650,00\nGiảm giá (10%) — 465,00\nPhí giao hàng — 350,00\nTổng cộng — 4.535,00\n\nVui lòng xem thông báo đính kèm nêu những thay đổi quan trọng về việc lập hóa đơn của quý khách.\n\n---\n\nOrbys Distributors\n\nGửi quý khách hàng thân mến:\nHệ thống lập hóa đơn hiện tại của chúng tôi đã được sử dụng kể từ khi Orbys Distributors được thành lập cách đây hơn hai mươi năm. Như một sự nâng cấp rất cần thiết, chúng tôi đang chuyển sang hóa đơn điện tử. Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động mỗi tháng và sẽ được gửi đến địa chỉ e-mail gắn với tài khoản công ty của quý khách.\n\nQuý khách hãy yên tâm rằng các ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:\n• Giảm 10% cho đơn hàng trên 4.000 đô la\n• Giảm 20% cho các tổ chức từ thiện\n• Giao hàng miễn phí đến các địa điểm trong vòng 5 dặm từ một trong các trung tâm cung ứng của chúng tôi\n• Hàng mẫu miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên\n\nThông tin thêm về việc chuyển sang hóa đơn điện tử có trên trang web của chúng tôi. Cảm ơn quý khách đã ủng hộ. Orbys Distributors trân trọng sự hợp tác của quý khách.\n\n---\n\nĐến: Mary Peterson, Phòng Thanh toán\nTừ: Tanvir Singh, Quản lý Tài khoản\nNgày: 12 tháng 9\nTiêu đề: Tài khoản 1012-4\n\nChào Mary,\n\nHôm nay tôi nhận được thắc mắc từ William Tesoriero ở Tesoriero Remodeling. Hóa đơn hằng tháng của ông ấy cho tháng 8 chưa bao giờ được gửi đến.\n\nNhư chị biết, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta. Kể từ khi chúng ta mới mở cửa kinh doanh, ông ấy đã mua hàng của chúng ta đều đặn. Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên. Đây là một khách hàng mà chúng ta tuyệt đối không muốn mất. Tôi đã giải thích với ông ấy rằng việc triển khai hệ thống hóa đơn điện tử đã không suôn sẻ như chúng ta mong đợi và hứa rằng chuyện này sẽ không xảy ra nữa.\n\nTôi sẽ rất cảm kích nếu chị có thể điều tra vấn đề ngay lập tức và gửi hóa đơn tháng 8 cho ông Tesoriero.\n\nTanvir","qs":[{"n":196,"q":"What does the invoice suggest about Green Canyon?","qvi":"Hóa đơn ngụ ý điều gì về Green Canyon?","opts":["It does landscaping projects.","It designs highways.","It repairs old houses.","It operates a farm."],"ans":"A","xp":"Dạng suy luận. Green Canyon mua \"Garden soil\", \"Crushed gravel\", \"Decorative stone\", \"70 paving stones\" (đất trồng vườn, đá dăm, đá trang trí, đá lát) → đây là vật liệu làm cảnh quan sân vườn → chọn (A). (C) 'sửa nhà cũ' gần với Tesoriero Remodeling ở e-mail, không phải Green Canyon.\n(A) Công ty làm các dự án cảnh quan (sân vườn).\n(B) Công ty thiết kế đường cao tốc.\n(C) Công ty sửa chữa nhà cũ.\n(D) Công ty vận hành một trang trại."},{"n":197,"q":"Why most likely did Green Canyon receive a discount on its order dated June 10 ?","qvi":"Nhiều khả năng tại sao Green Canyon được giảm giá cho đơn hàng ngày 10 tháng 6?","opts":["It is a charitable organization.","It belongs to the Frequent Buyer Club.","It spent more than $4,000 on merchandise.","It is located near an Orbys Distributors supply center."],"ans":"C","xp":"Dạng suy luận, kết hợp 2 bài. Hóa đơn: \"Subtotal 4,650.00\", \"Discount (10%) 465.00\". Thông báo: \"A 10% discount for orders of more than $4,000\" → đơn hàng 4.650 đô (> 4.000) và được giảm đúng 10% → chọn (C). (A) tổ chức từ thiện được giảm 20%, không phải 10%. (B) thành viên CLB được hàng mẫu miễn phí, không phải giảm giá. (D) sai: hóa đơn vẫn tính \"Delivery charge 350.00\", nên không ở gần trung tâm cung ứng.\n(A) Công ty là một tổ chức từ thiện.\n(B) Công ty thuộc Câu lạc bộ Khách hàng Thường xuyên.\n(C) Công ty đã chi hơn 4.000 đô la cho hàng hóa.\n(D) Công ty nằm gần một trung tâm cung ứng của Orbys Distributors."},{"n":198,"q":"According to the notice, what is changing at Orbys Distributors?","qvi":"Theo thông báo, điều gì đang thay đổi ở Orbys Distributors?","opts":["Its e-mail address","Its list of incentives","Its invoicing system","Its delivery schedule"],"ans":"C","xp":"Dạng chi tiết. \"Our current invoicing system has been in use since ... we are switching to electronic invoicing.\" → hệ thống lập hóa đơn thay đổi → chọn (C). (B) sai: \"our long-standing incentives remain in place\" (ưu đãi giữ nguyên). (A) hóa đơn sẽ gửi đến e-mail của khách, không phải công ty đổi e-mail.\n(A) Địa chỉ e-mail của công ty\n(B) Danh sách ưu đãi của công ty\n(C) Hệ thống lập hóa đơn của công ty\n(D) Lịch giao hàng của công ty"},{"n":199,"q":"What is suggested about Mr. Tesoriero?","qvi":"Điều gì được ngụ ý về ông Tesoriero?","opts":["He asked to meet with Mr. Singh.","He is interested in employment at Orbys Distributors.","He recently placed an order for some construction machinery.","He has been a customer of Orbys Distributors for about twenty years."],"ans":"D","xp":"Dạng suy luận, kết hợp 2 bài. E-mail: \"Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis.\" Thông báo: Orbys \"was founded over twenty years ago\" → ông là khách hàng từ khi công ty mở cửa, tức khoảng hai mươi năm → chọn (D). (A) ông chỉ gửi thắc mắc, không đề nghị gặp; (B), (C) không có thông tin.\n(A) Ông ấy đề nghị gặp ông Singh.\n(B) Ông ấy muốn xin việc tại Orbys Distributors.\n(C) Ông ấy gần đây đã đặt mua một số máy móc xây dựng.\n(D) Ông ấy đã là khách hàng của Orbys Distributors khoảng hai mươi năm."},{"n":200,"q":"What does Mr. Singh ask Ms. Peterson to do?","qvi":"Ông Singh yêu cầu cô Peterson làm gì?","opts":["Make a bill payment","Solve a problem","Confirm an order","Update an account number"],"ans":"B","xp":"Dạng chi tiết (yêu cầu). \"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.\" → điều tra vấn đề và gửi hóa đơn còn thiếu = giải quyết một vấn đề → chọn (B). Không có yêu cầu thanh toán (A), xác nhận đơn hàng (C) hay cập nhật số tài khoản (D).\n(A) Thanh toán một hóa đơn\n(B) Giải quyết một vấn đề\n(C) Xác nhận một đơn hàng\n(D) Cập nhật số tài khoản"}]}]}};
